window.SWIFT_ENGLISH_EXPANSION = [{"word":"adjust","part":"verb","phonetic":"/əˈdʒʌst/","definition":"To change something slightly so that it works better, fits better, or suits a new situation.","definitionZh":"调整；调节；适应","examples":["You can adjust the seat to make it more comfortable.","She adjusted her plans after the meeting was moved."],"tip":"Often used with “to”: adjust something to a new situation; adjust to a change.","course":"en","breakdown":"Usually describes a small or practical change rather than replacing something completely.","related":"adapt; modify; change","categories":["Actions","Everyday Terms"],"senses":[{"part":"verb — change something","definition":"To make a small change to something, such as a setting, position, or amount.","definitionZh":"对某物作小幅改变，例如调整设置、位置或数量。","examples":["Please adjust the mirror before driving.","He adjusted the volume on the television."]},{"part":"verb — become accustomed","definition":"To become familiar with a new situation or way of living.","definitionZh":"逐渐适应新的情况或生活方式。","examples":["It took me a week to adjust to the new schedule.","Children often adjust quickly to a new school."]}]},{"word":"advise","part":"verb","phonetic":"/ədˈvaɪz/","definition":"To give someone a suggestion or information about what they should do.","definitionZh":"建议；劝告；向……提供意见","examples":["The doctor advised him to get more rest.","I would advise checking the details before you sign."],"tip":"Use “advise someone to do something”. The noun is “advice”, which is uncountable.","course":"en","breakdown":"A verb used when giving guidance; do not confuse it with the noun “advice”.","related":"recommend; suggest; guidance","categories":["Actions","People & Relationships"],"senses":[{"part":"verb","definition":"To recommend what someone should do or give them guidance about a decision.","definitionZh":"就某项决定提出建议，或指导某人应该怎么做。","examples":["Her teacher advised her to practise every day.","We advise customers to keep their receipts."]}]},{"word":"agree","part":"verb","phonetic":"/əˈɡriː/","definition":"To have the same opinion as someone, accept a suggestion, or make a shared decision.","definitionZh":"同意；赞成；达成一致","examples":["I agree with your idea.","They agreed to meet after work."],"tip":"Common patterns include agree with a person or opinion, agree to a plan, and agree on a topic.","course":"en","breakdown":"The verb often appears with a preposition: agree with, agree to, or agree on.","related":"accept; approve; disagree","categories":["Actions","People & Relationships"],"senses":[{"part":"verb — share an opinion","definition":"To have the same opinion or think that something is true.","definitionZh":"持有相同意见，或认为某事属实。","examples":["I agree with you about the importance of practice.","Most people agreed that the road needed repairs."]},{"part":"verb — accept a proposal","definition":"To say yes to a suggestion, request, or arrangement.","definitionZh":"接受某项建议、请求或安排。","examples":["She agreed to help us move.","We agreed on a date for the event."]}]},{"word":"announce","part":"verb","phonetic":"/əˈnaʊns/","definition":"To make information known publicly or officially.","definitionZh":"宣布；公布；通知","examples":["The school announced the exam dates.","They announced that the shop would close early."],"tip":"Often used for news, decisions, events, and official information.","course":"en","breakdown":"An announcement is information that is made known to a group or the public.","related":"declare; inform; announcement","categories":["Actions","Everyday Terms"],"senses":[{"part":"verb","definition":"To tell people information publicly or officially.","definitionZh":"公开或正式地向人们告知信息。","examples":["The company announced a new service.","The winner will be announced tomorrow."]}]},{"word":"apply","part":"verb","phonetic":"/əˈplaɪ/","definition":"To make a formal request for something; to use or put something onto a surface; or to be relevant to a situation.","definitionZh":"申请；应用；涂抹；适用","examples":["She plans to apply for the job.","Apply the cream to clean skin.","This rule applies to every student."],"tip":"Common patterns: apply for a job, apply to a school, apply a rule, and apply something to a surface.","course":"en","breakdown":"The meaning depends on its pattern and object. The noun “application” can mean a request or the use of something.","related":"request; use; put on; application","categories":["Actions","Education","Everyday Terms"],"senses":[{"part":"verb — make a request","definition":"To formally ask to be considered for a job, course, permit, or other opportunity.","definitionZh":"正式提出申请，以获得工作、课程、许可证或其他机会。","examples":["He applied for a position at the museum.","You must apply to the university before June."]},{"part":"verb — put something on","definition":"To spread or place a substance onto a surface.","definitionZh":"将某种物质涂抹或放置在表面上。","examples":["Apply sunscreen before going outside.","She applied a little paint to the wall."]},{"part":"verb — be relevant","definition":"To be true, suitable, or relevant in a particular situation.","definitionZh":"在特定情况下适用、成立或相关。","examples":["The same rule applies to visitors.","This discount does not apply to sale items."]}]},{"word":"attach","part":"verb","phonetic":"/əˈtætʃ/","definition":"To fasten or join one thing to another; to include a file with a message; or to connect importance or meaning to something.","definitionZh":"附上；连接；固定；赋予……重要性","examples":["Please attach the receipt to the form.","I forgot to attach the photo to my email."],"tip":"In digital communication, “attach a file” means include it with an email or message.","course":"en","breakdown":"The object is usually joined, connected, or included with something else.","related":"connect; fasten; include; attachment","categories":["Actions","Everyday Terms","Science & Technology"],"senses":[{"part":"verb — fasten or join","definition":"To connect or fasten one object to another.","definitionZh":"将一个物体连接或固定在另一个物体上。","examples":["Attach the label to the front of the box.","The handle is attached to the door."]},{"part":"verb — include a file","definition":"To add a document, image, or other file to an email or digital message.","definitionZh":"在电子邮件或数字消息中添加文件、图片或其他附件。","examples":["I attached the report to my email.","You can attach up to three files."]}]},{"word":"breathe","part":"verb","phonetic":"/briːð/","definition":"To take air into the lungs and let it out again.","definitionZh":"呼吸；吸气；呼气","examples":["Take a moment to breathe slowly.","It was difficult to breathe in the smoky room."],"tip":"The verb is “breathe” /briːð/; the noun is “breath” /breθ/.","course":"en","breakdown":"A basic life process. Remember the different final sounds and spellings of “breathe” and “breath”.","related":"breath; inhale; exhale","categories":["Actions","Nature & Environment"],"senses":[{"part":"verb","definition":"To draw air into the lungs and release it.","definitionZh":"将空气吸入肺部，再将空气呼出。","examples":["Try to breathe deeply and calmly.","Fish breathe through their gills."]}]},{"word":"calculate","part":"verb","phonetic":"/ˈkælkjuleɪt/","definition":"To find an answer or amount by using mathematics or careful reasoning.","definitionZh":"计算；核算；估算","examples":["Can you calculate the total cost?","The app calculates the distance between two places."],"tip":"The noun is “calculation”; a person who calculates is a “calculator” only when referring to a device or, less commonly, a person.","course":"en","breakdown":"Can refer to exact mathematical work or a reasoned estimate.","related":"count; work out; estimate; calculation","categories":["Actions","Education","Science & Technology"],"senses":[{"part":"verb — work out a number","definition":"To use mathematics to find a number or answer.","definitionZh":"通过数学运算得出数字或答案。","examples":["We calculated the average score.","She calculated how much change she should receive."]},{"part":"verb — estimate","definition":"To judge or estimate an amount, time, or result using available information.","definitionZh":"根据现有信息估算数量、时间或结果。","examples":["They calculated that the journey would take two hours.","The team calculated the likely cost of the repair."]}]},{"word":"cancel","part":"verb","phonetic":"/ˈkænsəl/","definition":"To decide that an event, arrangement, order, or service will not happen or continue.","definitionZh":"取消；撤销；作废","examples":["They cancelled the match because of heavy rain.","I need to cancel my appointment."],"tip":"In American English, “canceled” and “canceling” use one l; British English commonly uses “cancelled” and “cancelling”.","course":"en","breakdown":"Used for plans, bookings, events, orders, and services that are stopped before completion.","related":"call off; withdraw; cancellation","categories":["Actions","Everyday Terms","Activities"],"senses":[{"part":"verb","definition":"To stop a planned event, appointment, or arrangement from taking place.","definitionZh":"使原定的活动、预约或安排不再举行。","examples":["The outdoor concert was cancelled due to rain.","Please cancel my dentist appointment."]},{"part":"verb — end an order or service","definition":"To end or withdraw an order, subscription, or service.","definitionZh":"终止或撤销订单、订阅或服务。","examples":["She cancelled her online order.","You can cancel the membership at any time."]}]},{"word":"celebrate","part":"verb","phonetic":"/ˈseləbreɪt/","definition":"To do something enjoyable or special to show that an important event or achievement matters.","definitionZh":"庆祝；纪念；赞扬","examples":["We celebrated her birthday at home.","The team celebrated its first victory."],"tip":"Commonly used with birthdays, festivals, achievements, and special occasions.","course":"en","breakdown":"Celebrating can involve a party or simply recognising an important event.","related":"celebration; festival; mark; honour","categories":["Actions","Activities","History & Culture"],"senses":[{"part":"verb — mark an occasion","definition":"To do something enjoyable or special because of an event or occasion.","definitionZh":"为了某个事件或节日而举行活动或做特别的事情。","examples":["They celebrate the New Year with their family.","We celebrated our anniversary with dinner."]},{"part":"verb — recognise an achievement","definition":"To publicly show appreciation for a success, person, or achievement.","definitionZh":"公开表达对某项成就、某个人或成功的赞赏。","examples":["The school celebrated the students' achievements.","The town celebrated its local artists."]}]},{"word":"charge","part":"verb / noun","phonetic":"/tʃɑːrdʒ/","definition":"To ask someone to pay money; to put electrical energy into a battery; to accuse someone officially; or the amount of money or responsibility involved.","definitionZh":"收费；充电；指控；费用；负责","examples":["The hotel charges extra for breakfast.","I need to charge my phone.","The shop made no delivery charge."],"tip":"“Charge” has several common meanings. The surrounding words show whether it refers to payment, electricity, an accusation, or responsibility.","course":"en","breakdown":"A highly flexible word used in money, technology, law, and responsibility contexts.","related":"fee; cost; bill; accuse; battery","categories":["Actions","Everyday Terms","Science & Technology"],"senses":[{"part":"verb — ask for payment","definition":"To ask someone to pay a particular amount for a product or service.","definitionZh":"要求某人为产品或服务支付一定金额。","examples":["The café charges five dollars for this drink.","They do not charge for delivery."]},{"part":"verb — supply electricity","definition":"To fill a battery with electrical energy so that a device can be used.","definitionZh":"向电池补充电能，使设备能够使用。","examples":["I charge my phone every night.","The battery takes two hours to charge."]},{"part":"noun — price or fee","definition":"An amount of money that someone must pay for a service or activity.","definitionZh":"某项服务或活动所需支付的金额；费用。","examples":["There is a small service charge.","What is the delivery charge?"]}]},{"word":"chase","part":"verb / noun","phonetic":"/tʃeɪs/","definition":"The act of following someone or something in order to catch or reach them.","definitionZh":"追赶或追逐某人或某物的行为；追逐。","examples":["The dog chased the ball across the garden.","The police chased the stolen car."],"tip":"Can be literal, as in chasing a person, or figurative, as in chasing a dream or goal.","course":"en","breakdown":"Often implies movement toward something that is trying to get away, though it also appears in figurative expressions.","related":"pursue; follow; pursuit","categories":["Actions","Activities"],"senses":[{"part":"verb","definition":"To run or move after someone or something to catch them.","definitionZh":"为了抓住某人或某物而跑动或追赶。","examples":["The children chased each other around the playground.","A cat chased a bird out of the garden."]},{"part":"verb — pursue a goal","definition":"To try hard to achieve or obtain something.","definitionZh":"努力追求或争取某个目标。","examples":["She is chasing her dream of becoming a writer.","He spent years chasing success."]},{"part":"noun","definition":"The act of following someone or something in order to catch or reach them.","definitionZh":"追赶或追逐某人或某物的行为；追逐。","examples":["The chase continued through the narrow streets.","After a long chase, the dog caught the ball."]}]},{"word":"connect","part":"verb","phonetic":"/kəˈnekt/","definition":"To join or link things together; to establish a relationship or communication; or to form a meaningful association.","definitionZh":"连接；联系；接通；建立关联","examples":["Connect the printer to your computer.","The train connects the city with the airport."],"tip":"Common patterns include connect A to B, connect with someone, and connect two ideas.","course":"en","breakdown":"Can describe physical links, digital connections, transport links, or relationships.","related":"join; link; associate; connection","categories":["Actions","People & Relationships","Science & Technology"],"senses":[{"part":"verb — join things","definition":"To attach or link two or more things so that they work together or form one unit.","definitionZh":"将两个或多个事物连接起来，使其共同运作或形成整体。","examples":["Connect the cable to the back of the screen.","A bridge connects the two sides of the river."]},{"part":"verb — communicate or relate","definition":"To communicate with someone or feel that you understand or share something with them.","definitionZh":"与某人交流，或感到彼此理解、有共同之处。","examples":["I connected with several people at the workshop.","The teacher connected the topic to everyday life."]}]},{"word":"continue","part":"verb","phonetic":"/kənˈtɪnjuː/","definition":"To keep doing something or to happen for a longer time without stopping.","definitionZh":"继续；持续；接着进行","examples":["Please continue reading the next page.","The rain continued throughout the night."],"tip":"Use continue doing something or continue to do something; both are common.","course":"en","breakdown":"Indicates that an action or situation carries on rather than ending.","related":"carry on; keep; proceed; continuation","categories":["Actions","Everyday Terms"],"senses":[{"part":"verb — keep doing","definition":"To keep performing an activity without stopping or giving up.","definitionZh":"不停下来或不放弃，继续进行某项活动。","examples":["She continued working after lunch.","You can continue to practise tomorrow."]},{"part":"verb — keep happening","definition":"To remain in progress or keep happening over a period of time.","definitionZh":"在一段时间内仍在进行或持续发生。","examples":["The road continues beyond the village.","The discussion continued for another hour."]}]},{"word":"control","part":"verb / noun","phonetic":"/kənˈtroʊl/","definition":"To direct or manage how something happens; to limit or regulate something; or the power to direct a person, process, or situation.","definitionZh":"控制；管理；支配；控制权","examples":["She controls the lights with a switch.","It is difficult to control traffic during the festival."],"tip":"The noun is usually uncountable when referring to power or management: have control of/over something.","course":"en","breakdown":"Can refer to managing a process, limiting behaviour, or having authority over something.","related":"manage; direct; regulate; authority","categories":["Actions","Everyday Terms","Science & Technology"],"senses":[{"part":"verb — manage or direct","definition":"To decide how an activity, system, or organisation operates.","definitionZh":"决定某项活动、系统或组织如何运作。","examples":["He controls the company's budget.","The pilot controls the aircraft."]},{"part":"verb — limit or regulate","definition":"To keep something within limits or prevent it from becoming too strong or harmful.","definitionZh":"将某事物限制在一定范围内，或防止其变得过强或有害。","examples":["The medicine helps control the pain.","They are trying to control the spread of the fire."]},{"part":"noun","definition":"The power or ability to direct, manage, or limit something.","definitionZh":"指挥、管理或限制某事物的权力或能力。","examples":["She has control over the final decision.","The device gives you control of the room's temperature."]}]},{"word":"convince","part":"verb","phonetic":"/kənˈvɪns/","definition":"To make someone believe that something is true or persuade them to do something.","definitionZh":"使相信；说服；使信服","examples":["He convinced me that the plan was safe.","She convinced her parents to let her travel."],"tip":"Use convince someone that something is true, or convince someone to do something.","course":"en","breakdown":"Focuses on changing someone's belief or opinion; “persuade” often emphasises getting them to take action.","related":"persuade; assure; belief","categories":["Actions","People & Relationships"],"senses":[{"part":"verb — make someone believe","definition":"To cause someone to believe that an idea or statement is true.","definitionZh":"使某人相信某个想法或陈述是真实的。","examples":["The evidence convinced the jury.","I am not convinced that this is the best choice."]},{"part":"verb — persuade someone","definition":"To succeed in getting someone to do something through reasoning or argument.","definitionZh":"通过讲道理或论证成功说服某人做某事。","examples":["We convinced him to join the team.","She convinced her friend to apply for the course."]}]},{"word":"copy","part":"verb / noun","phonetic":"/ˈkɑːpi/","definition":"To make something that is the same as an original; to reproduce information; or a thing made to look or read like another.","definitionZh":"复制；抄写；副本；一份","examples":["Please copy the address into your notebook.","I made a copy of the document."],"tip":"In computing, copy usually means duplicate text, files, or other digital content without removing the original.","course":"en","breakdown":"As a verb, it describes making a duplicate; as a noun, it can mean the duplicate itself.","related":"duplicate; reproduce; imitate; photocopy","categories":["Actions","Education","Science & Technology"],"senses":[{"part":"verb — make a duplicate","definition":"To make another version of a document, file, image, or object.","definitionZh":"制作文件、资料、图像或物品的另一个版本。","examples":["Copy the file to the new folder.","Can you copy this page for me?"]},{"part":"verb — imitate or reproduce","definition":"To do or make something in the same way as another person or example.","definitionZh":"以与他人或范例相同的方式做事或制作某物；模仿。","examples":["The child copied her older sister's movements.","Do not copy another student's answers."]},{"part":"noun","definition":"A thing made to be the same as an original, or one example of a book, document, or file.","definitionZh":"与原件相同的复制品；书籍、文件或档案的一份。","examples":["I need a copy of your passport photo page.","The library has three copies of the book."]}]},{"word":"correct","part":"adjective / verb","phonetic":"/kəˈrekt/","definition":"Right or free from mistakes; or to find and fix an error.","definitionZh":"正确的；准确的；纠正；改正","examples":["Your answer is correct.","Please correct the spelling mistake."],"tip":"The adjective is often pronounced with stress on the second syllable; the verb also means to fix an error.","course":"en","breakdown":"As an adjective it describes something accurate; as a verb it means make something accurate.","related":"right; accurate; fix; correction","categories":["Actions","Education","Everyday Terms"],"senses":[{"part":"adjective","definition":"True, accurate, or free from mistakes.","definitionZh":"真实、准确或没有错误的。","examples":["Make sure you write the correct date.","That is the correct answer."]},{"part":"verb","definition":"To change something that is wrong so that it becomes right or accurate.","definitionZh":"修改错误之处，使其变得正确或准确。","examples":["The teacher corrected my grammar.","Please correct the information on this form."]}]},{"word":"damage","part":"noun / verb","phonetic":"/ˈdæmɪdʒ/","definition":"Physical harm that makes something less useful or valuable; or to cause such harm.","definitionZh":"损坏；损害；破坏","examples":["The storm caused damage to several houses.","Be careful not to damage the screen."],"tip":"“Damage” is usually uncountable when referring to harm: some damage, serious damage. The verb is damage something.","course":"en","breakdown":"Can refer to physical harm, harm to reputation, or a negative effect on health or the environment.","related":"harm; destroy; break; damage","categories":["Actions","Everyday Terms","Nature & Environment"],"senses":[{"part":"noun","definition":"Harm that makes something broken, weaker, or less valuable.","definitionZh":"使某物损坏、变弱或价值降低的伤害。","examples":["The car has minor damage to its door.","Water damage can be expensive to repair."]},{"part":"verb","definition":"To cause physical harm or a negative effect to something or someone.","definitionZh":"对某物或某人造成物理损坏或负面影响。","examples":["Too much sunlight can damage your skin.","The careless move damaged the old table."]}]},{"word":"deliver","part":"verb","phonetic":"/dɪˈlɪvər/","definition":"To take something to a person or place; to give a speech or message; or to produce the result that was promised.","definitionZh":"递送；运送；发表；实现；接生","examples":["The shop delivers groceries to our home.","She delivered a short speech at the event."],"tip":"Common patterns include deliver a package, deliver a speech, and deliver results.","course":"en","breakdown":"The meaning changes with the object: goods are brought, speeches are given, and results are produced.","related":"bring; transport; present; delivery","categories":["Actions","Everyday Terms"],"senses":[{"part":"verb — bring something","definition":"To take goods, letters, or other items to the person or place they are intended for.","definitionZh":"将商品、信件或其他物品送到指定的人或地点。","examples":["The courier delivered the parcel this morning.","They deliver food within five kilometres."]},{"part":"verb — give a speech or message","definition":"To present a speech, statement, or message to an audience.","definitionZh":"向听众发表演讲、声明或传达信息。","examples":["The principal delivered a welcome speech.","He delivered the news calmly."]},{"part":"verb — produce a result","definition":"To do what was promised or expected, especially by achieving a result.","definitionZh":"履行承诺或达到预期，尤指取得成果。","examples":["The new system delivered better results.","The team must deliver the project on time."]}]},{"word":"address","part":"noun / verb","phonetic":"/ˈædres/ (noun), /əˈdres/ (verb)","definition":"The details that identify where someone lives or where something is located; or to speak to someone or deal with a problem.","definitionZh":"地址；称呼；向……讲话；处理（问题）","examples":["Please write your home address on the form.","The manager addressed the team's concerns."],"tip":"As a noun, the stress is usually on the first syllable; as a verb, it is usually on the second.","course":"en","breakdown":"The noun identifies a location; the verb can mean speak to an audience or take action on an issue.","related":"location; residence; speak to; deal with","categories":["Everyday Terms","Places","Actions"],"senses":[{"part":"noun","definition":"The details used to identify the location of a home, building, or other place.","definitionZh":"用于确定住宅、建筑物或其他地点位置的信息。","examples":["I changed my email address last month.","What is the address of the new library?"]},{"part":"verb — speak to","definition":"To speak to a person or group, often formally.","definitionZh":"向某个人或群体讲话，通常较为正式。","examples":["The principal addressed the students at assembly.","She addressed the audience before the performance."]},{"part":"verb — deal with","definition":"To take action to deal with a question, problem, or situation.","definitionZh":"采取行动处理某个问题、疑问或情况。","examples":["We must address the safety concerns.","The report addresses several important issues."]}]},{"word":"age","part":"noun / verb","phonetic":"/eɪdʒ/","definition":"The length of time that a person or thing has existed; or to become older over time.","definitionZh":"年龄；年纪；时代；变老；老化","examples":["What is the age of the building?","Some materials age better than others."],"tip":"Use “at the age of” for a specific age. “Age” can also describe a historical period, as in the Stone Age.","course":"en","breakdown":"Can refer to a person's years, the time something has existed, or a long historical period.","related":"old; young; elderly; era","categories":["Everyday Terms","History & Culture","People & Relationships"],"senses":[{"part":"noun — years lived","definition":"The number of years that a person or animal has lived.","definitionZh":"一个人或动物已经生活的年数；年龄。","examples":["Children of the same age often share interests.","She started learning music at the age of six."]},{"part":"noun — period of history","definition":"A particular period in history or a stage in the development of something.","definitionZh":"历史上的某个时期，或某事物发展过程中的阶段。","examples":["The Bronze Age followed the Stone Age.","We live in the digital age."]},{"part":"verb","definition":"To become older or to change as time passes.","definitionZh":"随着时间推移而变老或发生变化。","examples":["Wine can improve as it ages.","The photograph has aged badly in the sunlight."]}]},{"word":"amount","part":"noun / verb","phonetic":"/əˈmaʊnt/","definition":"A quantity or total of something; or, in the phrase “amount to”, to be equal to or have the effect of something.","definitionZh":"数量；总额；合计为；相当于","examples":["We spent a large amount of money on repairs.","The small changes amount to a major improvement."],"tip":"Use “amount” mainly with uncountable things; use “number” with countable items.","course":"en","breakdown":"The noun refers to quantity; “amount to” is a common verb phrase meaning equal or add up to.","related":"quantity; total; sum; number","categories":["Everyday Terms","Education"],"senses":[{"part":"noun","definition":"A quantity of something, especially something that is not counted as separate items.","definitionZh":"某种事物的数量，尤指不按单个项目计数的事物。","examples":["Add a small amount of salt.","The amount of information was overwhelming."]},{"part":"verb phrase — amount to","definition":"To add up to a particular total, or to have a particular meaning or effect.","definitionZh":"总计达到某个数额，或实际上意味着、构成某种结果。","examples":["The bills amount to more than one hundred dollars.","His actions amounted to a refusal."]}]},{"word":"area","part":"noun","phonetic":"/ˈeriə/","definition":"A particular part of a place, surface, or subject; or the size of a surface measured in square units.","definitionZh":"地区；区域；面积；领域","examples":["This area is popular with tourists.","The room has an area of twenty square metres."],"tip":"“Area” can refer to a physical location, a measured surface, or a subject of knowledge.","course":"en","breakdown":"The context shows whether it means a place, a measurement, or a field of activity.","related":"region; zone; space; field","categories":["Everyday Terms","Places","Education"],"senses":[{"part":"noun — place","definition":"A particular part of a town, country, building, or other location.","definitionZh":"城镇、国家、建筑物或其他地点中的某个区域。","examples":["There are several cafés in this area.","The children played in a quiet area of the park."]},{"part":"noun — size of a surface","definition":"The amount of space covered by a flat surface, measured in square units.","definitionZh":"平面所占的空间大小，以平方单位计算；面积。","examples":["Calculate the area of the triangle.","The garden has an area of fifty square metres."]},{"part":"noun — subject or activity","definition":"A particular subject, skill, or part of someone's work or interest.","definitionZh":"某个特定的学科、技能或工作与兴趣领域。","examples":["Marketing is not my strongest area.","The course covers several areas of science."]}]},{"word":"article","part":"noun","phonetic":"/ˈɑːrtɪkəl/","definition":"A piece of writing in a newspaper, magazine, or website; an item or object; or a word such as “a”, “an”, or “the” in grammar.","definitionZh":"文章；物品；条款；冠词","examples":["I read an interesting article about wildlife.","In English, “a” and “the” are articles."],"tip":"In grammar, English articles are “a”, “an”, and “the”. In publishing, an article is a written piece on a topic.","course":"en","breakdown":"The meaning depends on whether the context is writing, grammar, law, or a general object.","related":"essay; report; item; a; an; the","categories":["Everyday Terms","Education","History & Culture"],"senses":[{"part":"noun — written piece","definition":"A piece of writing about a subject, published in a newspaper, magazine, or online.","definitionZh":"在报纸、杂志或网络上发表的关于某个主题的文章。","examples":["She wrote an article about city transport.","I found the article on the school's website."]},{"part":"noun — grammar","definition":"A word used before a noun to show whether it refers to something specific or general.","definitionZh":"放在名词前，用来表示所指事物是特定还是泛指的词；冠词。","examples":["“An” is used before a vowel sound.","The word “the” is a definite article."]},{"part":"noun — object or item","definition":"An individual object or item, especially one of a group of things.","definitionZh":"单独的一件物品，尤指一组物品中的一件。","examples":["The shop sells household articles.","Each article must be labelled before storage."]}]},{"word":"attention","part":"noun","phonetic":"/əˈtenʃən/","definition":"The act of carefully watching, listening to, or thinking about something; or the interest and notice given to someone or something.","definitionZh":"注意；留心；关注；照料","examples":["Please pay attention to the instructions.","The new design attracted a lot of attention."],"tip":"Common phrases include pay attention to, attract attention, and bring something to someone's attention.","course":"en","breakdown":"Usually uncountable when referring to focus or interest; “attentions” has a different, more formal use.","related":"focus; notice; concentration; care","categories":["Everyday Terms","Education","People & Relationships"],"senses":[{"part":"noun — focus","definition":"The act of concentrating on something by watching, listening, or thinking carefully.","definitionZh":"通过仔细观察、聆听或思考而集中精神；注意力。","examples":["You need to give the speaker your full attention.","The child has difficulty keeping attention in class."]},{"part":"noun — interest or notice","definition":"Interest or public notice given to a person, event, or subject.","definitionZh":"人们对某个人、事件或主题表现出的兴趣或关注。","examples":["The story received international attention.","Her bright jacket attracted attention."]}]},{"word":"average","part":"noun / adjective / verb","phonetic":"/ˈævərɪdʒ/","definition":"A typical level or amount; the result of adding several numbers and dividing by how many there are; or to have a particular amount as a usual result.","definitionZh":"平均数；平均的；普通的；平均达到","examples":["The average score was eighty percent.","This town averages more rain in winter."],"tip":"As a noun in mathematics, the average is commonly the arithmetic mean. As an adjective, it can mean typical or ordinary.","course":"en","breakdown":"Can describe a mathematical value or something typical compared with others.","related":"mean; typical; ordinary; calculate","categories":["Everyday Terms","Education"],"senses":[{"part":"noun — mathematical value","definition":"A number found by adding a group of numbers and dividing the total by the number of values.","definitionZh":"将一组数字相加，再除以数字的个数所得出的数；平均数。","examples":["The average of four and six is five.","Calculate the average of these test scores."]},{"part":"adjective","definition":"Typical or usual when compared with other people or things of the same kind.","definitionZh":"与同类的人或事物相比，具有典型或通常水平的。","examples":["The average adult needs regular sleep.","It was an average performance, not an excellent one."]},{"part":"verb","definition":"To have a particular amount, rate, or result as the usual figure over a period of time.","definitionZh":"在一段时间内通常达到某个数量、比率或结果。","examples":["The team averages two goals per game.","The area averages a high temperature in July."]}]},{"word":"background","part":"noun","phonetic":"/ˈbækɡraʊnd/","definition":"The part behind the main subject; a person's education, experience, or family history; or the conditions that help explain a situation.","definitionZh":"背景；经历；出身；背景资料。","examples":["The photo has a mountain in the background.","She has a background in graphic design."],"tip":"“In the background” can mean physically behind something or happening without being the main focus.","course":"en","breakdown":"Can refer to a visual setting, personal experience, or information that explains a situation.","related":"setting; history; experience; context","categories":["Everyday Terms","People & Relationships","Education"],"senses":[{"part":"noun — behind the main subject","definition":"The part of a picture, scene, or place that is behind the main person or object.","definitionZh":"图像、场景或地点中位于主要人物或物体后面的部分。","examples":["A tree appears in the background of the photograph.","The singer stood in front of a blue background."]},{"part":"noun — personal experience","definition":"A person's education, family history, culture, or previous experience.","definitionZh":"一个人的教育、家庭历史、文化或以往经历。","examples":["Applicants should describe their educational background.","We come from different cultural backgrounds."]},{"part":"noun — context","definition":"Information about earlier events or conditions that helps explain a situation.","definitionZh":"有助于解释某种情况的先前事件或条件信息；背景资料。","examples":["The report provides background to the decision.","I need some background information before the meeting."]}]},{"word":"beginning","part":"noun","phonetic":"/bɪˈɡɪnɪŋ/","definition":"The point at which something starts, or the first part of an event, period, story, or process.","definitionZh":"开始；开端；起初；开头部分","examples":["We are only at the beginning of the project.","Read the beginning of the story again."],"tip":"Often used in “at the beginning of” and “from the beginning”. The verb is “begin”.","course":"en","breakdown":"Refers to the starting point or earliest part of something.","related":"start; opening; first; begin","categories":["Everyday Terms","Education"],"senses":[{"part":"noun — starting point","definition":"The time or point when an event, activity, or process starts.","definitionZh":"事件、活动或过程开始的时间或节点。","examples":["At the beginning of the year, we set new goals.","The beginning of the meeting was delayed."]},{"part":"noun — first part","definition":"The first section of a story, book, period, or sequence.","definitionZh":"故事、书籍、时期或顺序中的第一部分。","examples":["The beginning of the film is quite funny.","I missed the beginning of the lesson."]}]},{"word":"bill","part":"noun / verb","phonetic":"/bɪl/","definition":"A statement showing how much money is owed; a proposed law; a banknote; or to send someone a request for payment.","definitionZh":"账单；法案；纸币；开账单；收费","examples":["Could we have the bill, please?","The restaurant billed us for the extra meal."],"tip":"In restaurants, “bill” is common in British English; “check” is more common in American English.","course":"en","breakdown":"The meaning depends on the context: payment, government, money, or advertising.","related":"invoice; check; fee; law","categories":["Everyday Terms","History & Culture"],"senses":[{"part":"noun — payment statement","definition":"A document or statement showing the amount of money that must be paid.","definitionZh":"列明应付金额的文件或账单。","examples":["The electricity bill arrived yesterday.","Can we have the bill after dessert?"]},{"part":"noun — proposed law","definition":"A proposal for a new law that is discussed by a parliament or other law-making body.","definitionZh":"由议会或其他立法机构讨论的法律提案；法案。","examples":["The bill will be debated next week.","Members voted against the proposed bill."]},{"part":"verb","definition":"To send someone a statement asking them to pay for goods or services.","definitionZh":"向某人发送账单，要求其支付商品或服务费用。","examples":["The hotel billed the company directly.","We will bill you at the end of the month."]}]},{"word":"bit","part":"noun","phonetic":"/bɪt/","definition":"A small piece or amount of something; an informal short period; or a unit of information in computing.","definitionZh":"一点；少量；小块；短时间；比特","examples":["Would you like a bit of cake?","Wait a bit and I will be ready."],"tip":"“A bit” often means a little. In computing, a bit is the smallest basic unit of digital information.","course":"en","breakdown":"A flexible informal word for a small amount, a short time, or a digital unit.","related":"piece; little; small amount; byte","categories":["Everyday Terms","Science & Technology"],"senses":[{"part":"noun — small piece or amount","definition":"A small piece, part, or quantity of something.","definitionZh":"某物的一小块、一部分或少量。","examples":["He broke off a bit of chocolate.","There is a bit of water left in the bottle."]},{"part":"noun — short time","definition":"An informal word for a short period of time.","definitionZh":"短时间；片刻。","examples":["Stay here for a bit.","I will be back in a little bit."]},{"part":"noun — computing","definition":"A basic unit of digital information that can have a value of zero or one.","definitionZh":"数字信息的基本单位，其值可以是零或一；比特。","examples":["A byte contains eight bits.","The file stores one bit of information for each setting."]}]},{"word":"bottom","part":"noun / adjective","phonetic":"/ˈbɑːtəm/","definition":"The lowest part of something; the surface or side underneath; or the lowest position in a ranking or list.","definitionZh":"底部；底端；底层；最下面的；末位的","examples":["Your shoes are at the bottom of the stairs.","The team finished at the bottom of the table."],"tip":"Common phrases include at the bottom of, from top to bottom, and bottom line.","course":"en","breakdown":"Usually identifies the lowest part or position, physically or figuratively.","related":"base; lower; top; underneath","categories":["Everyday Terms","Places"],"senses":[{"part":"noun — lowest part","definition":"The lowest part or end of an object, container, or place.","definitionZh":"物体、容器或地点最低的部分或末端。","examples":["There is a small hole at the bottom of the bag.","The village lies at the bottom of the hill."]},{"part":"noun — lowest position","definition":"The lowest position in a list, ranking, or situation.","definitionZh":"名单、排名或某种情况中的最低位置。","examples":["Our team was at the bottom of the league.","The price has reached the bottom of its range."]},{"part":"adjective","definition":"Located at the lowest part or end of something.","definitionZh":"位于某物最下面部分或末端的。","examples":["Open the bottom drawer.","The bottom shelf is easier for children to reach."]}]},{"word":"budget","part":"noun / verb / adjective","phonetic":"/ˈbʌdʒɪt/","definition":"A plan for how money will be earned and spent; the amount of money available for a purpose; or to plan spending within that amount.","definitionZh":"预算；经费；编制预算；经济型的","examples":["We need to stay within our monthly budget.","They budgeted carefully for the trip."],"tip":"Common phrases include on a budget, budget for something, and within budget.","course":"en","breakdown":"Can refer to a spending plan, the available amount of money, or the act of planning expenses.","related":"plan; allowance; expense; finance","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A plan showing how money will be received and spent over a period of time.","definitionZh":"说明一段时间内收入和支出安排的计划；预算。","examples":["The school has a limited budget for new books.","We made a budget for our holiday."]},{"part":"verb","definition":"To plan how much money can be spent and make sure spending stays within that limit.","definitionZh":"规划可支出的金额，并确保花费不超过限额。","examples":["You should budget for transport and food.","They budgeted carefully before buying a car."]},{"part":"adjective","definition":"Designed or sold to be relatively inexpensive.","definitionZh":"为价格相对低廉而设计或销售的；经济型的。","examples":["We stayed in a budget hotel.","The company offers a budget version of the device."]}]},{"word":"cause","part":"noun / verb","phonetic":"/kɔːz/","definition":"A person, event, or thing that makes something happen; a reason for a result; or to make something happen.","definitionZh":"原因；起因；事业；导致；引起","examples":["What was the cause of the delay?","Heavy rain caused the road to flood."],"tip":"The noun “cause” often answers why something happened; the verb “cause” is followed by an effect.","course":"en","breakdown":"Distinguish the reason for an event from the action of making that event happen.","related":"reason; source; result; lead to","categories":["Everyday Terms","Education"],"senses":[{"part":"noun — reason","definition":"The person, event, or condition that makes something happen.","definitionZh":"促使某事发生的人、事件或条件；原因。","examples":["The cause of the fire is still unknown.","Lack of sleep was the main cause of his tiredness."]},{"part":"noun — social purpose","definition":"An aim, belief, or organisation that people support because they think it is important.","definitionZh":"人们认为重要并愿意支持的目标、信念或组织；事业。","examples":["She works for a good cause.","The group raised money for the environmental cause."]},{"part":"verb","definition":"To make something happen, especially something that produces a result or problem.","definitionZh":"使某事发生，尤指造成某种结果或问题。","examples":["The broken pipe caused serious damage.","His comment caused confusion."]}]},{"word":"chance","part":"noun / verb","phonetic":"/tʃæns/","definition":"The possibility that something may happen; an opportunity to do something; or to do something despite uncertainty.","definitionZh":"机会；可能性；运气；冒险做某事","examples":["There is a good chance of rain tomorrow.","This is your chance to ask a question."],"tip":"Common phrases include by chance, take a chance, and have a chance of doing something.","course":"en","breakdown":"Can refer to probability, an opportunity, or an action taken without certainty.","related":"opportunity; possibility; risk; luck","categories":["Everyday Terms","Activities"],"senses":[{"part":"noun — possibility","definition":"The likelihood or possibility that something will happen.","definitionZh":"某事发生的可能性。","examples":["There is a chance that the train will be late.","What are the chances of winning?"]},{"part":"noun — opportunity","definition":"A suitable time or opportunity to do something.","definitionZh":"做某事的合适时机或机会。","examples":["I never had a chance to say goodbye.","She got a chance to study abroad."]},{"part":"verb","definition":"To do or experience something when the result is uncertain, often involving risk.","definitionZh":"在结果不确定时做某事或尝试某事，通常带有风险。","examples":["I wouldn't chance driving in this storm.","He chanced upon an old friend at the market."]}]},{"word":"contact","part":"noun / verb","phonetic":"/ˈkɑːntækt/ (noun), /kənˈtækt/ (verb)","definition":"Communication with someone; a person you know who may help you; or to communicate with or touch someone or something.","definitionZh":"联系；接触；联系人；联络；联系某人","examples":["Please contact the office if you have any questions.","I keep in contact with my former classmates."],"tip":"As a noun, “contact” often means communication or a person you can reach. As a verb, it means get in touch with someone.","course":"en","breakdown":"Can refer to communication, a useful person, physical touching, or the act of getting in touch.","related":"communication; connection; reach; touch","categories":["Everyday Terms","People & Relationships"],"senses":[{"part":"noun — communication","definition":"The act of communicating or keeping in touch with a person or organisation.","definitionZh":"与某人或某个机构沟通或保持联系的行为。","examples":["You can make contact by email.","We lost contact after graduation."]},{"part":"noun — person","definition":"A person you know who may provide information, help, or an introduction.","definitionZh":"可能提供信息、帮助或引荐的熟人；联系人。","examples":["She has a contact at the travel agency.","I asked my business contacts for advice."]},{"part":"verb","definition":"To communicate with someone by phone, email, message, or another method.","definitionZh":"通过电话、电子邮件、消息或其他方式与某人联系。","examples":["Please contact me when you arrive.","The school contacted every parent."]}]},{"word":"claim","part":"noun / verb","phonetic":"/kleɪm/","definition":"To say that something is true, often without having proved it; to ask officially for something you have a right to; or a statement that something is true.","definitionZh":"声称；宣称；索取；索赔；主张","examples":["He claims that he saw the accident.","You can claim a refund with the receipt."],"tip":"A claim is an assertion or formal request. “Claim that” introduces a statement; “claim for” often relates to compensation.","course":"en","breakdown":"Can describe an unproven statement, a request for something owed, or the statement itself.","related":"assert; state; request; demand","categories":["Everyday Terms","Actions"],"senses":[{"part":"verb — say something is true","definition":"To state that something is true, especially when it has not yet been proved.","definitionZh":"表示某事属实，尤指尚未得到证实的说法。","examples":["The company claims that its product is safer.","She claimed she had never met him."]},{"part":"verb — ask for something owed","definition":"To formally ask for money, property, or a benefit that you believe you have a right to receive.","definitionZh":"正式要求获得自己认为有权得到的金钱、财产或福利。","examples":["You can claim travel expenses from your employer.","He claimed a refund for the damaged item."]},{"part":"noun","definition":"A statement that something is true, or a formal request for money or a right.","definitionZh":"关于某事属实的陈述；或正式提出的金钱、权利请求。","examples":["The report makes a surprising claim.","She submitted an insurance claim."]}]},{"word":"class","part":"noun / verb","phonetic":"/klæs/","definition":"A group of students taught together; a lesson or course; a category of people or things; or a level of quality or social position.","definitionZh":"班级；课程；类别；等级；社会阶层","examples":["Our class starts at nine.","The museum has a large collection of objects from this class."],"tip":"“Class” can refer to a school group, a lesson, a category, or social class. “Class” as a verb is less common and means to classify.","course":"en","breakdown":"Its meaning depends on education, classification, social structure, or quality.","related":"lesson; group; category; course","categories":["Everyday Terms","Education","People & Relationships"],"senses":[{"part":"noun — student group or lesson","definition":"A group of students who learn together, or a period of teaching.","definitionZh":"一起学习的一组学生；或一段授课时间。","examples":["There are twenty students in my class.","We have an English class every Monday."]},{"part":"noun — category","definition":"A group of people or things that share similar features.","definitionZh":"具有相似特征的一组人或事物；类别。","examples":["This class of machine is very reliable.","The library has a separate class for reference books."]},{"part":"noun — social or quality level","definition":"A division of society based on economic or social position, or a level of quality.","definitionZh":"根据经济或社会地位划分的社会群体；或质量等级。","examples":["The novel explores differences between social classes.","She showed great class under pressure."]},{"part":"verb","definition":"To place someone or something in a particular group or category.","definitionZh":"将某人或某物归入特定群体或类别；分类。","examples":["The material is classed as hazardous.","Researchers class the samples by age."]}]},{"word":"condition","part":"noun / verb","phonetic":"/kənˈdɪʃən/","definition":"The state that a person or thing is in; a rule that must be met; or to train someone or prepare something for a particular situation.","definitionZh":"状况；状态；条件；使适应；训练","examples":["The car is in excellent condition.","You can borrow the book on one condition."],"tip":"Common phrases include in good condition, on condition that, and under certain conditions.","course":"en","breakdown":"Can refer to a state, a requirement, or the process of preparing or training.","related":"state; situation; requirement; prepare","categories":["Everyday Terms","Education"],"senses":[{"part":"noun — state","definition":"The physical or general state that a person, object, or place is in.","definitionZh":"人、物品或地点所处的身体或总体状态。","examples":["The house is still in good condition.","Her condition improved after treatment."]},{"part":"noun — requirement","definition":"A rule, fact, or situation that must exist or be accepted for something else to happen.","definitionZh":"某事发生前必须存在或接受的规则、事实或情况；条件。","examples":["You can join on the condition that you follow the rules.","The offer is subject to certain conditions."]},{"part":"verb","definition":"To train or prepare a person or animal, or to treat something so that it is suitable for use.","definitionZh":"训练或使人、动物做好准备；或处理某物，使其适合使用。","examples":["The athletes conditioned their bodies for the race.","Use a product to condition dry hair."]}]},{"word":"connection","part":"noun","phonetic":"/kəˈnekʃən/","definition":"A link between people, places, ideas, or devices; a relationship or association; or a transport service that allows a journey to continue.","definitionZh":"连接；联系；关系；转乘；接驳","examples":["There is a strong connection between sleep and health.","We missed our train connection."],"tip":"“Connection” can be physical, social, logical, digital, or related to travel.","course":"en","breakdown":"The noun form of “connect”; it describes a link or relationship rather than the act of joining.","related":"link; relationship; contact; connect","categories":["Everyday Terms","People & Relationships","Science & Technology","Places"],"senses":[{"part":"noun — link or relationship","definition":"A relationship or association between people, things, ideas, or events.","definitionZh":"人与人、事物、想法或事件之间的关系或关联。","examples":["There is a connection between diet and health.","They discovered a connection between the two cases."]},{"part":"noun — physical or digital link","definition":"A physical or electronic link that allows devices, systems, or places to communicate or work together.","definitionZh":"使设备、系统或地点能够通信或共同运作的实体或电子连接。","examples":["Check the internet connection before the call.","The cable provides a connection to the monitor."]},{"part":"noun — travel transfer","definition":"A service or route that allows a passenger to continue a journey by changing trains, buses, or planes.","definitionZh":"乘客通过更换火车、巴士或飞机继续行程的接驳或转乘服务。","examples":["We have a forty-minute connection in Singapore.","The airport connection was cancelled."]}]},{"word":"bake","part":"verb","phonetic":"/beɪk/","definition":"To cook food using dry heat in an oven.","definitionZh":"烘焙；烤制","examples":["We baked a cake for her birthday.","Bake the bread until the crust turns golden."],"tip":"Commonly used for bread, cakes, biscuits, and other foods cooked in an oven.","course":"en","breakdown":"Baking usually uses an oven; it is different from frying food in a pan.","related":"oven; roast; cake; pastry","categories":["Activities","Everyday Terms"],"senses":[{"part":"verb","definition":"To cook food in an oven using dry heat.","definitionZh":"利用烤箱中的干热烹调食物。","examples":["She likes to bake cookies on weekends.","Bake the potatoes for forty minutes."]}]},{"word":"camp","part":"noun / verb","phonetic":"/kæmp/","definition":"A place where people stay in temporary shelters; or to live outdoors in a tent or other temporary shelter.","definitionZh":"营地；露营；扎营","examples":["We set up camp beside the lake.","The children are going to camp in the forest."],"tip":"“Go camping” is the common expression for taking a trip to stay outdoors in a tent.","course":"en","breakdown":"Can refer to the temporary place itself or the activity of staying there.","related":"tent; campsite; outdoors; camping","categories":["Activities","Places","Nature & Environment"],"senses":[{"part":"noun","definition":"A place where people stay in tents or temporary buildings, often outdoors.","definitionZh":"人们在户外搭帐篷或临时建筑居住的地方；营地。","examples":["The campsite has clean showers.","Their camp was near the river."]},{"part":"verb","definition":"To stay outdoors in a tent or temporary shelter for a period of time.","definitionZh":"在户外帐篷或临时住所中停留一段时间；露营。","examples":["We camped in the mountains for two nights.","They camp beside the beach every summer."]}]},{"word":"chat","part":"noun / verb","phonetic":"/tʃæt/","definition":"An informal conversation; or to talk with someone in a friendly and relaxed way.","definitionZh":"闲聊；聊天；谈话","examples":["We had a quick chat after class.","I like to chat with my neighbours."],"tip":"“Chat” is informal. The past tense and past participle are “chatted”.","course":"en","breakdown":"Usually describes relaxed conversation rather than a formal discussion.","related":"talk; conversation; message; discuss","categories":["Activities","People & Relationships","Science & Technology"],"senses":[{"part":"noun","definition":"An informal conversation between people.","definitionZh":"人们之间轻松、非正式的交谈。","examples":["Let's have a chat over coffee.","I had a friendly chat with my new colleague."]},{"part":"verb","definition":"To talk to someone in a relaxed and informal way.","definitionZh":"以轻松、非正式的方式与某人交谈。","examples":["They chatted for an hour.","We often chat online after work."]}]},{"word":"climb","part":"verb / noun","phonetic":"/klaɪm/","definition":"To move upward using the hands and feet, or to go up something such as a hill or ladder; an act of climbing.","definitionZh":"攀爬；爬上；上升；攀登","examples":["The children climbed the tree carefully.","We climbed to the top of the hill."],"tip":"Use climb a ladder or climb up a hill. The noun can refer to the activity or a difficult upward route.","course":"en","breakdown":"Usually describes upward movement, whether by using the body or travelling along a rising route.","related":"crawl; scale; hike; ascent","categories":["Activities","Nature & Environment"],"senses":[{"part":"verb — move upward","definition":"To move up or over something using the hands, feet, or body.","definitionZh":"利用手、脚或身体向上移动或越过某物。","examples":["The cat climbed onto the roof.","He climbed over the wall."]},{"part":"verb — rise","definition":"To increase or move to a higher level or position.","definitionZh":"增加或移动到更高的水平或位置。","examples":["Temperatures climbed during the afternoon.","The price of fuel continues to climb."]},{"part":"noun","definition":"An act or journey involving movement upward, especially one that is difficult.","definitionZh":"向上移动或攀登的过程，尤指较为困难的攀爬。","examples":["The final climb was steep and tiring.","It is a long climb to the mountain shelter."]}]},{"word":"draw","part":"verb / noun","phonetic":"/drɔː/","definition":"To make a picture or mark with a pen or pencil; to pull something toward you; or to cause people or things to come toward a place.","definitionZh":"画；绘制；拉；吸引；抽取","examples":["She likes to draw animals.","Draw the curtains before you go to bed."],"tip":"The past tense and past participle are “drew” and “drawn”. The word also has specialised meanings in sport and games.","course":"en","breakdown":"A common verb with several meanings. Context distinguishes making an image, pulling, attracting, and selecting.","related":"sketch; paint; pull; attract","categories":["Activities","Education","Actions"],"senses":[{"part":"verb — make a picture","definition":"To create a picture or design using a pen, pencil, or another tool.","definitionZh":"使用钢笔、铅笔或其他工具创作图画或设计。","examples":["The student drew a map of the town.","Can you draw a simple flower?"]},{"part":"verb — pull","definition":"To move something toward yourself or in a particular direction by pulling it.","definitionZh":"通过拉动使某物朝自己或某个方向移动。","examples":["Draw your chair closer to the table.","He drew the door open."]},{"part":"verb — attract","definition":"To attract attention, interest, or people toward something.","definitionZh":"吸引注意力、兴趣或人们前往某处。","examples":["The festival draws visitors from many countries.","Her talk drew a large audience."]},{"part":"noun","definition":"A result in a game or competition in which neither side wins; a tie.","definitionZh":"比赛中双方均未获胜的结果；平局。","examples":["The match ended in a draw.","Neither team was satisfied with the draw."]}]},{"word":"exercise","part":"noun / verb","phonetic":"/ˈeksərsaɪz/","definition":"Physical activity done to improve health or strength; a task done to develop a skill; or to use a right, power, or ability.","definitionZh":"运动；锻炼；练习；行使（权利或权力）","examples":["Regular exercise is good for your health.","Complete the exercise on page ten."],"tip":"“Exercise” is usually uncountable when referring to physical activity, but a specific task can be “an exercise”.","course":"en","breakdown":"Can mean physical training, a learning task, or the use of a right or skill.","related":"workout; practise; training; activity","categories":["Activities","Education","Everyday Terms"],"senses":[{"part":"noun — physical activity","definition":"Physical activity done to keep the body healthy or make it stronger.","definitionZh":"为了保持身体健康或增强体能而进行的身体活动。","examples":["Walking is a simple form of exercise.","She does exercise three times a week."]},{"part":"noun — practice task","definition":"A task designed to help someone practise or develop a skill.","definitionZh":"帮助某人练习或培养技能的任务。","examples":["The teacher gave us a grammar exercise.","Try the listening exercise again."]},{"part":"verb — use a right or ability","definition":"To use a right, power, or ability that you have.","definitionZh":"使用自己拥有的权利、权力或能力。","examples":["Citizens can exercise their right to vote.","The manager must exercise good judgement."]}]},{"word":"fish","part":"noun / verb","phonetic":"/fɪʃ/","definition":"An animal that lives in water and breathes through gills; or to try to catch fish.","definitionZh":"鱼；鱼类；钓鱼；捕鱼","examples":["We saw colourful fish in the aquarium.","They fish in the lake every weekend."],"tip":"The usual plural is “fish”; “fishes” is sometimes used when referring to different species.","course":"en","breakdown":"Can refer to the animal or the activity of catching fish.","related":"seafood; fishing; aquarium; catch","categories":["Activities","Nature & Environment"],"senses":[{"part":"noun","definition":"An animal that lives in water, has gills, and usually has fins.","definitionZh":"生活在水中、用鳃呼吸且通常有鳍的动物；鱼。","examples":["A goldfish can live in a home aquarium.","Many fish live near coral reefs."]},{"part":"verb","definition":"To try to catch fish, usually with a rod, line, net, or trap.","definitionZh":"通常使用鱼竿、鱼线、渔网或陷阱尝试捕捉鱼类。","examples":["My grandfather likes to fish by the river.","They went fishing early in the morning."]}]},{"word":"garden","part":"noun / verb","phonetic":"/ˈɡɑːrdən/","definition":"An area of land where flowers, plants, or vegetables are grown; or to work in such an area.","definitionZh":"花园；菜园；园艺；种植","examples":["She grows herbs in the garden.","My parents garden together every Sunday."],"tip":"In British English, “garden” often means the outdoor area next to a home; American English often uses “yard” for this space.","course":"en","breakdown":"Can refer to the planted area or the activity of caring for it.","related":"yard; flowerbed; plant; gardening","categories":["Places","Activities","Nature & Environment"],"senses":[{"part":"noun","definition":"An area near a house or in a public place where flowers, plants, or vegetables are grown.","definitionZh":"在住宅附近或公共场所种植花卉、植物或蔬菜的区域；花园或菜园。","examples":["The children played in the garden.","There is a small vegetable garden behind the house."]},{"part":"verb","definition":"To grow and care for plants as an activity.","definitionZh":"通过种植和照料植物进行园艺活动。","examples":["She gardens to relax after work.","They garden together at the weekend."]}]},{"word":"hike","part":"noun / verb","phonetic":"/haɪk/","definition":"A long walk in the countryside or mountains, usually for enjoyment or exercise; or to go on such a walk.","definitionZh":"远足；徒步旅行；徒步行走","examples":["We went on a hike through the forest.","They plan to hike up the mountain tomorrow."],"tip":"A hike is usually longer or more challenging than an ordinary walk.","course":"en","breakdown":"Usually refers to walking outdoors over a longer distance, often on natural trails.","related":"walk; trek; trail; hiking","categories":["Activities","Nature & Environment"],"senses":[{"part":"noun","definition":"A long walk, especially in the countryside or mountains, taken for enjoyment or exercise.","definitionZh":"尤指在乡村或山区进行的长距离步行，通常为了休闲或锻炼；远足。","examples":["The hike took us three hours.","We packed water and snacks for the hike."]},{"part":"verb","definition":"To take a long walk in the countryside or mountains.","definitionZh":"在乡村或山区进行长距离步行；徒步远足。","examples":["They hiked along the coastal trail.","We hiked to a waterfall during the holiday."]}]},{"word":"jog","part":"verb / noun","phonetic":"/dʒɑːɡ/","definition":"To run slowly and steadily, usually for exercise; or a period of this activity.","definitionZh":"慢跑；轻推；慢跑一段时间","examples":["I jog around the park every morning.","A short jog helps me wake up."],"tip":"The forms are jog, jogs, jogged, and jogging; the final consonant is doubled before -ed and -ing.","course":"en","breakdown":"A jog is slower and less intense than a fast run.","related":"run; exercise; jogging; sprint","categories":["Activities"],"senses":[{"part":"verb — run slowly","definition":"To run at a slow, steady speed, especially as a form of exercise.","definitionZh":"以缓慢、稳定的速度跑步，尤指作为一种锻炼方式；慢跑。","examples":["She jogs for twenty minutes after work.","We jogged along the beach at sunrise."]},{"part":"noun","definition":"A period of slow, steady running for exercise.","definitionZh":"为了锻炼而进行的一段缓慢、稳定的跑步；慢跑。","examples":["Let's go for a short jog.","He went for a jog before breakfast."]}]},{"word":"knit","part":"verb / noun","phonetic":"/nɪt/","definition":"To make clothing or other items by joining loops of yarn with knitting needles; or a piece of knitted fabric.","definitionZh":"编织；针织；织物","examples":["My aunt taught me to knit a scarf.","She knitted a warm hat for the baby."],"tip":"The past tense is “knitted” or “knit”; “knitted” is common in everyday use.","course":"en","breakdown":"Usually refers to making fabric by forming connected loops of yarn.","related":"sew; crochet; wool; knitting","categories":["Activities","Everyday Terms"],"senses":[{"part":"verb","definition":"To make clothing or fabric by using needles to form connected loops of yarn.","definitionZh":"使用织针将纱线编成相互连接的线圈，以制作衣物或织物。","examples":["He learned to knit from his grandmother.","She knits socks during the winter."]},{"part":"noun","definition":"A knitted piece of clothing or fabric.","definitionZh":"针织制品或针织面料。","examples":["The shop sells soft cotton knits.","This knit is warm but lightweight."]}]},{"word":"paint","part":"noun / verb","phonetic":"/peɪnt/","definition":"A coloured liquid or substance used to cover or decorate a surface; or to create a picture by applying it.","definitionZh":"油漆；颜料；绘画；涂漆","examples":["We need more paint for the bedroom wall.","He likes to paint landscapes."],"tip":"“Paint” can mean the material or the activity. A person who paints pictures is a painter.","course":"en","breakdown":"Can describe decorating a surface or creating an image with coloured material.","related":"colour; draw; brush; painting","categories":["Activities","Everyday Terms"],"senses":[{"part":"noun","definition":"A coloured liquid or substance spread over a surface to protect or decorate it.","definitionZh":"涂在表面上以保护或装饰物体的有色液体或物质；油漆或颜料。","examples":["The paint on the door is still wet.","We bought blue paint for the kitchen."]},{"part":"verb — apply colour","definition":"To cover a surface with paint.","definitionZh":"在表面涂上颜料或油漆。","examples":["They painted the fence white.","I painted my bedroom last weekend."]},{"part":"verb — create an image","definition":"To create a picture by putting paint onto paper, canvas, or another surface.","definitionZh":"通过将颜料涂在纸张、画布或其他表面上创作图画。","examples":["She paints portraits of her friends.","The artist painted a view of the harbour."]}]},{"word":"photograph","part":"noun / verb","phonetic":"/ˈfoʊtəɡræf/","definition":"A picture made using a camera; or to take a picture of someone or something with a camera.","definitionZh":"照片；摄影；拍摄","examples":["I found an old photograph of my grandparents.","The reporter photographed the event."],"tip":"The noun is stressed on the first syllable. Related forms include photographer and photography.","course":"en","breakdown":"The noun is the image; the verb is the action of recording an image with a camera.","related":"photo; picture; camera; photography","categories":["Activities","Everyday Terms","History & Culture"],"senses":[{"part":"noun","definition":"A picture made by using a camera to record an image.","definitionZh":"使用相机记录图像而形成的图片；照片。","examples":["This photograph was taken in 1998.","She keeps a photograph of her family on her desk."]},{"part":"verb","definition":"To take a picture of a person, place, or thing using a camera.","definitionZh":"使用相机拍摄人物、地点或事物。","examples":["The journalist photographed the crowd.","Visitors are allowed to photograph the building."]}]},{"word":"practise","part":"verb","phonetic":"/ˈpræktɪs/","definition":"To do an activity repeatedly in order to improve a skill; or to carry out a profession or method regularly.","definitionZh":"练习；训练；从事；实践","examples":["You should practise speaking English every day.","She practises law in Kuala Lumpur."],"tip":"British English uses “practise” as the verb and “practice” as the noun. American English uses “practice” for both.","course":"en","breakdown":"Repeated action helps improve ability; the verb can also mean to work in a profession.","related":"practice; train; rehearse; improve","categories":["Activities","Education"],"senses":[{"part":"verb — improve a skill","definition":"To repeat an activity regularly so that you become better at it.","definitionZh":"定期重复某项活动，以提高自己的能力。","examples":["He practises the piano every evening.","We need to practise for the presentation."]},{"part":"verb — work in a profession","definition":"To work in a profession or regularly use a particular method or belief.","definitionZh":"从事某种职业，或定期采用某种方法或信念。","examples":["She practises medicine in a local clinic.","They practise meditation each morning."]}]},{"word":"read","part":"verb / noun","phonetic":"/riːd/ (present), /red/ (past)","definition":"To look at and understand written words; or to interpret information from signs, data, or other sources.","definitionZh":"阅读；读懂；朗读；解读","examples":["I read a chapter before bed.","Can you read the sign from here?"],"tip":"The spelling stays the same, but the past tense “read” is pronounced /red/, like “red”.","course":"en","breakdown":"Usually means understanding written language, but can also mean interpreting signals, expressions, or data.","related":"study; look through; interpret; reader","categories":["Activities","Education"],"senses":[{"part":"verb — understand written words","definition":"To look at written or printed words and understand their meaning.","definitionZh":"查看书写或印刷的文字并理解其含义。","examples":["She reads a book every week.","I read the instructions before using the machine."]},{"part":"verb — interpret information","definition":"To understand or interpret information shown by signs, numbers, expressions, or other clues.","definitionZh":"理解或解读标志、数字、表情或其他线索所传达的信息。","examples":["The device can read a barcode.","He could read the worry on her face."]},{"part":"noun — informal","definition":"A piece of writing or a book that someone reads, especially when describing how enjoyable or interesting it is.","definitionZh":"供人阅读的文章或书籍，尤指用来评价其趣味性或可读性。","examples":["The article is an easy read.","That novel is a fascinating read."]}]},{"word":"shop","part":"noun / verb","phonetic":"/ʃɑːp/","definition":"A place where goods are sold; or to visit stores to look at or buy things.","definitionZh":"商店；店铺；购物；逛商店","examples":["There is a small shop near the station.","We usually shop for groceries on Saturday."],"tip":"“Shop” is common in British English; “store” is more common in American English for many types of retail business.","course":"en","breakdown":"The noun is a place that sells goods; the verb describes visiting places to buy or browse.","related":"store; market; buy; shopping","categories":["Everyday Terms","Places","Activities"],"senses":[{"part":"noun","definition":"A place where goods are sold to customers.","definitionZh":"向顾客出售商品的地方；商店。","examples":["The bookshop closes at six.","I bought some fruit at the local shop."]},{"part":"verb","definition":"To visit shops or websites to look for or buy goods.","definitionZh":"前往商店或网站寻找、挑选或购买商品；购物。","examples":["We shop online when we are busy.","She shops for clothes twice a year."]}]},{"word":"skate","part":"verb / noun","phonetic":"/skeɪt/","definition":"To move over a surface on skates with wheels or blades; or a boot or shoe fitted with them.","definitionZh":"滑冰；滑旱冰；冰鞋；轮滑鞋","examples":["The children skate at the rink after school.","He learned to skate on the frozen lake."],"tip":"“Ice-skate” specifies skating on ice; “roller-skate” uses wheeled skates.","course":"en","breakdown":"Usually refers to moving while wearing footwear designed to glide over ice or a smooth surface.","related":"ice-skate; roller-skate; rink; skating","categories":["Activities"],"senses":[{"part":"verb","definition":"To move across ice or another smooth surface while wearing skates.","definitionZh":"穿着冰鞋或轮滑鞋在冰面或其他平滑表面上滑行。","examples":["She skates confidently on the ice.","We went to the park to roller-skate."]},{"part":"noun","definition":"A boot or shoe fitted with a blade or wheels for skating.","definitionZh":"装有冰刀或轮子的滑行靴或鞋；冰鞋或轮滑鞋。","examples":["He bought a new pair of skates.","Make sure your skates fit properly."]}]},{"word":"ski","part":"noun / verb","phonetic":"/skiː/","definition":"A long, narrow piece of equipment attached to a boot for travelling over snow; or to move over snow using skis.","definitionZh":"滑雪板；滑雪；进行滑雪运动","examples":["She learned to ski when she was young.","He bought a new pair of skis."],"tip":"The plural is “skis”; the activity is often called skiing.","course":"en","breakdown":"Can refer to the equipment or the activity of travelling over snow on it.","related":"skiing; snow; slope; snowboard","categories":["Activities","Nature & Environment"],"senses":[{"part":"noun","definition":"One of a pair of long, narrow pieces of equipment used to move over snow.","definitionZh":"用于在雪地上移动的一对细长装备之一；滑雪板。","examples":["One ski was damaged during the trip.","She rented skis at the resort."]},{"part":"verb","definition":"To travel over snow while standing on skis.","definitionZh":"站在滑雪板上在雪地上滑行；滑雪。","examples":["They ski every winter.","We skied down a gentle slope."]}]},{"word":"sleep","part":"noun / verb","phonetic":"/sliːp/","definition":"The natural state of rest in which the body and mind are less active; or to be in that state.","definitionZh":"睡眠；睡觉；入睡","examples":["I need more sleep during the week.","The baby is sleeping upstairs."],"tip":"The past tense and past participle are “slept”. Common phrases include go to sleep and fall asleep.","course":"en","breakdown":"Refers to the resting state or the act of being in that state; it is different from “rest”, which does not always involve sleeping.","related":"rest; nap; asleep; bedtime","categories":["Activities","Everyday Terms"],"senses":[{"part":"noun","definition":"The natural condition of resting in which a person or animal is usually unconscious and less aware of the surroundings.","definitionZh":"人或动物自然休息的状态，通常处于无意识且对周围环境感知较弱的状态；睡眠。","examples":["A good night's sleep helps me concentrate.","The noise interrupted my sleep."]},{"part":"verb","definition":"To be in the natural resting state in which the body and mind are less active.","definitionZh":"处于身体和精神活动减弱的自然休息状态；睡觉。","examples":["The children sleep for ten hours.","I slept badly because of the heat."]}]},{"word":"train","part":"noun / verb","phonetic":"/treɪn/","definition":"A series of connected railway vehicles that carry passengers or goods; or to teach and practise skills for a particular job or activity.","definitionZh":"火车；列车；训练；培训","examples":["We took the train to the city.","The company trains new employees."],"tip":"As a verb, train can mean practise to improve performance or teach someone how to do a job.","course":"en","breakdown":"The noun usually refers to railway transport; the verb refers to developing skills through instruction and practice.","related":"railway; practise; coach; training","categories":["Everyday Terms","Places","Activities","Education"],"senses":[{"part":"noun","definition":"A series of connected railway vehicles pulled by an engine along tracks.","definitionZh":"由机车牵引、沿铁轨行驶的一组连接车辆；火车或列车。","examples":["The train arrives at platform three.","We travelled by train across the country."]},{"part":"verb — develop a skill","definition":"To practise regularly in order to improve physical ability or performance.","definitionZh":"通过定期练习提高体能或表现。","examples":["She trains for a marathon every morning.","The team trains twice a week."]},{"part":"verb — teach someone","definition":"To teach someone the knowledge or skills needed for a job or activity.","definitionZh":"教授某人从事工作或活动所需的知识与技能。","examples":["The hotel trains its staff in customer service.","He was trained to operate the equipment."]}]},{"word":"write","part":"verb","phonetic":"/raɪt/","definition":"To form letters, words, or other symbols on a surface or digital device; or to create a text such as a message, letter, or story.","definitionZh":"写；书写；撰写；创作","examples":["Please write your name at the top of the page.","She writes stories for children."],"tip":"The past tense and past participle are “wrote” and “written”. “Write down” means record information in writing.","course":"en","breakdown":"Can refer to forming written symbols or creating a longer piece of text.","related":"read; spell; compose; author","categories":["Activities","Education"],"senses":[{"part":"verb — form written symbols","definition":"To make letters, words, or symbols using a pen, pencil, keyboard, or another tool.","definitionZh":"使用笔、铅笔、键盘或其他工具写出字母、单词或符号。","examples":["Write the answer in the space provided.","He writes with his left hand."]},{"part":"verb — create a text","definition":"To create a piece of writing, such as a letter, report, article, or story.","definitionZh":"创作信件、报告、文章或故事等文字作品。","examples":["I wrote an email to the manager.","She is writing a book about her travels."]}]},{"word":"airport","part":"noun","phonetic":"/ˈerpɔːrt/","definition":"A place where aircraft take off and land, with facilities for passengers and air travel.","definitionZh":"机场；航空港","examples":["We arrived at the airport two hours early.","The airport is connected to the city by train."],"tip":"An airport usually has terminals, check-in areas, security checks, and runways.","course":"en","breakdown":"Refers to the whole facility used for air travel, not only the runway.","related":"aircraft; airline; terminal; runway","categories":["Places"],"senses":[{"part":"noun","definition":"A place where passenger or cargo aircraft take off and land, and where travellers use airport services.","definitionZh":"供客运或货运飞机起降，并为旅客提供航空服务的场所。","examples":["The airport was busy during the holiday season.","Our flight leaves from the international airport."]}]},{"word":"apartment","part":"noun","phonetic":"/əˈpɑːrtmənt/","definition":"A set of rooms for living in, usually on one floor of a larger building.","definitionZh":"公寓；套房","examples":["They rent a small apartment near the station.","The apartment has two bedrooms and a balcony."],"tip":"“Apartment” is common in American English; “flat” is commonly used in British English.","course":"en","breakdown":"A private home within a larger residential building.","related":"flat; home; building; rent","categories":["Places","Everyday Terms"],"senses":[{"part":"noun","definition":"A private set of rooms used as a home within a larger building containing other homes.","definitionZh":"位于包含多个住宅的大楼内、供个人或家庭居住的一套独立房间；公寓。","examples":["She lives in a modern apartment downtown.","We are looking for a two-bedroom apartment."]}]},{"word":"avenue","part":"noun","phonetic":"/ˈævənuː/","definition":"A wide road in a town or city, often lined with trees or buildings; or a possible way to achieve something.","definitionZh":"林荫大道；大街；途径；方法","examples":["The hotel is on a quiet avenue.","Education can open new avenues for young people."],"tip":"In street names, “Avenue” is often shortened to “Ave.”","course":"en","breakdown":"Can refer to a type of road or, figuratively, a possible approach or opportunity.","related":"street; road; boulevard; approach","categories":["Places","Everyday Terms"],"senses":[{"part":"noun — road","definition":"A wide street in a town or city, sometimes with trees along its sides.","definitionZh":"城镇或城市中较宽的道路，有时两侧种有树木；大道。","examples":["The museum stands along a tree-lined avenue.","Turn left at the next avenue."]},{"part":"noun — possible way","definition":"A possible method or opportunity for achieving something.","definitionZh":"实现某事的一种可能方法或机会；途径。","examples":["We are exploring every avenue to solve the problem.","The course offers an avenue into the industry."]}]},{"word":"bakery","part":"noun","phonetic":"/ˈbeɪkəri/","definition":"A shop or place where bread, cakes, and other baked foods are made or sold.","definitionZh":"面包店；烘焙坊","examples":["I bought fresh bread from the bakery.","The bakery opens before sunrise."],"tip":"A bakery may make its own products, sell baked goods, or do both.","course":"en","breakdown":"The place is associated with baking and selling bread, cakes, pastries, and similar food.","related":"baker; bread; cake; pastry","categories":["Places","Everyday Terms"],"senses":[{"part":"noun","definition":"A shop or workplace where bread, cakes, and other baked goods are produced or sold.","definitionZh":"制作或销售面包、蛋糕及其他烘焙食品的商店或工作场所。","examples":["The bakery sells warm croissants every morning.","He works at a bakery near the market."]}]},{"word":"bank","part":"noun / verb","phonetic":"/bæŋk/","definition":"An organisation that keeps money and provides financial services; the land beside a river; or to deposit money in a bank.","definitionZh":"银行；河岸；存入银行；依靠","examples":["I need to visit the bank after work.","They sat on the bank of the river."],"tip":"The meaning is clear from context: financial services or the side of a river. The verb “bank” can mean deposit money.","course":"en","breakdown":"A common word with two distinct noun meanings and a related financial verb.","related":"money; account; riverbank; deposit","categories":["Places","Everyday Terms"],"senses":[{"part":"noun — financial organisation","definition":"An organisation that keeps customers' money, provides accounts, and offers financial services.","definitionZh":"保管客户资金、提供账户及金融服务的机构；银行。","examples":["She opened a savings account at the bank.","The bank closes at four in the afternoon."]},{"part":"noun — side of a river","definition":"The land along the edge of a river or stream.","definitionZh":"河流或溪流边缘的陆地；河岸。","examples":["We walked along the river bank.","A tree fell onto the bank after the storm."]},{"part":"verb — deposit money","definition":"To put money into a bank account.","definitionZh":"将钱存入银行账户。","examples":["He banks part of his salary every month.","You can bank the cheque at any branch."]}]},{"word":"beach","part":"noun / verb","phonetic":"/biːtʃ/","definition":"An area of sand or small stones beside the sea or a lake; or to bring a boat onto a shore.","definitionZh":"海滩；沙滩；使船搁浅","examples":["We spent the afternoon at the beach.","The boat was beached near the harbour."],"tip":"A beach can be sandy, rocky, or covered with small stones.","course":"en","breakdown":"Usually refers to the shore area where people walk or relax; the verb is less common.","related":"shore; coast; seaside; sand","categories":["Places","Nature & Environment","Activities"],"senses":[{"part":"noun","definition":"An area of sand or small stones beside the sea, a lake, or another body of water.","definitionZh":"海洋、湖泊或其他水域旁由沙子或小石子构成的区域；海滩。","examples":["The children built sandcastles on the beach.","The beach was quiet early in the morning."]},{"part":"verb","definition":"To bring a boat onto a shore and leave it there.","definitionZh":"将船驶到岸边并停放在岸上；使船搁浅。","examples":["They beached the small boat before the storm.","The damaged vessel was beached for repairs."]}]},{"word":"bedroom","part":"noun","phonetic":"/ˈbedruːm/","definition":"A room in a home or other building where people sleep.","definitionZh":"卧室；睡房","examples":["My bedroom has a large window.","The house has three bedrooms."],"tip":"A “one-bedroom apartment” has one separate bedroom in addition to its other living areas.","course":"en","breakdown":"A room mainly used for sleeping, usually containing a bed.","related":"bed; home; room; sleep","categories":["Places","Everyday Terms"],"senses":[{"part":"noun","definition":"A room in a house, apartment, or other building that is used mainly for sleeping.","definitionZh":"住宅、公寓或其他建筑物中主要用于睡觉的房间；卧室。","examples":["Please keep your bedroom tidy.","The guest bedroom is upstairs."]}]},{"word":"building","part":"noun","phonetic":"/ˈbɪldɪŋ/","definition":"A structure with walls and a roof, such as a house, school, or office; or the process of constructing something.","definitionZh":"建筑物；大楼；建造；建设","examples":["That building was designed by a local architect.","The building of the bridge took two years."],"tip":"As a noun, “building” usually means a physical structure; “the building of” can refer to construction as an activity.","course":"en","breakdown":"Can refer to the finished structure or, in some contexts, the act of constructing it.","related":"structure; construction; house; tower","categories":["Places","Everyday Terms"],"senses":[{"part":"noun — structure","definition":"A structure with walls and a roof, especially one used for living, working, or public activities.","definitionZh":"具有墙壁和屋顶的结构，尤指用于居住、工作或公共活动的建筑物。","examples":["The office building has twenty floors.","That old building is now a museum."]},{"part":"noun — construction activity","definition":"The process or activity of constructing something.","definitionZh":"建造某物的过程或活动。","examples":["The building of the new school is almost complete.","Road building can cause traffic delays."]}]},{"word":"bus stop","part":"noun","phonetic":"/ˈbʌs stɑːp/","definition":"A place beside a road where buses stop to let passengers get on or off.","definitionZh":"巴士站；公交车站","examples":["I waited at the bus stop for ten minutes.","The next bus stop is outside the library."],"tip":"Also commonly written as “bus stop” without a hyphen.","course":"en","breakdown":"A designated stopping place for buses, usually marked by a sign or shelter.","related":"bus; station; route; passenger","categories":["Places"],"senses":[{"part":"noun","definition":"A designated place where a bus stops so passengers can board or leave it.","definitionZh":"巴士停靠、供乘客上车或下车的指定地点；巴士站。","examples":["There is a bus stop across the street.","The driver stopped at every bus stop along the route."]}]},{"word":"cafe","part":"noun","phonetic":"/kæˈfeɪ/","definition":"A small restaurant or shop where people can buy drinks and light meals.","definitionZh":"咖啡馆；小餐馆","examples":["We met at a cafe near the office.","The cafe serves coffee, sandwiches, and cakes."],"tip":"Also spelled “café”. A cafe usually has a more casual atmosphere than a formal restaurant.","course":"en","breakdown":"A place for drinks and simple meals, often with tables for customers to sit and talk.","related":"coffee shop; restaurant; bakery; menu","categories":["Places","Everyday Terms"],"senses":[{"part":"noun","definition":"A small restaurant or shop where customers can buy drinks and light meals, often to eat on the premises.","definitionZh":"顾客可以购买饮料和简餐、通常也可在店内用餐的小餐馆或商店；咖啡馆。","examples":["The cafe has outdoor seating.","Let's have lunch at the cafe downstairs."]}]},{"word":"cafeteria","part":"noun","phonetic":"/ˌkæfəˈtɪriə/","definition":"A place where people serve themselves from a counter and eat meals, often in a school, workplace, or public building.","definitionZh":"自助餐厅；食堂","examples":["Students eat lunch in the school cafeteria.","The office cafeteria is closed on Sundays."],"tip":"A cafeteria usually offers self-service food; the word is especially common in schools and workplaces.","course":"en","breakdown":"A dining area where customers typically choose food at a counter before sitting down.","related":"canteen; dining hall; lunch; food","categories":["Places","Everyday Terms"],"senses":[{"part":"noun","definition":"A dining place where people choose food from a counter, pay, and usually carry it to their table.","definitionZh":"人们从柜台选择食物、付款并通常自行端到座位用餐的场所；自助餐厅或食堂。","examples":["The hospital cafeteria serves meals all day.","We had lunch in the university cafeteria."]}]},{"word":"campus","part":"noun","phonetic":"/ˈkæmpəs/","definition":"The land and buildings belonging to a university, college, or school.","definitionZh":"校园；大学校园；校区","examples":["The library is in the centre of the campus.","There are several cafés on campus."],"tip":"“On campus” means within the school or university grounds; “off campus” means outside them.","course":"en","breakdown":"Usually refers to the grounds and buildings of an educational institution as a whole.","related":"university; college; school; grounds","categories":["Places","Education"],"senses":[{"part":"noun","definition":"The grounds and buildings of a university, college, or other educational institution.","definitionZh":"大学、学院或其他教育机构所属的土地和建筑物；校园。","examples":["The campus has a large sports field.","She lives on campus during the semester."]}]},{"word":"capital","part":"noun","phonetic":"/ˈkæpɪtəl/","definition":"The city where a country's government is based; money or property used for business; or a letter of the larger form used at the beginning of names and sentences.","definitionZh":"首都；资本；大写字母。","examples":["Kuala Lumpur is the capital of Malaysia.","Write your name with a capital letter."],"tip":"“Capital” has several distinct meanings in geography, business, and writing.","course":"en","breakdown":"Context identifies whether it refers to a city, financial resources, or letter form.","related":"city; funds; investment; uppercase","categories":["Places","Everyday Terms","Education"],"senses":[{"part":"noun — city","definition":"The city where a country's central government is located.","definitionZh":"一国中央政府所在地的城市；首都。","examples":["Tokyo is the capital of Japan.","The capital attracts visitors from across the country."]},{"part":"noun — business funds","definition":"Money or other resources used to start or operate a business or investment.","definitionZh":"用于创办或经营企业、进行投资的资金或其他资源；资本。","examples":["The company needs more capital to expand.","Investors provided the capital for the project."]},{"part":"noun — letter","definition":"A large letter used at the beginning of a sentence or in a proper name.","definitionZh":"用于句首或专有名称开头的大写字母。","examples":["The name begins with a capital.","Use a capital letter for country names."]}]},{"word":"castle","part":"noun","phonetic":"/ˈkæsəl/","definition":"A large strong building from the past, often with thick walls and towers, built to defend a place or house important people.","definitionZh":"城堡；堡垒","examples":["The old castle stands on a hill.","We visited a medieval castle during our trip."],"tip":"Castles were often built for defence and as homes for rulers or nobles.","course":"en","breakdown":"Usually refers to a historic fortified building, rather than an ordinary modern house.","related":"fortress; palace; tower; medieval","categories":["Places","History & Culture"],"senses":[{"part":"noun","definition":"A large historic building with strong walls and towers, built mainly for defence and sometimes used as a residence.","definitionZh":"具有坚固城墙和塔楼的大型历史建筑，主要用于防御，有时也作为居所；城堡。","examples":["The castle was built in the thirteenth century.","A stone bridge leads to the castle entrance."]}]},{"word":"cave","part":"noun / verb","phonetic":"/keɪv/","definition":"A large natural hole or chamber in the side of a hill or underground; or to collapse inward.","definitionZh":"洞穴；山洞；坍塌；屈服","examples":["Bats were sleeping inside the cave.","The roof began to cave in after the storm."],"tip":"The phrasal verb “cave in” can mean physically collapse or give in to pressure.","course":"en","breakdown":"The noun is a natural underground space; the verb is most often used in the phrase “cave in”.","related":"cavern; tunnel; collapse; underground","categories":["Places","Nature & Environment"],"senses":[{"part":"noun","definition":"A large natural hole or chamber in rock, often extending underground or into a hill.","definitionZh":"岩石中较大的天然洞口或空间，通常延伸至地下或山体内部；洞穴。","examples":["The explorers entered a dark cave.","Water dripped from the roof of the cave."]},{"part":"verb — cave in","definition":"To collapse inward, or to give way under pressure.","definitionZh":"向内坍塌；或在压力下让步。","examples":["Part of the roof caved in.","He finally caved in and agreed to help."]}]},{"word":"church","part":"noun","phonetic":"/tʃɜːrtʃ/","definition":"A building used for Christian religious services; or the Christian community or organisation as a whole.","definitionZh":"教堂；基督教会；教会","examples":["The church is next to the town hall.","The church holds a service every Sunday."],"tip":"“Church” can mean the building or the religious community; capitalisation may depend on the name or institution.","course":"en","breakdown":"Refers to a Christian place of worship or the wider religious institution and community.","related":"chapel; cathedral; worship; congregation","categories":["Places","History & Culture"],"senses":[{"part":"noun — building","definition":"A building where Christians gather for religious services and worship.","definitionZh":"基督徒聚集举行宗教仪式和敬拜活动的建筑物；教堂。","examples":["The village church is more than two hundred years old.","They walked to church on Sunday morning."]},{"part":"noun — organisation","definition":"The Christian religious community or an organised Christian institution.","definitionZh":"基督教宗教团体或有组织的基督教机构；教会。","examples":["The church supports several local charities.","She works for the church."]}]},{"word":"cinema","part":"noun","phonetic":"/ˈsɪnəmə/","definition":"A building where people pay to watch films; or the art and industry of making films.","definitionZh":"电影院；电影艺术；电影业","examples":["We are going to the cinema tonight.","He studies the history of world cinema."],"tip":"“Cinema” is common in British English; “movie theater” is common in American English for the building.","course":"en","breakdown":"Can refer to a place where films are shown or the medium and industry of filmmaking.","related":"movie theatre; film; screening; actor","categories":["Places","History & Culture","Activities"],"senses":[{"part":"noun — building","definition":"A place where people watch films on a large screen, usually after buying a ticket.","definitionZh":"人们通常购票后在大屏幕上观看电影的场所；电影院。","examples":["The cinema has six screens.","We booked seats at the cinema online."]},{"part":"noun — art and industry","definition":"The art, business, and medium of making and showing films.","definitionZh":"制作和放映电影的艺术、行业及媒介；电影艺术或电影业。","examples":["She is interested in Asian cinema.","The course explores the history of cinema."]}]},{"word":"clinic","part":"noun","phonetic":"/ˈklɪnɪk/","definition":"A place where people receive medical advice or treatment, often without staying overnight; or a meeting where expert advice or training is given.","definitionZh":"诊所；门诊部；专题指导活动","examples":["He went to the clinic for a check-up.","The sports clinic teaches young players basic skills."],"tip":"A clinic usually provides appointments and treatment without the overnight stay associated with a hospital.","course":"en","breakdown":"Most commonly a medical facility, but can also describe a short expert-led training session.","related":"hospital; doctor; medical centre; treatment","categories":["Places","Everyday Terms"],"senses":[{"part":"noun — medical facility","definition":"A place where people receive medical examinations, advice, or treatment, usually without staying overnight.","definitionZh":"人们接受医疗检查、建议或治疗的场所，通常不需要留院过夜；诊所或门诊部。","examples":["The clinic opens at eight in the morning.","She works at a dental clinic."]},{"part":"noun — training session","definition":"A short event in which an expert gives practical advice or instruction about a skill.","definitionZh":"由专家就某项技能提供实际建议或指导的短期活动。","examples":["The coach held a basketball clinic for children.","The workshop included a writing clinic."]}]},{"word":"coast","part":"noun / verb","phonetic":"/koʊst/","definition":"The land beside the sea; or to move smoothly without using much power, effort, or control.","definitionZh":"海岸；沿海地区；滑行；轻松前进","examples":["They drove along the coast.","The bicycle coasted down the hill."],"tip":"“Coast” as a verb often describes a vehicle moving downhill or continuing with little effort.","course":"en","breakdown":"The noun refers to a geographical edge of land; the verb describes smooth movement or progress with little effort.","related":"shore; seaside; coastline; glide","categories":["Places","Nature & Environment","Actions"],"senses":[{"part":"noun","definition":"The area of land next to the sea or ocean.","definitionZh":"与海洋相邻的陆地区域；海岸或沿海地区。","examples":["Many towns along the coast depend on tourism.","We watched the sunset from the coast."]},{"part":"verb","definition":"To move smoothly, especially downhill, without using much power or effort.","definitionZh":"平稳移动，尤指下坡时不需要太多动力或力气；滑行。","examples":["The car coasted to a stop.","He coasted down the hill on his bicycle."]}]},{"word":"adult","part":"noun / adjective","phonetic":"/əˈdʌlt/ or /ˈædʌlt/","definition":"A person who has reached the age when they are legally or fully grown; or relating to grown people rather than children.","definitionZh":"成年人；成年的；成人的","examples":["An adult must accompany the children.","The event is intended for an adult audience."],"tip":"The legal age of adulthood differs between countries and for different legal purposes.","course":"en","breakdown":"Can refer to a grown person or describe something intended for grown people.","related":"grown-up; child; mature; adulthood","categories":["People & Relationships","Everyday Terms"],"senses":[{"part":"noun","definition":"A person who is fully grown, especially one who has reached the legally recognised age of adulthood.","definitionZh":"已经完全长大的人，尤指达到法律认可成年年龄的人；成年人。","examples":["Each child must be with an adult.","The museum offers separate tickets for adults and children."]},{"part":"adjective","definition":"Fully grown, or intended for people who are fully grown.","definitionZh":"已经成年的；或专为成年人设计或提供的。","examples":["She is an adult learner returning to school.","The film is suitable for an adult audience."]}]},{"word":"ancestor","part":"noun","phonetic":"/ˈænsestər/","definition":"A person in your family who lived a long time before you, such as a great-grandparent.","definitionZh":"祖先；祖辈；先人","examples":["One of her ancestors came from Italy.","The family keeps records of its ancestors."],"tip":"An ancestor is someone from an earlier generation; a descendant is someone from a later generation.","course":"en","breakdown":"Refers to a person from an earlier generation in a family line.","related":"forefather; relative; descendant; generation","categories":["People & Relationships","History & Culture"],"senses":[{"part":"noun","definition":"A person in your family who lived in an earlier generation, often many years ago.","definitionZh":"家族中生活在更早一代的人，通常指许多年前的祖辈；祖先。","examples":["Her ancestors lived in the countryside.","He researched his ancestors using old letters."]}]},{"word":"aunt","part":"noun","phonetic":"/ænt/ or /ɑːnt/","definition":"The sister of your mother or father, or the wife of your uncle.","definitionZh":"姑母；姨母；伯母；婶婶；舅母；阿姨","examples":["My aunt lives near the beach.","We visited our aunt during the school holidays."],"tip":"The exact Chinese family term depends on whether the aunt is related through the mother or father and on family age relationships.","course":"en","breakdown":"A family relationship term for a parent's sister or an uncle's wife.","related":"uncle; niece; nephew; relative","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"The sister of someone's mother or father, or the wife of someone's uncle.","definitionZh":"某人的母亲或父亲的姐妹，或叔叔、舅舅等的妻子；姑母、姨母或阿姨等。","examples":["My aunt taught me how to bake.","Her aunt and uncle came to the wedding."]}]},{"word":"baby","part":"noun","phonetic":"/ˈbeɪbi/","definition":"A very young child who has not yet learned to walk or talk; or the youngest or smallest member of a group.","definitionZh":"婴儿；宝宝；家庭或群体中最年幼的成员。","examples":["The baby is sleeping in the cot.","He is the baby of the family."],"tip":"The plural is “babies”. “Baby” can be used informally as a term of affection, depending on context.","course":"en","breakdown":"Usually means an infant, but can also describe the youngest member of a family or group.","related":"infant; toddler; child; newborn","categories":["People & Relationships","Everyday Terms"],"senses":[{"part":"noun — infant","definition":"A very young child, especially one who is not yet able to walk or speak.","definitionZh":"非常年幼的孩子，尤指尚未学会走路或说话的婴儿。","examples":["The baby began to cry.","They bought a car seat for their new baby."]},{"part":"noun — youngest member","definition":"The youngest or smallest member of a family or group.","definitionZh":"家庭或群体中年龄最小或体型最小的成员。","examples":["He is the baby of the family.","The new player is the baby of the team."]}]},{"word":"boyfriend","part":"noun","phonetic":"/ˈbɔɪfrend/","definition":"A male partner in a romantic relationship; or, in some contexts, a male friend.","definitionZh":"男朋友；男性伴侣；男性朋友（较少见）","examples":["She introduced her boyfriend to her parents.","My boyfriend and I enjoy hiking."],"tip":"In everyday modern use, “boyfriend” usually means a romantic partner, not simply a male friend.","course":"en","breakdown":"Usually describes a person's male romantic partner.","related":"girlfriend; partner; couple; relationship","categories":["People & Relationships"],"senses":[{"part":"noun — romantic partner","definition":"A man or boy who is in a romantic relationship with someone.","definitionZh":"与某人处于恋爱关系的男性；男朋友。","examples":["Her boyfriend gave her flowers.","They have been boyfriend and girlfriend for two years."]},{"part":"noun — male friend","definition":"A male friend, especially in older or less common usage where the romantic meaning is not intended.","definitionZh":"男性朋友，尤指较旧或较少见的用法中不表示恋爱关系时。","examples":["She invited a boyfriend from school to the event.","He was one of her closest boyfriends."]}]},{"word":"bride","part":"noun","phonetic":"/braɪd/","definition":"A woman who is getting married or has recently married.","definitionZh":"新娘","examples":["The bride arrived at the ceremony with her father.","The bride and groom thanked their guests."],"tip":"The male partner getting married is the “groom”.","course":"en","breakdown":"Refers to the woman at the centre of a wedding ceremony or newly married woman.","related":"groom; wedding; marriage; spouse","categories":["People & Relationships","History & Culture"],"senses":[{"part":"noun","definition":"A woman on her wedding day or a woman who has recently married.","definitionZh":"在婚礼当天结婚的女性，或刚刚结婚的女性；新娘。","examples":["The bride wore a simple white dress.","Guests waited for the bride to enter."]}]},{"word":"brother","part":"noun","phonetic":"/ˈbrʌðər/","definition":"A boy or man who has the same parent or parents as another person; or a man who shares a close group, belief, or community with others.","definitionZh":"兄弟；哥哥；弟弟；同胞；兄弟会成员","examples":["My brother works in another city.","She has two older brothers."],"tip":"English “brother” does not show whether the person is older or younger; Chinese uses different words for older and younger brothers.","course":"en","breakdown":"A family relationship term; context can also extend it to people sharing a community or organisation.","related":"sister; sibling; family; relative","categories":["People & Relationships"],"senses":[{"part":"noun — family member","definition":"A male person who has one or both parents in common with another person.","definitionZh":"与另一个人有一个或两个共同父母的男性；兄弟、哥哥或弟弟。","examples":["My younger brother is still at school.","Her brother helped her move house."]},{"part":"noun — member of a group","definition":"A man who belongs to the same religious, social, or professional group as others, or who is treated as a close companion.","definitionZh":"属于同一宗教、社会或职业团体的男性成员，或被视为亲密伙伴的男性。","examples":["The monks called one another brother.","He regarded his teammates as brothers."]}]},{"word":"buddy","part":"noun","phonetic":"/ˈbʌdi/","definition":"A friend or companion, especially one you do an activity with; an informal way to address someone.","definitionZh":"伙伴；朋友；搭档；老兄（非正式称呼）","examples":["He went fishing with his old buddy.","Thanks for your help, buddy."],"tip":"“Buddy” is informal and common in North American English; use more neutral terms in formal situations.","course":"en","breakdown":"A friendly, informal word for someone you know or spend time with.","related":"friend; pal; partner; companion","categories":["People & Relationships"],"senses":[{"part":"noun — friend","definition":"A friend or companion, often someone you spend time or do activities with.","definitionZh":"朋友或伙伴，通常指一起相处或参加活动的人。","examples":["I am meeting a buddy after work.","He has been my fishing buddy for years."]},{"part":"noun — form of address","definition":"An informal way of speaking directly to someone, especially in a friendly or familiar tone.","definitionZh":"直接称呼某人的非正式说法，尤指友好或熟悉的语气。","examples":["Hey, buddy, how are you?","Listen, buddy, I need your help."]}]},{"word":"citizen","part":"noun","phonetic":"/ˈsɪtɪzən/","definition":"A person who legally belongs to a particular country and has the rights and responsibilities of that country.","definitionZh":"公民；国民；市民","examples":["Every citizen has responsibilities as well as rights.","The programme helps young citizens understand local government."],"tip":"A citizen is a legal member of a country; a resident may live there without being a citizen.","course":"en","breakdown":"Usually refers to legal membership of a country, although it can also mean a person living in a particular city.","related":"national; resident; nationality; citizenship","categories":["People & Relationships","History & Culture"],"senses":[{"part":"noun — member of a country","definition":"A person who has legal membership of a country and is entitled to its rights and subject to its laws.","definitionZh":"依法属于某个国家、享有该国权利并承担相应法律义务的人；公民或国民。","examples":["The law protects every citizen.","She became a citizen after completing the required process."]},{"part":"noun — member of a city","definition":"A person who lives in a particular town or city, especially when discussing public life and responsibilities.","definitionZh":"居住在某个城镇或城市的人，尤指讨论公共生活和责任时；市民。","examples":["The mayor met with local citizens.","Citizens can attend the public meeting."]}]},{"word":"classmate","part":"noun","phonetic":"/ˈklæsmeɪt/","definition":"A person who is in the same class or study group as you at school or another educational institution.","definitionZh":"同班同学；同学","examples":["I worked with a classmate on the science project.","She has known her classmates since primary school."],"tip":"A classmate is in the same class; a schoolmate may attend the same school but be in a different class.","course":"en","breakdown":"A school or study relationship based on being in the same class.","related":"schoolmate; student; peer; class","categories":["People & Relationships","Education"],"senses":[{"part":"noun","definition":"A person who studies in the same class or teaching group as another person.","definitionZh":"与另一个人在同一个班级或教学小组学习的人；同班同学。","examples":["My classmate lent me a pencil.","The teacher asked each classmate to introduce themselves."]}]},{"word":"cousin","part":"noun","phonetic":"/ˈkʌzən/","definition":"A child of your aunt or uncle; a relative who shares a more distant family connection.","definitionZh":"堂兄弟姐妹；表兄弟姐妹；堂亲；表亲","examples":["My cousin is visiting us this weekend.","She has several cousins on her mother's side."],"tip":"English “cousin” does not specify gender or whether the relative is older or younger; Chinese kinship terms are more specific.","course":"en","breakdown":"A family term for the child of an aunt or uncle, regardless of gender.","related":"aunt; uncle; relative; family","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A child of someone's aunt or uncle, whether male or female.","definitionZh":"某人的姑母、姨母、叔伯或舅舅等的子女，不区分性别；堂亲或表亲。","examples":["My cousin lives in Penang.","He invited all his cousins to the family gathering."]}]},{"word":"couple","part":"noun / verb","phonetic":"/ˈkʌpəl/","definition":"Two people or things considered together, especially two people in a romantic relationship; or to join two things together.","definitionZh":"一对；夫妻；情侣；几个；连接；结合","examples":["The couple moved into a new apartment.","A couple of friends are coming over."],"tip":"“A couple of” often means two, but informally it can mean a small number.","course":"en","breakdown":"Can refer to two people or items, a romantic pair, or the act of joining things.","related":"pair; partner; two; join","categories":["People & Relationships","Everyday Terms"],"senses":[{"part":"noun — two people together","definition":"Two people who are married or in a romantic relationship.","definitionZh":"已婚或处于恋爱关系的两个人；夫妻或情侣。","examples":["The couple celebrated their anniversary.","A young couple sat near the window."]},{"part":"noun — two items","definition":"Two people or things considered together; in informal use, a small number.","definitionZh":"被视为一组的两个人或两个事物；非正式用法中也可表示少量。","examples":["I need a couple of minutes.","She bought a couple of notebooks."]},{"part":"verb","definition":"To connect or join two things together.","definitionZh":"将两个事物连接或结合在一起。","examples":["The railway lines are coupled together.","The two events are closely coupled."]}]},{"word":"daughter","part":"noun","phonetic":"/ˈdɔːtər/","definition":"A female child in relation to her parents.","definitionZh":"女儿","examples":["Their daughter starts school next year.","My daughter enjoys drawing and reading."],"tip":"The male equivalent is “son”.","course":"en","breakdown":"A direct family relationship term for a female child.","related":"son; parent; child; family","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A female child in relation to one or both of her parents.","definitionZh":"相对于父母而言的女性子女；女儿。","examples":["Their youngest daughter lives nearby.","He is proud of his daughter's work."]}]},{"word":"neighbour","part":"noun / verb","phonetic":"/ˈneɪbər/","definition":"A person who lives near you; or to be next to or close to something.","definitionZh":"邻居；邻近的人；与……相邻","examples":["Our neighbours are very friendly.","The two villages neighbour each other."],"tip":"British English spells the word “neighbour”; American English uses “neighbor”.","course":"en","breakdown":"Usually a person living nearby; the verb is less common and means to be next to something.","related":"neighbor; resident; nearby; neighbourhood","categories":["People & Relationships","Everyday Terms"],"senses":[{"part":"noun","definition":"A person who lives near another person or household.","definitionZh":"住在某人或某户人家附近的人；邻居。","examples":["We invited our neighbours to dinner.","A neighbour helped us carry the boxes."]},{"part":"verb","definition":"To be located next to or close to another place or area.","definitionZh":"位于另一个地点或区域旁边或附近；与……相邻。","examples":["The park neighbours the school.","Their property neighbours a large field."]}]},{"word":"enemy","part":"noun","phonetic":"/ˈenəmi/","definition":"A person, group, or country that opposes or wants to harm another; or something harmful that must be overcome.","definitionZh":"敌人；仇敌；有害因素；大敌","examples":["The two countries were once enemies.","Lack of sleep is the enemy of concentration."],"tip":"An enemy is someone or something opposed to you; an opponent may simply be someone competing against you.","course":"en","breakdown":"Can refer to a hostile person or group, or figuratively to a harmful force or condition.","related":"opponent; rival; foe; threat","categories":["People & Relationships"],"senses":[{"part":"noun — hostile person or group","definition":"A person, group, or country that is actively opposed to another or may try to harm them.","definitionZh":"积极反对他人或可能试图伤害他人的个人、群体或国家；敌人。","examples":["The soldiers faced the enemy across the river.","They became enemies after the argument."]},{"part":"noun — harmful force","definition":"Something that causes damage or makes success more difficult.","definitionZh":"造成损害或使成功变得更加困难的事物；大敌。","examples":["Stress can be an enemy of good health.","Carelessness is the enemy of accuracy."]}]},{"word":"female","part":"noun / adjective","phonetic":"/ˈfiːmeɪl/","definition":"A person or animal that belongs to the sex that can produce eggs or give birth; or relating to that sex.","definitionZh":"女性；雌性；女性的；雌性的","examples":["The study included both male and female participants.","The female bird builds the nest."],"tip":"“Female” is often used in scientific, official, or statistical contexts; “woman” is usually more natural when referring to an adult person.","course":"en","breakdown":"A biological or demographic term that can function as a noun or adjective.","related":"male; woman; girl; sex","categories":["People & Relationships","Science & Technology"],"senses":[{"part":"noun","definition":"A person or animal of the sex that produces eggs or, in many species, gives birth.","definitionZh":"属于能够产生卵子或在许多物种中能够生育这一性别的人或动物；雌性或女性。","examples":["The survey included fifty females and fifty males.","The female of this species is larger."]},{"part":"adjective","definition":"Relating to the sex that produces eggs or gives birth.","definitionZh":"与能够产生卵子或生育的性别有关的；女性的或雌性的。","examples":["The female athletes trained together.","A female elephant was caring for the calf."]}]},{"word":"gentleman","part":"noun","phonetic":"/ˈdʒentəlmən/","definition":"A man who is polite, considerate, and well-mannered; or a formal and polite way to refer to a man.","definitionZh":"绅士；有礼貌的男士；先生","examples":["He behaved like a true gentleman.","Ladies and gentlemen, welcome to the event."],"tip":"The plural is “gentlemen”. It can sound formal or old-fashioned in some everyday situations.","course":"en","breakdown":"Often describes a man's polite behaviour or serves as a formal form of address.","related":"man; gentlemanly; polite; lady","categories":["People & Relationships","Everyday Terms"],"senses":[{"part":"noun — well-mannered man","definition":"A man who behaves politely, respectfully, and considerately toward others.","definitionZh":"举止礼貌、尊重他人并体贴周到的男性；绅士。","examples":["He offered his seat to the older passenger like a gentleman.","A gentleman always treats others with respect."]},{"part":"noun — formal address","definition":"A polite or formal way of referring to a man, especially in public speech.","definitionZh":"尤指在公开讲话中礼貌或正式地称呼男性的方式；先生。","examples":["The gentleman at the front has a question.","Ladies and gentlemen, please take your seats."]}]},{"word":"guest","part":"noun","phonetic":"/ɡest/","definition":"A person who is invited to visit someone's home or attend an event; or a person staying at a hotel or similar place.","definitionZh":"客人；宾客；住客；嘉宾","examples":["We have a guest staying with us tonight.","The hotel offers free breakfast to its guests."],"tip":"A guest is invited or received by a host; the host is the person who welcomes the guest.","course":"en","breakdown":"Can refer to a visitor at a home or event, a hotel customer, or an invited participant.","related":"visitor; host; visitor; customer","categories":["People & Relationships","Everyday Terms"],"senses":[{"part":"noun — invited visitor","definition":"A person invited to someone's home or to take part in an event.","definitionZh":"受邀到某人家中或参加某项活动的人；客人或宾客。","examples":["Each guest received a name badge.","We invited twenty guests to the wedding."]},{"part":"noun — hotel customer","definition":"A person who pays to stay at a hotel or other accommodation.","definitionZh":"付费入住酒店或其他住宿场所的人；住客。","examples":["Hotel guests can use the swimming pool.","The guest checked out early."]},{"part":"noun — invited participant","definition":"A person invited to appear on a programme, speak at an event, or take part in an activity.","definitionZh":"受邀在节目中露面、在活动中发言或参与某项活动的人；嘉宾。","examples":["The show has a special guest tonight.","She was a guest speaker at the conference."]}]},{"word":"grandfather","part":"noun","phonetic":"/ˈɡrændˌfɑːðər/","definition":"The father of someone's mother or father.","definitionZh":"祖父；外祖父；爷爷；外公","examples":["My grandfather taught me how to fish.","Her grandfather lives in a small village."],"tip":"English “grandfather” does not distinguish the father's side from the mother's side; Chinese uses different terms.","course":"en","breakdown":"A family relationship term for a parent's father.","related":"grandmother; grandparent; grandson; granddaughter","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"The father of someone's mother or father.","definitionZh":"某人的父亲或母亲的父亲；祖父或外祖父。","examples":["My grandfather is eighty years old.","We visit our grandfather every weekend."]}]},{"word":"grandmother","part":"noun","phonetic":"/ˈɡrændˌmʌðər/","definition":"The mother of someone's mother or father.","definitionZh":"祖母；外祖母；奶奶；外婆","examples":["My grandmother makes excellent soup.","Their grandmother lives with the family."],"tip":"English “grandmother” does not distinguish the father's side from the mother's side; Chinese uses different terms.","course":"en","breakdown":"A family relationship term for a parent's mother.","related":"grandfather; grandparent; granddaughter; grandson","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"The mother of someone's mother or father.","definitionZh":"某人的父亲或母亲的母亲；祖母或外祖母。","examples":["Her grandmother taught her to sew.","We called our grandmother on her birthday."]}]},{"word":"divide","part":"verb","phonetic":"/dɪˈvaɪd/","definition":"To separate something into parts or groups, or to share it among people.","definitionZh":"分开；划分；分配","examples":["We divided the work into three parts.","Please divide the cake equally."],"tip":"Use “divide into” for the parts created and “divide by” in mathematics.","course":"en","breakdown":"To separate something into parts or groups, or to share it among people.","related":"separate; split; share","categories":["Actions"],"senses":[{"part":"verb","definition":"To separate something into parts or groups, or to share it among people.","definitionZh":"分开；划分；分配","examples":["We divided the work into three parts.","Please divide the cake equally."]}]},{"word":"doubt","part":"noun / verb","phonetic":"/daʊt/","definition":"A feeling of uncertainty about something; or to question whether something is true.","definitionZh":"怀疑；疑问；不确定","examples":["I have no doubt that she will succeed.","He began to doubt his decision."],"tip":"Use “doubt that” when you think something may not be true; “without a doubt” means certainly.","course":"en","breakdown":"A feeling of uncertainty about something; or to question whether something is true.","related":"uncertainty; question; suspect","categories":["Actions"],"senses":[{"part":"noun","definition":"A feeling of uncertainty about whether something is true or what will happen.","definitionZh":"怀疑；疑虑；不确定","examples":["I have no doubt that she will succeed.","She had serious doubts about the plan."]},{"part":"verb","definition":"To feel uncertain about something or to question whether it is true.","definitionZh":"对某事感到不确定；怀疑某事是否属实。","examples":["I doubt that the shop is still open.","She began to doubt her decision."]}]},{"word":"earn","part":"verb","phonetic":"/ɜːrn/","definition":"To receive money or another reward in return for work or effort.","definitionZh":"赚得；挣得；赢得","examples":["She earns enough to support herself.","You must work hard to earn trust."],"tip":"You earn money, a living, or respect through work or actions.","course":"en","breakdown":"To receive money or another reward in return for work or effort.","related":"make; gain; deserve","categories":["Actions"],"senses":[{"part":"verb","definition":"To receive money or another reward in return for work or effort.","definitionZh":"赚得；挣得；赢得","examples":["She earns enough to support herself.","You must work hard to earn trust."]}]},{"word":"enjoy","part":"verb","phonetic":"/ɪnˈdʒɔɪ/","definition":"To get pleasure or satisfaction from something.","definitionZh":"享受；喜爱；从……中获得乐趣","examples":["I enjoy walking in the park.","Did you enjoy the film?"],"tip":"Use “enjoy” with a noun or an -ing verb, not with “to” plus a verb.","course":"en","breakdown":"To get pleasure or satisfaction from something.","related":"like; appreciate; pleasure","categories":["Actions"],"senses":[{"part":"verb","definition":"To get pleasure or satisfaction from something.","definitionZh":"享受；喜爱；从……中获得乐趣","examples":["I enjoy walking in the park.","Did you enjoy the film?"]}]},{"word":"enter","part":"verb","phonetic":"/ˈentər/","definition":"To go or come into a place; or to put information into a system.","definitionZh":"进入；参加；输入","examples":["Please enter the room quietly.","Enter your email address here."],"tip":"“Enter” usually takes a direct object: say “enter the room”, not “enter into the room”.","course":"en","breakdown":"To go or come into a place; or to put information into a system.","related":"come in; go into; input","categories":["Actions"],"senses":[{"part":"verb","definition":"To go or come into a place; or to put information into a system.","definitionZh":"进入；参加；输入","examples":["Please enter the room quietly.","Enter your email address here."]}]},{"word":"escape","part":"verb / noun","phonetic":"/ɪˈskeɪp/","definition":"To get away from a place, person, or situation; or the act of getting away.","definitionZh":"逃脱；逃离；摆脱","examples":["The cat escaped through the open window.","They planned their escape at night."],"tip":"Use “escape from” for a place or situation, and “escape doing something” for avoiding an action.","course":"en","breakdown":"To get away from a place, person, or situation; or the act of getting away.","related":"get away; flee; avoid","categories":["Actions"],"senses":[{"part":"verb","definition":"To get away from a place, person, or difficult situation.","definitionZh":"逃脱；逃离；摆脱","examples":["The cat escaped through the open window."]},{"part":"noun","definition":"The act of getting away from a place, person, or difficult situation.","definitionZh":"逃离某个地方、某个人或困境的行为；逃脱。","examples":["Their escape was planned carefully.","The fire escape was blocked by boxes."]}]},{"word":"examine","part":"verb","phonetic":"/ɪɡˈzæmɪn/","definition":"To look at or test something carefully in order to understand or judge it.","definitionZh":"检查；审查；考查","examples":["The doctor examined my ankle.","Please examine the details before signing."],"tip":"“Examine” suggests looking carefully for details; it is more formal than “look at”.","course":"en","breakdown":"To look at or test something carefully in order to understand or judge it.","related":"inspect; check; investigate","categories":["Actions"],"senses":[{"part":"verb","definition":"To look at or test something carefully in order to understand or judge it.","definitionZh":"检查；审查；考查","examples":["The doctor examined my ankle.","Please examine the details before signing."]}]},{"word":"exchange","part":"noun / verb","phonetic":"/ɪksˈtʃeɪndʒ/","definition":"The act of giving something and receiving something else; or to give one thing for another.","definitionZh":"交换；交流；兑换","examples":["We exchanged phone numbers.","The shop will exchange the shirt."],"tip":"Use “exchange A for B” when one thing is given and another is received.","course":"en","breakdown":"The act of giving something and receiving something else; or to give one thing for another.","related":"swap; trade; replace","categories":["Actions"],"senses":[{"part":"noun","definition":"An act of giving something and receiving something else in return.","definitionZh":"交换；交流；兑换","examples":["The exchange of ideas helped the team.","The two countries agreed to a cultural exchange."]},{"part":"verb","definition":"To give something to someone and receive something in return.","definitionZh":"与他人互相给予并交换物品、信息或服务。","examples":["We exchanged phone numbers after the meeting.","The shop agreed to exchange the damaged item."]}]},{"word":"exist","part":"verb","phonetic":"/ɪɡˈzɪst/","definition":"To be real or present; to have life or being.","definitionZh":"存在；生存","examples":["Do life forms exist on other planets?","The old building still exists."],"tip":"“Exist” describes being real or present; it is not normally used in the continuous form.","course":"en","breakdown":"To be real or present; to have life or being.","related":"live; remain; presence","categories":["Actions"],"senses":[{"part":"verb","definition":"To be real or present; to have life or being.","definitionZh":"存在；生存","examples":["Do life forms exist on other planets?","The old building still exists."]}]},{"word":"explore","part":"verb","phonetic":"/ɪkˈsplɔːr/","definition":"To travel through or investigate a place or subject to learn more about it.","definitionZh":"探索；探究；考察","examples":["We explored the old town on foot.","The class will explore the causes of climate change."],"tip":"You can explore a place physically or explore an idea by studying it.","course":"en","breakdown":"To travel through or investigate a place or subject to learn more about it.","related":"investigate; discover; travel","categories":["Actions"],"senses":[{"part":"verb","definition":"To travel through or investigate a place or subject to learn more about it.","definitionZh":"探索；探究；考察","examples":["We explored the old town on foot.","The class will explore the causes of climate change."]}]},{"word":"fail","part":"verb / noun","phonetic":"/feɪl/","definition":"To be unsuccessful in doing something; or an unsuccessful result.","definitionZh":"失败；未能；不及格","examples":["The engine failed to start.","One mistake does not mean you have failed."],"tip":"Use “fail to do something” when an expected action does not happen.","course":"en","breakdown":"To be unsuccessful in doing something; or an unsuccessful result.","related":"unsuccessful; miss; failure","categories":["Actions"],"senses":[{"part":"verb","definition":"To be unsuccessful in doing something or reaching a desired result.","definitionZh":"失败；未能；不及格","examples":["The engine failed to start.","One mistake does not mean you have failed."]},{"part":"noun","definition":"An unsuccessful result, especially an informal term for a failing mark or attempt.","definitionZh":"失败的结果；尤指考试或任务中的不及格（非正式用法）。","examples":["The teacher marked the test as a fail.","Forgetting the key was a complete fail."]}]},{"word":"fix","part":"verb / noun","phonetic":"/fɪks/","definition":"To repair something, make it work, or decide it firmly; a solution to a problem.","definitionZh":"修理；修复；确定；解决办法","examples":["Can you fix the broken chair?","We need to fix a date for the meeting."],"tip":"“Fix” is informal and broad; use “repair” for equipment and “solve” for a problem.","course":"en","breakdown":"To repair something, make it work, or decide it firmly; a solution to a problem.","related":"repair; mend; solve","categories":["Actions"],"senses":[{"part":"verb","definition":"To repair something, make it work, or decide it firmly; a solution to a problem.","definitionZh":"修理；修复；确定；解决办法","examples":["Can you fix the broken chair?","We need to fix a date for the meeting."]},{"part":"noun","definition":"A solution or repair that corrects a problem, often a quick or temporary one.","definitionZh":"解决问题的方法或修复措施，常指快速或临时的解决办法。","examples":["The update includes a fix for the login problem.","A fresh coat of paint was only a temporary fix."]}]},{"word":"guess","part":"verb / noun","phonetic":"/ɡes/","definition":"To give an answer without being certain; or an answer based on limited information.","definitionZh":"猜测；推测；猜想","examples":["Can you guess what is inside the box?","My guess was close to the correct answer."],"tip":"Use “guess that” before a clause, or “guess at” when suggesting an uncertain answer.","course":"en","breakdown":"To give an answer without being certain; or an answer based on limited information.","related":"estimate; suppose; predict","categories":["Actions"],"senses":[{"part":"verb","definition":"To give an answer or estimate without being certain that it is correct.","definitionZh":"猜测；推测；猜想","examples":["Can you guess what is inside the box?"]},{"part":"noun","definition":"An answer or opinion given without being certain that it is correct.","definitionZh":"在没有把握的情况下作出的猜测或估计。","examples":["That was a good guess.","My guess is that the train will be late."]}]},{"word":"happen","part":"verb","phonetic":"/ˈhæpən/","definition":"To take place or occur, often without being planned.","definitionZh":"发生；出现","examples":["Accidents can happen at any time.","What happened after the meeting?"],"tip":"Use “happen to” for an accidental experience, as in “What happened to your phone?”","course":"en","breakdown":"To take place or occur, often without being planned.","related":"occur; take place; event","categories":["Actions"],"senses":[{"part":"verb","definition":"To take place or occur, often without being planned.","definitionZh":"发生；出现","examples":["Accidents can happen at any time.","What happened after the meeting?"]}]},{"word":"hide","part":"verb","phonetic":"/haɪd/","definition":"To put something where it cannot be seen, or to keep something secret.","definitionZh":"隐藏；躲藏；隐瞒","examples":["The children hid behind the sofa.","He tried to hide his disappointment."],"tip":"Use “hide something from someone” when keeping information or an object out of their view.","course":"en","breakdown":"To put something where it cannot be seen, or to keep something secret.","related":"conceal; cover; secret","categories":["Actions"],"senses":[{"part":"verb","definition":"To put something where it cannot be seen, or to keep something secret.","definitionZh":"隐藏；躲藏；隐瞒","examples":["The children hid behind the sofa.","He tried to hide his disappointment."]}]},{"word":"influence","part":"noun / verb","phonetic":"/ˈɪnfluəns/","definition":"The power to affect a person or situation; or to have such an effect.","definitionZh":"影响；作用；影响力","examples":["Friends can have a strong influence on us.","Weather may influence our travel plans."],"tip":"“Influence” is usually a noun or verb; “have an influence on” is a common noun pattern.","course":"en","breakdown":"The power to affect a person or situation; or to have such an effect.","related":"affect; shape; impact","categories":["Actions"],"senses":[{"part":"noun","definition":"The power or effect that a person or thing has on another.","definitionZh":"影响；作用；影响力","examples":["Friends can have a strong influence on us."]},{"part":"verb","definition":"To affect the way someone thinks, behaves, or the way something develops.","definitionZh":"影响某人的想法、行为或某件事的发展。","examples":["Her teachers influenced her choice of career.","The weather may influence our plans."]}]},{"word":"inform","part":"verb","phonetic":"/ɪnˈfɔːrm/","definition":"To give someone facts or details they need to know.","definitionZh":"通知；告知；报告","examples":["Please inform us of any changes.","The school informed parents about the event."],"tip":"Use “inform someone of/about something”; the verb is more formal than “tell”.","course":"en","breakdown":"To give someone facts or details they need to know.","related":"notify; tell; announce","categories":["Actions"],"senses":[{"part":"verb","definition":"To give someone facts or details they need to know.","definitionZh":"通知；告知；报告","examples":["Please inform us of any changes.","The school informed parents about the event."]}]},{"word":"introduce","part":"verb","phonetic":"/ˌɪntrəˈduːs/","definition":"To tell people each other's names, present something for the first time, or bring something into use.","definitionZh":"介绍；引进；首次提出","examples":["Let me introduce my colleague.","The company will introduce a new service."],"tip":"Use “introduce someone to someone” for introductions and “introduce a change” for something new.","course":"en","breakdown":"To tell people each other's names, present something for the first time, or bring something into use.","related":"present; welcome; launch","categories":["Actions"],"senses":[{"part":"verb","definition":"To tell people each other's names, present something for the first time, or bring something into use.","definitionZh":"介绍；引进；首次提出","examples":["Let me introduce my colleague.","The company will introduce a new service."]}]},{"word":"invite","part":"verb","phonetic":"/ɪnˈvaɪt/","definition":"To ask someone to come to an event or to take part in something.","definitionZh":"邀请；请求参与","examples":["We invited our neighbours to dinner.","She invited me to join the team."],"tip":"Use “invite someone to an event” or “invite someone to do something”.","course":"en","breakdown":"To ask someone to come to an event or to take part in something.","related":"ask; welcome; invitation","categories":["Actions"],"senses":[{"part":"verb","definition":"To ask someone to come to an event or to take part in something.","definitionZh":"邀请；请求参与","examples":["We invited our neighbours to dinner.","She invited me to join the team."]}]},{"word":"join","part":"verb","phonetic":"/dʒɔɪn/","definition":"To become part of a group or activity, or to connect things together.","definitionZh":"加入；参加；连接","examples":["Would you like to join our club?","Join the two pieces with glue."],"tip":"Use “join a group” without “to”; use “join in” for taking part in an activity.","course":"en","breakdown":"To become part of a group or activity, or to connect things together.","related":"connect; participate; become a member","categories":["Actions"],"senses":[{"part":"verb","definition":"To become part of a group or activity, or to connect things together.","definitionZh":"加入；参加；连接","examples":["Would you like to join our club?","Join the two pieces with glue."]}]},{"word":"judge","part":"verb / noun","phonetic":"/dʒʌdʒ/","definition":"To form an opinion about someone or something; or a person who makes decisions in a court or competition.","definitionZh":"判断；评判；法官；裁判","examples":["Do not judge people by their appearance.","The judge listened to both sides."],"tip":"“Judge” can mean form an opinion; “a judge” is also an official in a court or competition.","course":"en","breakdown":"To form an opinion about someone or something; or a person who makes decisions in a court or competition.","related":"assess; decide; evaluate","categories":["Actions"],"senses":[{"part":"verb","definition":"To form an opinion about someone or something after considering the available information.","definitionZh":"判断；评判；评价","examples":["Do not judge people by their appearance.","Try not to judge a book by its cover."]},{"part":"noun","definition":"An official who makes decisions in a court or decides the result of a competition.","definitionZh":"在法庭上作出裁决，或在比赛中评定结果的官员；法官；裁判。","examples":["The judge listened to both sides.","A panel of judges selected the winning design."]}]},{"word":"kick","part":"verb / noun","phonetic":"/kɪk/","definition":"To hit or move something with your foot; or the action of doing so.","definitionZh":"踢；踹；一脚","examples":["He kicked the ball into the goal.","The child gave the door a gentle kick."],"tip":"Use “kick someone/something” with a direct object; “kick off” can mean begin an event.","course":"en","breakdown":"To hit or move something with your foot; or the action of doing so.","related":"strike; hit; boot","categories":["Actions"],"senses":[{"part":"verb","definition":"To hit or move something with the foot.","definitionZh":"踢；踹","examples":["He kicked the ball into the goal."]},{"part":"noun","definition":"An act of hitting or moving something with the foot.","definitionZh":"用脚踢或推动某物的动作；一脚。","examples":["He gave the ball a powerful kick.","One kick was enough to open the loose panel."]}]},{"word":"knock","part":"verb / noun","phonetic":"/nɑːk/","definition":"To hit a door or surface to make a sound; or the sound made by hitting it.","definitionZh":"敲；击；敲门声","examples":["Please knock before entering.","I heard a knock at the door."],"tip":"Use “knock on/at the door” for the action of making a sound to get attention.","course":"en","breakdown":"To hit a door or surface to make a sound; or the sound made by hitting it.","related":"tap; hit; rap","categories":["Actions"],"senses":[{"part":"verb","definition":"To hit a door or surface, usually to attract attention or make a sound.","definitionZh":"敲；击；敲门","examples":["Please knock before entering."]},{"part":"noun","definition":"A short sound made by hitting a door or another hard surface.","definitionZh":"敲击门或其他坚硬表面时发出的短促声音；敲门声。","examples":["I heard a knock at the front door.","There was a loud knock on the window."]}]},{"word":"lend","part":"verb","phonetic":"/lend/","definition":"To give something to someone for a period of time, expecting it to be returned.","definitionZh":"借出；借给","examples":["Could you lend me your pen?","The bank agreed to lend them money."],"tip":"The lender gives: “lend something to someone”; the borrower receives: “borrow something from someone”.","course":"en","breakdown":"To give something to someone for a period of time, expecting it to be returned.","related":"loan; borrow; give temporarily","categories":["Actions"],"senses":[{"part":"verb","definition":"To give something to someone for a period of time, expecting it to be returned.","definitionZh":"借出；借给","examples":["Could you lend me your pen?","The bank agreed to lend them money."]}]},{"word":"lift","part":"verb / noun","phonetic":"/lɪft/","definition":"To raise something to a higher position; or an act or device that raises people or things.","definitionZh":"举起；抬起；电梯；提升","examples":["Please lift the box carefully.","We took the lift to the fifth floor."],"tip":"In British English, “a lift” can also mean an elevator or a ride in a vehicle.","course":"en","breakdown":"To raise something to a higher position; or an act or device that raises people or things.","related":"raise; elevate; carry","categories":["Actions"],"senses":[{"part":"verb","definition":"To raise something to a higher position.","definitionZh":"举起；抬起；提起","examples":["Please lift the box carefully."]},{"part":"noun","definition":"A device that carries people or goods between floors; in British English, also a ride in a vehicle.","definitionZh":"运送人员或货物上下楼层的电梯；在英式英语中也可指搭便车。","examples":["We took the lift to the sixth floor.","Could you give me a lift to the station?"]}]},{"word":"measure","part":"verb / noun","phonetic":"/ˈmeʒər/","definition":"To find the size, amount, or level of something; or a unit or action used for comparison.","definitionZh":"测量；衡量；措施；单位","examples":["Measure the table before buying a cover.","The government introduced safety measures."],"tip":"Use “measure something” for finding its size; “measure up” can mean meet a standard.","course":"en","breakdown":"To find the size, amount, or level of something; or a unit or action used for comparison.","related":"assess; size; quantity","categories":["Actions"],"senses":[{"part":"verb","definition":"To find the size, amount, or level of something using a suitable unit or method.","definitionZh":"测量；衡量","examples":["Measure the table before buying a cover."]},{"part":"noun","definition":"An action taken to achieve a purpose or prevent a problem; a standard unit or amount.","definitionZh":"为达到目的或防止问题而采取的措施；衡量事物的标准或单位。","examples":["The school introduced safety measures.","A centimetre is a unit of measure."]}]},{"word":"offer","part":"verb / noun","phonetic":"/ˈɔːfər/","definition":"To say that you are willing to give or do something; or a proposal to do so.","definitionZh":"提供；主动给予；提议；报价","examples":["She offered to help us move.","The shop has a special offer today."],"tip":"Use “offer to do something” or “offer someone something”; an offer can be accepted or refused.","course":"en","breakdown":"To say that you are willing to give or do something; or a proposal to do so.","related":"propose; provide; suggestion","categories":["Actions"],"senses":[{"part":"verb","definition":"To say that you are willing to give, provide, or do something.","definitionZh":"提供；主动给予；提议","examples":["She offered to help us move."]},{"part":"noun","definition":"A proposal to give, do, or provide something; or a special price or deal.","definitionZh":"提供某物或做某事的提议；特价或优惠。","examples":["She received an offer of a new job.","The shop has a special offer this week."]}]},{"word":"promise","part":"noun / verb","phonetic":"/ˈprɑːmɪs/","definition":"A statement that you will do something; or to say that you will do it.","definitionZh":"承诺；保证；答应","examples":["He made a promise to call.","I promise I will be careful."],"tip":"Use “promise to do something” or “promise someone that…” to state a commitment.","course":"en","breakdown":"A statement that you will do something; or to say that you will do it.","related":"pledge; assure; commitment","categories":["Actions"],"senses":[{"part":"noun","definition":"A statement that someone will certainly do or not do something.","definitionZh":"承诺；保证；诺言","examples":["He made a promise to call.","She kept her promise to return the book."]},{"part":"verb","definition":"To tell someone that you will certainly do or not do something.","definitionZh":"向某人保证自己一定会做或不会做某事。","examples":["I promise to call you tomorrow.","He promised his parents that he would be careful."]}]},{"word":"protect","part":"verb","phonetic":"/prəˈtekt/","definition":"To keep someone or something safe from harm, damage, or danger.","definitionZh":"保护；防护","examples":["Sunscreen helps protect your skin.","The law protects consumers."],"tip":"Use “protect someone/something from” danger or “protect against” a particular risk.","course":"en","breakdown":"To keep someone or something safe from harm, damage, or danger.","related":"guard; defend; shelter","categories":["Actions"],"senses":[{"part":"verb","definition":"To keep someone or something safe from harm, damage, or danger.","definitionZh":"保护；防护","examples":["Sunscreen helps protect your skin.","The law protects consumers."]}]},{"word":"prove","part":"verb","phonetic":"/pruːv/","definition":"To show that something is true by using facts, evidence, or clear reasoning.","definitionZh":"证明；证实","examples":["The test results prove that the method works.","Can you prove your claim?"],"tip":"Use “prove that…” for a claim; “prove someone wrong” means show their belief is incorrect.","course":"en","breakdown":"To show that something is true by using facts, evidence, or clear reasoning.","related":"demonstrate; show; evidence","categories":["Actions"],"senses":[{"part":"verb","definition":"To show that something is true by using facts, evidence, or clear reasoning.","definitionZh":"证明；证实","examples":["The test results prove that the method works.","Can you prove your claim?"]}]},{"word":"publish","part":"verb","phonetic":"/ˈpʌblɪʃ/","definition":"To prepare and make written or digital material available to the public.","definitionZh":"出版；发表；发布","examples":["The author will publish a new book.","The results were published online."],"tip":"A book, article, or report is published; the person or organisation makes it available to the public.","course":"en","breakdown":"To prepare and make written or digital material available to the public.","related":"release; print; issue","categories":["Actions"],"senses":[{"part":"verb","definition":"To prepare and make written or digital material available to the public.","definitionZh":"出版；发表；发布","examples":["The author will publish a new book.","The results were published online."]}]},{"word":"pull","part":"verb / noun","phonetic":"/pʊl/","definition":"To use force to move something toward yourself; or the act of doing so.","definitionZh":"拉；拖；吸引力","examples":["Pull the door gently to open it.","Give the handle a firm pull."],"tip":"“Pull” moves something toward the person applying force; its opposite is usually “push”.","course":"en","breakdown":"To use force to move something toward yourself; or the act of doing so.","related":"draw; drag; tug","categories":["Actions"],"senses":[{"part":"verb","definition":"To use force to move something toward yourself or in a particular direction.","definitionZh":"拉；拖；拽","examples":["Pull the door gently to open it."]},{"part":"noun","definition":"An act of using force to move something towards yourself; an influence or attraction.","definitionZh":"用力将某物拉向自己的动作；吸引力或影响力。","examples":["The child gave the rope a strong pull.","The campaign gained a strong pull with younger voters."]}]},{"word":"push","part":"verb / noun","phonetic":"/pʊʃ/","definition":"To use force to move something away from yourself; or an effort to make progress.","definitionZh":"推；推动；努力","examples":["Push the button to start the machine.","The team made a final push to finish."],"tip":"“Push” moves something away or forward; it can also mean encourage an idea or effort.","course":"en","breakdown":"To use force to move something away from yourself; or an effort to make progress.","related":"press; shove; drive","categories":["Actions"],"senses":[{"part":"verb","definition":"To use force to move something away from yourself or in a particular direction.","definitionZh":"推；推动","examples":["Push the button to start the machine."]},{"part":"noun","definition":"An act of moving something away with force; an organised effort to achieve something.","definitionZh":"用力向外推动的动作；为实现目标而作出的努力。","examples":["The door needs a hard push.","There is a new push to improve road safety."]}]},{"word":"receive","part":"verb","phonetic":"/rɪˈsiːv/","definition":"To get or accept something that is given, sent, or offered.","definitionZh":"收到；接收；接待","examples":["I received your message this morning.","The winner will receive a certificate."],"tip":"“Receive” is more formal than “get”; it does not normally take “from” unless the source is named.","course":"en","breakdown":"To get or accept something that is given, sent, or offered.","related":"get; accept; obtain","categories":["Actions"],"senses":[{"part":"verb","definition":"To get or accept something that is given, sent, or offered.","definitionZh":"收到；接收；接待","examples":["I received your message this morning.","The winner will receive a certificate."]}]},{"word":"reply","part":"verb / noun","phonetic":"/rɪˈplaɪ/","definition":"To answer someone by speaking, writing, or using a message; or the answer itself.","definitionZh":"回答；回复；答复","examples":["Please reply to my email by Friday.","I am still waiting for her reply."],"tip":"Use “reply to a message/person”; “reply” can be a verb or a noun.","course":"en","breakdown":"To answer someone by speaking, writing, or using a message; or the answer itself.","related":"answer; respond; response","categories":["Actions"],"senses":[{"part":"verb","definition":"To answer someone by speaking, writing, or sending a message.","definitionZh":"回答；回复；答复","examples":["Please reply to my email by Friday."]},{"part":"noun","definition":"An answer given by speaking, writing, or sending a message.","definitionZh":"通过说话、写作或发送消息作出的回答；答复。","examples":["I sent a reply to the invitation.","We are still waiting for their reply."]}]},{"word":"report","part":"noun / verb","phonetic":"/rɪˈpɔːrt/","definition":"A spoken or written account of information; or to give information about an event or situation.","definitionZh":"报告；报道；汇报","examples":["She wrote a report about the trip.","Please report any damage to the manager."],"tip":"Use “report on” a topic and “report something to” an authority or organisation.","course":"en","breakdown":"A spoken or written account of information; or to give information about an event or situation.","related":"account; describe; announce","categories":["Actions"],"senses":[{"part":"noun","definition":"A spoken or written account that gives information about an event, situation, or investigation.","definitionZh":"报告；报道；汇报","examples":["She wrote a report about the trip.","The report summarised the results of the survey."]},{"part":"verb","definition":"To give information about an event, situation, or problem, especially to an authority or the public.","definitionZh":"向有关方面或公众提供有关事件、情况或问题的信息；报告；报道。","examples":["Please report any damage to the manager.","The newspaper reported the result this morning."]}]},{"word":"rescue","part":"verb / noun","phonetic":"/ˈreskjuː/","definition":"To save someone or something from danger; or the act of saving them.","definitionZh":"营救；救援；救助","examples":["Firefighters rescued the family.","The rescue took several hours."],"tip":"“Rescue” usually means saving someone or something from danger, not simply helping with an ordinary task.","course":"en","breakdown":"To save someone or something from danger; or the act of saving them.","related":"save; recover; help","categories":["Actions"],"senses":[{"part":"verb","definition":"To save someone or something from danger or a difficult situation.","definitionZh":"营救；救援；救助","examples":["Firefighters rescued the family.","Firefighters rescued two people from the building."]},{"part":"noun","definition":"The act of saving someone or something from danger or difficulty.","definitionZh":"将某人或某物从危险或困境中救出的行为；营救；救援。","examples":["The rescue took several hours.","A rescue team arrived before sunset."]}]},{"word":"return","part":"verb / noun","phonetic":"/rɪˈtɜːrn/","definition":"To go or come back to a place, or to give something back; the act of coming back.","definitionZh":"返回；归还；回报","examples":["Please return the books next week.","She returned home after work."],"tip":"Use “return to a place” for going back and “return something to someone” for giving it back.","course":"en","breakdown":"To go or come back to a place, or to give something back; the act of coming back.","related":"come back; give back; restore","categories":["Actions"],"senses":[{"part":"verb","definition":"To go or come back to a place, or to give something back; the act of coming back.","definitionZh":"返回；归还；回报","examples":["Please return the books next week.","She returned home after work."]},{"part":"noun","definition":"The act of coming or going back to a place, or of giving something back.","definitionZh":"返回某地或归还某物的行为；回来；归还。","examples":["Her return to work was delayed.","The shop allows the return of unused items."]}]},{"word":"review","part":"noun / verb","phonetic":"/rɪˈvjuː/","definition":"A careful look at something to assess it; or to examine it again.","definitionZh":"评论；评审；复习；审查","examples":["I read a review before buying the phone.","Let's review the main points."],"tip":"A review can be an assessment or a study session; “review for an exam” means revise.","course":"en","breakdown":"A careful look at something to assess it; or to examine it again.","related":"assess; evaluate; revise","categories":["Actions"],"senses":[{"part":"noun","definition":"A careful examination or assessment of something; also a written or spoken opinion about a book, film, or product.","definitionZh":"评论；评审；复习；审查","examples":["I read a review before buying the phone.","The review praised the film's visual effects."]},{"part":"verb","definition":"To examine or consider something again, often to check it or make a decision.","definitionZh":"再次检查或考虑某事，通常是为了核实情况或作出决定。","examples":["The manager will review your application.","Let's review the main points before the test."]}]},{"word":"save","part":"verb","phonetic":"/seɪv/","definition":"To keep something for future use, prevent loss, or rescue someone from danger.","definitionZh":"保存；节省；拯救","examples":["Remember to save your work.","The lifeguard saved the swimmer."],"tip":"“Save” can mean keep for later, prevent loss, or rescue; the context makes the sense clear.","course":"en","breakdown":"To keep something for future use, prevent loss, or rescue someone from danger.","related":"keep; store; rescue","categories":["Actions"],"senses":[{"part":"verb","definition":"To keep something for future use, prevent loss, or rescue someone from danger.","definitionZh":"保存；节省；拯救","examples":["Remember to save your work.","The lifeguard saved the swimmer."]}]},{"word":"search","part":"noun / verb","phonetic":"/sɜːrtʃ/","definition":"An attempt to find someone or something; or to look carefully for it.","definitionZh":"搜索；搜寻；寻找","examples":["The police began a search of the area.","Search the website for more information."],"tip":"Use “search for something” when looking for it; “search a place” means examine that place.","course":"en","breakdown":"An attempt to find someone or something; or to look carefully for it.","related":"look for; seek; investigate","categories":["Actions"],"senses":[{"part":"noun","definition":"An attempt to find someone or something by looking carefully.","definitionZh":"搜索；搜寻；寻找","examples":["The police began a search of the area."]},{"part":"verb","definition":"To look carefully through a place or information to find someone or something.","definitionZh":"仔细查看某个地方或信息，以寻找某人或某物。","examples":["Police searched the building for evidence.","I searched online for a reliable guide."]}]},{"word":"select","part":"verb","phonetic":"/sɪˈlekt/","definition":"To choose someone or something from a group.","definitionZh":"选择；挑选；选拔","examples":["Select your preferred language.","The coach selected five players."],"tip":"“Select” is slightly more formal than “choose”; use “select from” when options are listed.","course":"en","breakdown":"To choose someone or something from a group.","related":"choose; pick; select","categories":["Actions"],"senses":[{"part":"verb","definition":"To choose someone or something from a group.","definitionZh":"选择；挑选；选拔","examples":["Select your preferred language.","The coach selected five players."]}]},{"word":"share","part":"verb / noun","phonetic":"/ʃer/","definition":"To use, have, or give something together with others; or one part of something divided among people.","definitionZh":"分享；共用；份额","examples":["We share the same office.","Please share your ideas with the group."],"tip":"Use “share something with someone”; “share in” means take part in a benefit or responsibility.","course":"en","breakdown":"To use, have, or give something together with others; or one part of something divided among people.","related":"divide; distribute; tell","categories":["Actions"],"senses":[{"part":"verb","definition":"To use, have, or give something together with others; or one part of something divided among people.","definitionZh":"分享；共用；份额","examples":["We share the same office.","Please share your ideas with the group."]},{"part":"noun","definition":"A part or amount of something that belongs or is given to one person or group.","definitionZh":"属于或分配给某个人或群体的一部分；份额。","examples":["Everyone should receive a fair share.","She owns a small share of the company."]}]},{"word":"solve","part":"verb","phonetic":"/sɑːlv/","definition":"To find an answer to a problem or explain something difficult.","definitionZh":"解决；解答","examples":["We worked together to solve the puzzle.","The team solved the problem quickly."],"tip":"You solve a problem, puzzle, or mystery; you do not usually “solve a person”.","course":"en","breakdown":"To find an answer to a problem or explain something difficult.","related":"resolve; answer; work out","categories":["Actions"],"senses":[{"part":"verb","definition":"To find an answer to a problem or explain something difficult.","definitionZh":"解决；解答","examples":["We worked together to solve the puzzle.","The team solved the problem quickly."]}]},{"word":"survive","part":"verb","phonetic":"/sərˈvaɪv/","definition":"To stay alive or continue to exist despite danger, difficulty, or change.","definitionZh":"幸存；生存；继续存在","examples":["Few plants survive in this dry soil.","The business survived a difficult year."],"tip":"Use “survive an event” or “survive on something” when describing what keeps someone alive.","course":"en","breakdown":"To stay alive or continue to exist despite danger, difficulty, or change.","related":"live; endure; outlast","categories":["Actions"],"senses":[{"part":"verb","definition":"To stay alive or continue to exist despite danger, difficulty, or change.","definitionZh":"幸存；生存；继续存在","examples":["Few plants survive in this dry soil.","The business survived a difficult year."]}]},{"word":"throw","part":"verb / noun","phonetic":"/θroʊ/","definition":"To send something through the air using your hand; or the act of doing so.","definitionZh":"投；扔；抛；投掷","examples":["Throw the ball to me.","He made a long throw across the field."],"tip":"Use “throw something to someone” when they can catch it, and “throw something at” when aiming at them.","course":"en","breakdown":"To send something through the air using your hand; or the act of doing so.","related":"toss; cast; hurl","categories":["Actions"],"senses":[{"part":"verb","definition":"To send something through the air using your hand.","definitionZh":"投；扔；抛；投掷","examples":["Throw the ball to me."]},{"part":"noun","definition":"An act of sending something through the air with the hand.","definitionZh":"用手将某物抛向空中的动作；投掷。","examples":["His first throw landed near the target.","The player made a long throw across the field."]}]},{"word":"volunteer","part":"noun / verb","phonetic":"/ˌvɑːlənˈtɪr/","definition":"A person who freely offers to do something without being paid; or to offer to do it.","definitionZh":"志愿者；自愿做；主动提出","examples":["A volunteer helped at the event.","She volunteered to lead the group."],"tip":"Use “volunteer to do something”; a volunteer is someone who offers help without being paid.","course":"en","breakdown":"A person who freely offers to do something without being paid; or to offer to do it.","related":"offer; helper; contribute","categories":["Actions"],"senses":[{"part":"noun","definition":"A person who freely offers to do something, usually without being paid.","definitionZh":"志愿者","examples":["A volunteer helped at the event."]},{"part":"verb","definition":"To offer to do something willingly, without being asked or expecting payment.","definitionZh":"主动提出自愿做某事，通常不要求报酬。","examples":["She volunteered to organise the event.","Several students volunteered to help."]}]},{"word":"vote","part":"noun / verb","phonetic":"/voʊt/","definition":"A choice made in an election or decision; or to express that choice formally.","definitionZh":"投票；选举；选票","examples":["Every member has the right to vote.","The final vote takes place tomorrow."],"tip":"Use “vote for” a candidate or option and “vote on” a question or proposal.","course":"en","breakdown":"A choice made in an election or decision; or to express that choice formally.","related":"elect; ballot; choose","categories":["Actions"],"senses":[{"part":"noun","definition":"A choice expressed in an election or formal decision-making process; the act or result of voting.","definitionZh":"投票；选票；表决","examples":["The final vote takes place tomorrow.","The proposal received a majority of votes."]},{"part":"verb","definition":"To make a formal choice in an election or decision.","definitionZh":"在选举或正式决策中表达自己的选择；投票。","examples":["Residents will vote for a new council member.","The committee voted on the proposal."]}]},{"word":"warn","part":"verb","phonetic":"/wɔːrn/","definition":"To tell someone about a possible danger or problem so they can be careful.","definitionZh":"警告；提醒；预先通知","examples":["The sign warns drivers about the sharp turn.","I warned him not to touch the wire."],"tip":"Use “warn someone about/of a danger” or “warn someone not to do something”.","course":"en","breakdown":"To tell someone about a possible danger or problem so they can be careful.","related":"alert; caution; advise","categories":["Actions"],"senses":[{"part":"verb","definition":"To tell someone about a possible danger or problem so they can be careful.","definitionZh":"警告；提醒；预先通知","examples":["The sign warns drivers about the sharp turn.","I warned him not to touch the wire."]}]},{"word":"waste","part":"noun / verb","phonetic":"/weɪst/","definition":"To use more time, money, or material than necessary; or something that is not used effectively.","definitionZh":"浪费；废弃物；无用之物","examples":["Do not waste clean water.","Food waste is a serious problem."],"tip":"Use “waste time/money” for using resources badly; “a waste of” is the common noun pattern.","course":"en","breakdown":"To use more time, money, or material than necessary; or something that is not used effectively.","related":"squander; misuse; spend","categories":["Actions"],"senses":[{"part":"noun","definition":"To use more time, money, or material than necessary; or something that is not used effectively.","definitionZh":"浪费；废弃物；无用之物","examples":["Do not waste clean water.","Food waste is a serious problem."]},{"part":"verb","definition":"To use time, money, or another resource carelessly or without a useful result.","definitionZh":"不恰当地使用时间、金钱或其他资源，使其未能发挥应有作用；浪费。","examples":["Do not waste your time on unreliable sources.","We wasted a lot of food at the event."]}]},{"word":"worry","part":"verb / noun","phonetic":"/ˈwɜːri/","definition":"To feel anxious about something; or a feeling of anxiety.","definitionZh":"担心；忧虑；烦恼","examples":["Try not to worry about the result.","Money is a constant worry for him."],"tip":"Use “worry about” a problem; “worry someone” means cause that person to feel anxious.","course":"en","breakdown":"To feel anxious about something; or a feeling of anxiety.","related":"anxiety; concern; fret","categories":["Actions"],"senses":[{"part":"verb","definition":"To feel anxious or troubled about something that may happen or has happened.","definitionZh":"担心；忧虑；烦恼","examples":["Try not to worry about the result."]},{"part":"noun","definition":"A feeling of anxiety about a problem or something that may happen.","definitionZh":"对问题或可能发生的事情感到焦虑；担忧；烦恼。","examples":["Money is a constant worry for some families.","Her biggest worry was missing the flight."]}]},{"word":"business","part":"noun","phonetic":"/ˈbɪznəs/","definition":"An organisation that sells goods or services, or the activity of buying and selling for profit.","definitionZh":"企业；生意；商业；事务","examples":["She runs a small business.","Business was slow during the holiday."],"tip":"“Business” is usually uncountable when referring to commercial activity, but countable for a company: “a business”.","course":"en","breakdown":"An organisation that sells goods or services, or the activity of buying and selling for profit.","related":"company; trade; commerce","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An organisation that sells goods or services, or the activity of buying and selling for profit.","definitionZh":"企业；生意；商业；事务","examples":["She runs a small business.","Business was slow during the holiday."]}]},{"word":"cost","part":"noun / verb","phonetic":"/kɔːst/","definition":"The amount of money needed to buy or do something; or to require that amount.","definitionZh":"费用；成本；花费","examples":["The cost of travel has increased.","How much does the repair cost?"],"tip":"The noun “cost” is the amount paid; the verb often follows the pattern “cost someone an amount”.","course":"en","breakdown":"The amount of money needed to buy or do something; or to require that amount.","related":"price; expense; charge","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The amount of money, time, or effort needed to buy, do, or achieve something.","definitionZh":"费用；成本；花费","examples":["The cost of travel has increased."]},{"part":"verb","definition":"To require a particular amount of money, time, or effort.","definitionZh":"需要花费一定数量的金钱、时间或精力。","examples":["The tickets cost twenty dollars each.","The mistake cost us several hours."]}]},{"word":"country","part":"noun","phonetic":"/ˈkʌntri/","definition":"An area of land with its own government, people, and borders; or land outside towns and cities.","definitionZh":"国家；乡村；农村地区","examples":["Malaysia is a country in Southeast Asia.","They moved from the city to the country."],"tip":"“Country” means a nation in political contexts, but can mean rural areas in expressions like “in the country”.","course":"en","breakdown":"An area of land with its own government, people, and borders; or land outside towns and cities.","related":"nation; state; countryside","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An area of land with its own government, people, and borders; or land outside towns and cities.","definitionZh":"国家；乡村；农村地区","examples":["Malaysia is a country in Southeast Asia.","They moved from the city to the country."]}]},{"word":"course","part":"noun","phonetic":"/kɔːrs/","definition":"A series of lessons on a subject, a direction of movement, or one part of a meal.","definitionZh":"课程；过程；路线；一道菜","examples":["I signed up for an English course.","The main course arrived late."],"tip":"A course can be a series of lessons, a direction, or one part of a meal; context identifies the meaning.","course":"en","breakdown":"A series of lessons on a subject, a direction of movement, or one part of a meal.","related":"class; programme; route","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A series of lessons on a subject, a direction of movement, or one part of a meal.","definitionZh":"课程；过程；路线；一道菜","examples":["I signed up for an English course.","The main course arrived late."]}]},{"word":"culture","part":"noun","phonetic":"/ˈkʌltʃər/","definition":"The shared customs, beliefs, arts, and way of life of a group or society.","definitionZh":"文化；文明；修养","examples":["Food is an important part of culture.","The museum celebrates local culture."],"tip":"“Culture” often refers to shared practices and values; “cultural” is the adjective.","course":"en","breakdown":"The shared customs, beliefs, arts, and way of life of a group or society.","related":"custom; tradition; society","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The shared customs, beliefs, arts, and way of life of a group or society.","definitionZh":"文化；文明；修养","examples":["Food is an important part of culture.","The museum celebrates local culture."]}]},{"word":"customer","part":"noun","phonetic":"/ˈkʌstəmər/","definition":"A person or organisation that buys goods or services from a business.","definitionZh":"顾客；客户","examples":["The customer asked for a receipt.","Good service keeps customers coming back."],"tip":"A customer buys goods or services; “client” is more common for professional or advisory services.","course":"en","breakdown":"A person or organisation that buys goods or services from a business.","related":"buyer; client; shopper","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A person or organisation that buys goods or services from a business.","definitionZh":"顾客；客户","examples":["The customer asked for a receipt.","Good service keeps customers coming back."]}]},{"word":"direction","part":"noun","phonetic":"/dəˈrekʃən/","definition":"The way in which someone or something moves or faces; or instructions about where to go.","definitionZh":"方向；方位；指示；说明","examples":["Which direction is the station?","Follow the directions on the label."],"tip":"Use “in the direction of” for movement and “directions” for instructions on how to get somewhere.","course":"en","breakdown":"The way in which someone or something moves or faces; or instructions about where to go.","related":"route; instruction; orientation","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The way in which someone or something moves or faces; or instructions about where to go.","definitionZh":"方向；方位；指示；说明","examples":["Which direction is the station?","Follow the directions on the label."]}]},{"word":"effect","part":"noun","phonetic":"/ɪˈfekt/","definition":"A change or result caused by an action, event, or condition.","definitionZh":"影响；效果；结果","examples":["The medicine had a positive effect.","We studied the effects of air pollution."],"tip":"“Effect” is usually a noun meaning result; “affect” is usually the verb meaning influence.","course":"en","breakdown":"A change or result caused by an action, event, or condition.","related":"result; consequence; impact","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A change or result caused by an action, event, or condition.","definitionZh":"影响；效果；结果","examples":["The medicine had a positive effect.","We studied the effects of air pollution."]}]},{"word":"end","part":"noun / verb","phonetic":"/end/","definition":"The final part or point of something; or to bring something to a finish.","definitionZh":"结束；末端；终点","examples":["We walked to the end of the road.","The meeting will end at noon."],"tip":"“At the end” refers to a final point; “in the end” means finally or after everything is considered.","course":"en","breakdown":"The final part or point of something; or to bring something to a finish.","related":"finish; conclusion; stop","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The final part, point, or stage of something.","definitionZh":"结束；末端；终点","examples":["We walked to the end of the road."]},{"part":"verb","definition":"To bring an activity, event, or period of time to a finish.","definitionZh":"使活动、事件或一段时间结束；终止。","examples":["The meeting ended at noon.","They ended the discussion with a clear decision."]}]},{"word":"event","part":"noun","phonetic":"/ɪˈvent/","definition":"Something that happens, especially something planned or important; or a public activity.","definitionZh":"事件；活动；赛事","examples":["The school organised a sports event.","It was an important event in her life."],"tip":"An event may be planned or significant; “eventually” means in the end, not at an event.","course":"en","breakdown":"Something that happens, especially something planned or important; or a public activity.","related":"occasion; happening; function","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Something that happens, especially something planned or important; or a public activity.","definitionZh":"事件；活动；赛事","examples":["The school organised a sports event.","It was an important event in her life."]}]},{"word":"example","part":"noun","phonetic":"/ɪɡˈzæmpəl/","definition":"A person or thing that shows what something is like or how it works.","definitionZh":"例子；实例；榜样","examples":["Can you give me an example?","Her actions set a good example."],"tip":"Use “for example” to introduce an illustration and “an example of” to identify a type.","course":"en","breakdown":"A person or thing that shows what something is like or how it works.","related":"instance; sample; illustration","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A person or thing that shows what something is like or how it works.","definitionZh":"例子；实例；榜样","examples":["Can you give me an example?","Her actions set a good example."]}]},{"word":"fact","part":"noun","phonetic":"/fækt/","definition":"Something that is known or proven to be true.","definitionZh":"事实；真相","examples":["It is a fact that water freezes at low temperatures.","Check the facts before sharing the story."],"tip":"Use “in fact” to add or correct information; “as a matter of fact” is a similar expression.","course":"en","breakdown":"Something that is known or proven to be true.","related":"truth; detail; evidence","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Something that is known or proven to be true.","definitionZh":"事实；真相","examples":["It is a fact that water freezes at low temperatures.","Check the facts before sharing the story."]}]},{"word":"family","part":"noun","phonetic":"/ˈfæməli/","definition":"A group of people related by birth, marriage, or close bonds.","definitionZh":"家庭；家人；家族","examples":["My family meets every Sunday.","This is a family restaurant."],"tip":"“Family” can take a singular or plural verb depending on whether the group or its members are emphasised.","course":"en","breakdown":"A group of people related by birth, marriage, or close bonds; or intended for families.","related":"relatives; household; kin","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A group of people related by birth, marriage, or close bonds; or intended for families.","definitionZh":"家庭；家人；家族；适合家庭的","examples":["My family meets every Sunday.","This is a family restaurant."]}]},{"word":"feature","part":"noun / verb","phonetic":"/ˈfiːtʃər/","definition":"An important or noticeable part of something; or to include someone or something as a main part.","definitionZh":"特征；特点；特色；以……为特色","examples":["The phone has a useful safety feature.","The programme features local artists."],"tip":"A feature is a noticeable part or function; “feature” as a verb means include prominently.","course":"en","breakdown":"An important or noticeable part of something; or to include someone or something as a main part.","related":"quality; characteristic; highlight","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An important or noticeable part, quality, or characteristic of something.","definitionZh":"特征；特点；特色","examples":["The phone has a useful safety feature."]},{"part":"verb","definition":"To include or present someone or something as an important part.","definitionZh":"将某人或某物作为重要部分纳入或呈现；以……为特色。","examples":["The exhibition features work by local artists.","The app will feature a new search tool."]}]},{"word":"field","part":"noun","phonetic":"/fiːld/","definition":"An open area of land, often used for farming or sport; or an area of study or work.","definitionZh":"田地；场地；领域；专业","examples":["The children played in the field.","She works in the field of education."],"tip":"“Field” can refer to land, a subject of study, or a professional area; phrases such as “field of work” are common.","course":"en","breakdown":"An open area of land, often used for farming or sport; or an area of study or work.","related":"area; sector; ground","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An open area of land, often used for farming or sport; or an area of study or work.","definitionZh":"田地；场地；领域；专业","examples":["The children played in the field.","She works in the field of education."]}]},{"word":"figure","part":"noun / verb","phonetic":"/ˈfɪɡjər/","definition":"A number or amount, a person's shape, or a person of importance; also to calculate or understand.","definitionZh":"数字；金额；人物；身形；认为","examples":["The latest figures show an increase.","I cannot figure out how the device works."],"tip":"“Figure” has several common meanings; “figure out” means understand or solve something.","course":"en","breakdown":"A number or amount, a person's shape, or a person of importance; also to calculate or understand.","related":"number; shape; person; calculate","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A number or amount, a person's shape, or a person of importance; also to calculate or understand.","definitionZh":"数字；金额；人物；身形；认为","examples":["The latest figures show an increase.","I cannot figure out how the device works."]},{"part":"verb","definition":"To calculate or work out an amount, or to think or believe something.","definitionZh":"计算或弄清某个数额；认为；推断。","examples":["We need to figure out the total cost.","I figured that she would arrive later."]}]},{"word":"food","part":"noun","phonetic":"/fuːd/","definition":"Things that people or animals eat to live and grow.","definitionZh":"食物；食品","examples":["Fresh food is available at the market.","The children prepared food together."],"tip":"“Food” is generally uncountable; use “a food” only when referring to a particular type.","course":"en","breakdown":"Things that people or animals eat to live and grow.","related":"meal; dish; cuisine","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Things that people or animals eat to live and grow.","definitionZh":"食物；食品","examples":["Fresh food is available at the market.","The children prepared food together."]}]},{"word":"form","part":"noun / verb","phonetic":"/fɔːrm/","definition":"The shape or structure of something, a document to complete, or to create or develop something.","definitionZh":"形式；形状；表格；形成","examples":["Please fill in this form.","Clouds began to form over the hills."],"tip":"“Fill in a form” is common in British English; “fill out a form” is common in American English.","course":"en","breakdown":"The shape or structure of something, a document to complete, or to create or develop something.","related":"shape; type; document","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The shape or structure of something, a document to complete, or to create or develop something.","definitionZh":"形式；形状；表格；形成","examples":["Please fill in this form.","Please complete the form before the interview."]},{"part":"verb","definition":"To create, develop, or come together into a particular shape or group.","definitionZh":"形成、建立或聚集成某种形状或群体。","examples":["The students formed a line outside.","Clouds began to form over the hills."]}]},{"word":"front","part":"noun / adjective","phonetic":"/frʌnt/","definition":"The part or side that faces forward or is most visible; or located at the forward part.","definitionZh":"前面；正面；前部的","examples":["Wait for me at the front of the building.","The front door was open."],"tip":"Use “in front of” for position; “at the front” refers to the leading part of a group or place.","course":"en","breakdown":"The part or side that faces forward or is most visible; or located at the forward part.","related":"ahead; forward; back","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The part or side that faces forward or is most visible; or located at the forward part.","definitionZh":"前面；正面；前部的","examples":["Wait for me at the front of the building.","The front door was open."]},{"part":"adjective","definition":"Located at or relating to the forward part of something.","definitionZh":"位于某物前部的；与正面有关的。","examples":["Please use the front entrance.","The front seats were already taken."]}]},{"word":"future","part":"noun / adjective","phonetic":"/ˈfjuːtʃər/","definition":"The time that is yet to come; or relating to that time.","definitionZh":"未来；将来；未来的","examples":["We are planning for the future.","She hopes to study abroad in the future."],"tip":"Use “in the future” for a later time; “future” can also describe a person or event expected later.","course":"en","breakdown":"The time that is yet to come; or relating to that time.","related":"coming; upcoming; later","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The time that is yet to come; or relating to that time.","definitionZh":"未来；将来；未来的","examples":["We are planning for the future.","She hopes to study abroad in the future."]},{"part":"adjective","definition":"Relating to a time that has not yet happened.","definitionZh":"与尚未到来的时间有关的；未来的。","examples":["We need to consider future costs.","Future generations will use this technology."]}]},{"word":"grade","part":"noun / verb","phonetic":"/ɡreɪd/","definition":"A level or mark showing quality or achievement; or to assess and assign such a level.","definitionZh":"等级；成绩；年级；评分","examples":["He received a high grade in science.","The teacher will grade the essays."],"tip":"“Grade” can mean a school year, a quality level, or a mark; usage varies by region.","course":"en","breakdown":"A level or mark showing quality or achievement; or to assess and assign such a level.","related":"mark; level; score","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A level or mark showing quality, standard, or achievement; also a school year or level.","definitionZh":"等级；成绩；年级","examples":["He received a high grade in science."]},{"part":"verb","definition":"To assess work or performance and assign a mark or level.","definitionZh":"评估作业或表现，并给予分数或等级；评分。","examples":["Teachers grade the exams next week.","The essays were graded fairly."]}]},{"word":"ground","part":"noun / verb","phonetic":"/ɡraʊnd/","definition":"The surface of the earth; a reason or basis for something; or to place something on the ground.","definitionZh":"地面；土地；理由；基础","examples":["The ground was wet after the rain.","There are good grounds for concern."],"tip":"“On the ground” refers to the surface; “grounds” can mean reasons or land around a building.","course":"en","breakdown":"The surface of the earth; a reason or basis for something; or to place something on the ground.","related":"earth; floor; basis","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The surface of the earth; a reason or basis for something.","definitionZh":"地面；土地；理由；基础","examples":["The ground was wet after the rain.","There are good grounds for concern."]},{"part":"verb","definition":"To prevent an aircraft or person from leaving, or to establish something on a firm basis.","definitionZh":"禁止飞机起飞或限制某人外出；使某事建立在可靠基础上。","examples":["Heavy fog grounded several flights.","The report grounds its conclusions in clear evidence."]}]},{"word":"group","part":"noun / verb","phonetic":"/ɡruːp/","definition":"A number of people or things considered together; or to put them together.","definitionZh":"群体；组；团体；分组","examples":["Our group finished the project early.","Group the words by meaning."],"tip":"Use “a group of” before a plural noun; the verb “group” means arrange things together.","course":"en","breakdown":"A number of people or things considered together; or to put them together.","related":"team; collection; crowd","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A number of people or things considered together because they share something.","definitionZh":"群体；组；团体","examples":["Our group finished the project early."]},{"part":"verb","definition":"To arrange people or things into sets according to shared features.","definitionZh":"根据共同特征将人或事物归类或分组。","examples":["Please group the words by topic.","The students were grouped according to their level."]}]},{"word":"growth","part":"noun","phonetic":"/ɡroʊθ/","definition":"The process of becoming larger, developing, or increasing in amount or importance.","definitionZh":"成长；生长；增长；发展","examples":["The plant's growth slowed in winter.","The company reported strong growth."],"tip":"“Growth” is uncountable when describing development in general; use “growth in” for an increase.","course":"en","breakdown":"The process of becoming larger, developing, or increasing in amount or importance.","related":"development; increase; progress","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The process of becoming larger, developing, or increasing in amount or importance.","definitionZh":"成长；生长；增长；发展","examples":["The plant's growth slowed in winter.","The company reported strong growth."]}]},{"word":"half","part":"noun / adjective / adverb","phonetic":"/hæf/","definition":"One of two equal parts of something; or an amount equal to one of those parts.","definitionZh":"一半；半个；一半的","examples":["I ate half of the sandwich.","The journey took half an hour."],"tip":"Use “half of” before a noun or pronoun; “half” can also work as an adjective, as in “half an hour”.","course":"en","breakdown":"One of two equal parts of something; or an amount equal to one of those parts.","related":"one-half; partly; middle","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"One of two equal parts of something; or an amount equal to one of those parts.","definitionZh":"一半；半个；一半的","examples":["I ate half of the sandwich.","The journey took half an hour."]},{"part":"adjective","definition":"Equal to one of two parts of something; partly or not complete.","definitionZh":"相当于某物两个部分之一的；不完全的；半个的。","examples":["We spent half a day at the museum.","The half-empty bottle was on the table."]},{"part":"adverb","definition":"To a degree that is about 50 percent or not complete.","definitionZh":"达到约一半的程度；不完全地。","examples":["I was only half listening to the conversation.","The job was half finished when the rain started."]}]},{"word":"history","part":"noun","phonetic":"/ˈhɪstəri/","definition":"The study or record of past events, especially those involving people and societies.","definitionZh":"历史；历史学；经历","examples":["We learned about the history of the city.","The building has a long history."],"tip":"“History” is the study or record of the past; “a history of” can describe a person's past experience.","course":"en","breakdown":"The study or record of past events, especially those involving people and societies.","related":"past; record; historical","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The study or record of past events, especially those involving people and societies.","definitionZh":"历史；历史学；经历","examples":["We learned about the history of the city.","The building has a long history."]}]},{"word":"idea","part":"noun","phonetic":"/aɪˈdiːə/","definition":"A thought, plan, or suggestion formed in the mind.","definitionZh":"想法；主意；概念","examples":["That is a great idea.","She has an idea for a new project."],"tip":"Use “an idea for” a plan and “an idea of” an understanding or impression.","course":"en","breakdown":"A thought, plan, or suggestion formed in the mind.","related":"thought; concept; suggestion","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A thought, plan, or suggestion formed in the mind.","definitionZh":"想法；主意；概念","examples":["That is a great idea.","She has an idea for a new project."]}]},{"word":"information","part":"noun","phonetic":"/ˌɪnfərˈmeɪʃən/","definition":"Facts or details that help someone understand something or make a decision.","definitionZh":"信息；资料；情报","examples":["The website provides useful information.","Please keep this information private."],"tip":"“Information” is uncountable: say “some information” or “a piece of information”, not “informations”.","course":"en","breakdown":"Facts or details that help someone understand something or make a decision.","related":"details; facts; data","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Facts or details that help someone understand something or make a decision.","definitionZh":"信息；资料；情报","examples":["The website provides useful information.","Please keep this information private."]}]},{"word":"item","part":"noun","phonetic":"/ˈaɪtəm/","definition":"A single thing in a list, group, or collection, especially one for sale or discussion.","definitionZh":"项目；物品；条目","examples":["Each item has a price label.","Choose one item from the list."],"tip":"“Item” is a neutral word for one thing in a list, set, or collection.","course":"en","breakdown":"A single thing in a list, group, or collection, especially one for sale or discussion.","related":"object; entry; product","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A single thing in a list, group, or collection, especially one for sale or discussion.","definitionZh":"项目；物品；条目","examples":["Each item has a price label.","Choose one item from the list."]}]},{"word":"level","part":"noun / adjective / verb","phonetic":"/ˈlevəl/","definition":"A position or amount on a scale; a floor or stage; or to make something flat or equal.","definitionZh":"水平；等级；层次；使平整","examples":["The water level is rising.","This course is suitable for your level."],"tip":"Use “level of” before an amount or quality; “level” can also be a verb meaning make flat.","course":"en","breakdown":"A position or amount on a scale; a floor or stage; or to make something flat or equal.","related":"stage; degree; standard","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A position or amount on a scale; a floor or stage in a building or process.","definitionZh":"水平；等级；层次","examples":["The water level is rising.","This course is suitable for your level."]},{"part":"adjective","definition":"Flat, even, or at the same height or amount.","definitionZh":"平坦的；水平的；处于相同高度或程度的。","examples":["Make sure the table is level.","The road is almost level here."]},{"part":"verb","definition":"To make a surface flat or bring things to the same height or amount.","definitionZh":"使表面平坦；使不同事物达到相同高度或水平。","examples":["Workers levelled the ground before laying the path.","The new policy aims to level the playing field for small businesses."]}]},{"word":"life","part":"noun","phonetic":"/laɪf/","definition":"The condition of being alive, the period during which someone lives, or the experiences of living.","definitionZh":"生命；生活；人生","examples":["Plant life depends on water and light.","She enjoys life in the city."],"tip":"“Life” is countable when referring to individual lives, but uncountable when describing life in general.","course":"en","breakdown":"The condition of being alive, the period during which someone lives, or the experiences of living.","related":"living; existence; lifetime","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The condition of being alive, the period during which someone lives, or the experiences of living.","definitionZh":"生命；生活；人生","examples":["Plant life depends on water and light.","She enjoys life in the city."]}]},{"word":"line","part":"noun / verb","phonetic":"/laɪn/","definition":"A long, narrow mark or shape; a row of people or things; or to form a row along something.","definitionZh":"线；线条；队伍；台词","examples":["Draw a straight line across the page.","We waited in line for tickets."],"tip":"“Line” can mean a row, a queue, a mark, or a sentence of text; “queue” is more common in British English.","course":"en","breakdown":"A long, narrow mark or shape; a row of people or things; or to form a row along something.","related":"row; queue; boundary","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A long, narrow mark or shape; a row of people or things.","definitionZh":"线；线条；队伍；台词","examples":["Draw a straight line across the page.","We waited in line for tickets."]},{"part":"verb","definition":"To cover the inside of something with a layer, or to form a row along an edge.","definitionZh":"用一层材料铺在某物内部；沿边缘排成一行。","examples":["Line the baking tray with paper.","Trees line both sides of the road."]}]},{"word":"list","part":"noun / verb","phonetic":"/lɪst/","definition":"A set of names, items, or details written one after another; or to write them down.","definitionZh":"清单；目录；列出","examples":["I made a shopping list.","Please list your main reasons."],"tip":"Use “a list of” for items collected together; “list” as a verb means write items down.","course":"en","breakdown":"A set of names, items, or details written one after another; or to write them down.","related":"record; catalogue; inventory","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A set of names, items, or details written one after another.","definitionZh":"清单；目录；列表","examples":["I made a shopping list."]},{"part":"verb","definition":"To write or state a series of names, items, or details.","definitionZh":"写下或说出一系列名称、项目或细节；列出。","examples":["Please list your three main goals.","The website lists all available courses."]}]},{"word":"location","part":"noun","phonetic":"/loʊˈkeɪʃən/","definition":"A particular place or position where someone or something is, or where an event happens.","definitionZh":"地点；位置；定位","examples":["The app can share your location.","They chose a quiet location for the event."],"tip":"“Location” is a general term for where something is; “venue” is more specific to an event.","course":"en","breakdown":"A particular place or position where someone or something is, or where an event happens.","related":"place; position; site","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A particular place or position where someone or something is, or where an event happens.","definitionZh":"地点；位置；定位","examples":["The app can share your location.","They chose a quiet location for the event."]}]},{"word":"loss","part":"noun","phonetic":"/lɔːs/","definition":"The fact of no longer having something, or the amount by which something decreases.","definitionZh":"失去；损失；亏损","examples":["The loss of power stopped the machine.","The company reported a financial loss."],"tip":"“Loss” is the noun; “lose” is the verb. Do not confuse “loss” with “loose”.","course":"en","breakdown":"The fact of no longer having something, or the amount by which something decreases.","related":"damage; decrease; absence","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The fact of no longer having something, or the amount by which something decreases.","definitionZh":"失去；损失；亏损","examples":["The loss of power stopped the machine.","The company reported a financial loss."]}]},{"word":"luck","part":"noun","phonetic":"/lʌk/","definition":"Good or bad things that happen by chance rather than through planning or effort.","definitionZh":"运气；幸运；机遇","examples":["Good luck with your exam.","We had bad luck with the weather."],"tip":"“Luck” is uncountable; use “good luck” to wish someone success.","course":"en","breakdown":"Good or bad things that happen by chance rather than through planning or effort.","related":"fortune; chance; fate","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Good or bad things that happen by chance rather than through planning or effort.","definitionZh":"运气；幸运；机遇","examples":["Good luck with your exam.","We had bad luck with the weather."]}]},{"word":"main","part":"adjective / noun","phonetic":"/meɪn/","definition":"The most important or largest part of something; the principal part.","definitionZh":"主要的；最重要的；主干","examples":["The main entrance is on the left.","Our main concern is safety."],"tip":"“Main” is usually an adjective and normally comes before a noun: “the main reason”.","course":"en","breakdown":"The most important or largest part of something; the principal part.","related":"chief; primary; principal","categories":["Everyday Terms"],"senses":[{"part":"adjective","definition":"The most important or largest part of something; the principal part.","definitionZh":"主要的；最重要的；主干","examples":["The main entrance is on the left.","Our main concern is safety."]},{"part":"noun","definition":"A principal pipe or cable that carries a public supply such as water or electricity.","definitionZh":"输送水、电等公共供应的主要管道或线路；主管道；干线。","examples":["A leak was found in the main.","The workers repaired the water main."]}]},{"word":"material","part":"noun / adjective","phonetic":"/məˈtɪriəl/","definition":"A substance used to make things, or information and resources used for a purpose; relating to physical things.","definitionZh":"材料；原料；资料；物质的","examples":["Wood is a common building material.","The teacher prepared reading material."],"tip":"“Material” can mean physical substance or information used for a task; “materials” often refers to supplies.","course":"en","breakdown":"A substance used to make things, or information and resources used for a purpose; relating to physical things.","related":"substance; fabric; resource","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A substance used to make things, or information and resources used for a purpose; relating to physical things.","definitionZh":"材料；原料；资料；物质的","examples":["Wood is a common building material.","The teacher prepared reading material."]},{"part":"adjective","definition":"Important or relevant enough to affect a decision or situation.","definitionZh":"重要到足以影响决定或情况的；实质性的。","examples":["The report contains no material errors.","There was a material difference between the two offers."]}]},{"word":"matter","part":"noun / verb","phonetic":"/ˈmætər/","definition":"A subject or situation to consider; physical substance; or to be important.","definitionZh":"事情；问题；物质；要紧","examples":["We need to discuss an important matter.","Your opinion matters to us."],"tip":"“Matter” can mean a topic or physical substance; as a verb, “it matters” means it is important.","course":"en","breakdown":"A subject or situation to consider; physical substance; or to be important.","related":"issue; subject; substance","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A subject or situation that needs to be considered; physical substance.","definitionZh":"事情；问题；物质","examples":["We need to discuss an important matter.","The matter was discussed at yesterday's meeting."]},{"part":"verb","definition":"To be important or have an effect on a situation.","definitionZh":"具有重要性；对某种情况产生影响；要紧。","examples":["Your opinion matters to us.","It does not matter which route we take."]}]},{"word":"meal","part":"noun","phonetic":"/miːl/","definition":"An occasion when people eat, or the food eaten at that time.","definitionZh":"一餐；饭；膳食","examples":["We had a simple meal at home.","Breakfast is my favourite meal."],"tip":"A meal is an occasion for eating; “dish” refers to a particular prepared food.","course":"en","breakdown":"An occasion when people eat, or the food eaten at that time.","related":"breakfast; lunch; dinner","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An occasion when people eat, or the food eaten at that time.","definitionZh":"一餐；饭；膳食","examples":["We had a simple meal at home.","Breakfast is my favourite meal."]}]},{"word":"memory","part":"noun","phonetic":"/ˈmeməri/","definition":"The ability to remember information or experiences; or something remembered.","definitionZh":"记忆力；记忆；回忆","examples":["Her memory is excellent.","That song brings back a happy memory."],"tip":"“Memory” can mean the ability to remember or a particular recollection; “memories” is common for past experiences.","course":"en","breakdown":"The ability to remember information or experiences; or something remembered.","related":"recollection; recall; remembrance","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The ability to remember information or experiences; or something remembered.","definitionZh":"记忆力；记忆；回忆","examples":["Her memory is excellent.","That song brings back a happy memory."]}]},{"word":"middle","part":"noun / adjective","phonetic":"/ˈmɪdəl/","definition":"The centre point or part between two ends; or located at the centre.","definitionZh":"中间；中央；中部的","examples":["Put the table in the middle of the room.","He arrived in the middle of the film."],"tip":"Use “in the middle of” for a central position or for something happening during an activity.","course":"en","breakdown":"The centre point or part between two ends; or located at the centre.","related":"centre; centre point; halfway","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The centre point or part between two ends; or located at the centre.","definitionZh":"中间；中央；中部的","examples":["Put the table in the middle of the room.","He arrived in the middle of the film."]},{"part":"adjective","definition":"Located at or near the centre of a place, period, or group.","definitionZh":"位于某个地点、时期或群体中央或附近的；中间的。","examples":["She is the middle child in her family.","We met in the middle section of the hall."]}]},{"word":"mind","part":"noun / verb","phonetic":"/maɪnd/","definition":"The part of a person that thinks, feels, and remembers; or to object to something.","definitionZh":"头脑；思想；介意","examples":["Keep an open mind when you listen.","Would you mind closing the window?"],"tip":"“Make up your mind” means decide; “Would you mind…?” is a polite way to make a request.","course":"en","breakdown":"The part of a person that thinks, feels, and remembers; or to object to something.","related":"thought; attention; opinion","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The part of a person that thinks, feels, remembers, and makes decisions.","definitionZh":"头脑；思想；心智","examples":["Keep an open mind when you listen."]},{"part":"verb","definition":"To object to something, be bothered by it, or be willing to take care of something.","definitionZh":"对某事介意或反对；愿意照看或处理某事。","examples":["Would you mind opening the window?","I do not mind waiting a few minutes."]}]},{"word":"moment","part":"noun","phonetic":"/ˈmoʊmənt/","definition":"A very short period of time, or a particular point in time.","definitionZh":"片刻；瞬间；时刻","examples":["Please wait a moment.","It was a special moment for the family."],"tip":"Use “in a moment” for very soon and “at the moment” for now.","course":"en","breakdown":"A very short period of time, or a particular point in time.","related":"instant; second; while","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A very short period of time, or a particular point in time.","definitionZh":"片刻；瞬间；时刻","examples":["Please wait a moment.","It was a special moment for the family."]}]},{"word":"money","part":"noun","phonetic":"/ˈmʌni/","definition":"What people use to buy goods and services, usually in the form of coins, notes, or digital balances.","definitionZh":"钱；金钱；货币","examples":["She saved money for a new laptop.","You can pay by card or with cash."],"tip":"“Money” is uncountable in ordinary use; say “some money” or “an amount of money”.","course":"en","breakdown":"What people use to buy goods and services, usually in the form of coins, notes, or digital balances.","related":"cash; funds; currency","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"What people use to buy goods and services, usually in the form of coins, notes, or digital balances.","definitionZh":"钱；金钱；货币","examples":["She saved money for a new laptop.","You can pay by card or with cash."]}]},{"word":"name","part":"noun / verb","phonetic":"/neɪm/","definition":"A word used to identify a person, place, or thing; or to give something a name.","definitionZh":"名字；名称；命名","examples":["Please write your name here.","They named the puppy Milo."],"tip":"Use “name someone/something” as a direct-object verb; “by name” identifies a person specifically.","course":"en","breakdown":"A word used to identify a person, place, or thing; or to give something a name.","related":"title; label; identify","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A word or set of words used to identify a person, place, or thing.","definitionZh":"名字；名称","examples":["Please write your name here.","Her name appears at the top of the list."]},{"part":"verb","definition":"To give someone or something a name, or to identify someone or something.","definitionZh":"给某人或某物取名；说出或指出某人或某物。","examples":["They named the puppy Milo.","Can you name three countries in Asia?"]}]},{"word":"news","part":"noun","phonetic":"/nuːz/","definition":"Information about recent events, especially when shared through television, newspapers, or the internet.","definitionZh":"新闻；消息；资讯","examples":["I heard the news this morning.","The local news starts at six."],"tip":"“News” looks plural but is grammatically singular: say “the news is”, not “the news are”.","course":"en","breakdown":"Information about recent events, especially when shared through television, newspapers, or the internet.","related":"report; update; information","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Information about recent events, especially when shared through television, newspapers, or the internet.","definitionZh":"新闻；消息；资讯","examples":["I heard the news this morning.","The local news starts at six."]}]},{"word":"noise","part":"noun","phonetic":"/nɔɪz/","definition":"A sound, especially one that is loud, unpleasant, or unwanted.","definitionZh":"噪音；声响；吵闹声","examples":["The noise kept me awake.","Please do not make noise in the library."],"tip":"“Noise” is usually uncountable; use “a noise” for one particular sound.","course":"en","breakdown":"A sound, especially one that is loud, unpleasant, or unwanted.","related":"sound; racket; disturbance","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A sound, especially one that is loud, unpleasant, or unwanted.","definitionZh":"噪音；声响；吵闹声","examples":["The noise kept me awake.","Please do not make noise in the library."]}]},{"word":"note","part":"noun / verb","phonetic":"/noʊt/","definition":"A short written record or message; or to notice and record something.","definitionZh":"笔记；便条；音符；注意到","examples":["I left a note on the desk.","Please note the change in time."],"tip":"“Take note of” means pay attention to; “make a note of” means write something down.","course":"en","breakdown":"A short written record or message; or to notice and record something.","related":"message; remark; notice","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A short written record or message; a musical sound or tone.","definitionZh":"笔记；便条；音符","examples":["I left a note on the desk."]},{"part":"verb","definition":"To notice something or record it for attention or future reference.","definitionZh":"注意到某事，或将其记录下来以便留意或日后参考。","examples":["Please note the change in opening hours.","She noted his name in her notebook."]}]},{"word":"number","part":"noun / verb","phonetic":"/ˈnʌmbər/","definition":"A mathematical symbol or amount; or to give things a position in a series.","definitionZh":"数字；号码；数量；编号","examples":["What is your phone number?","Number the pages from one to ten."],"tip":"Use “a number of” with a plural noun and plural verb; “the number of” takes a singular verb.","course":"en","breakdown":"A mathematical symbol or amount; or to give things a position in a series.","related":"figure; amount; total","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A mathematical symbol or amount; a quantity or identifying number.","definitionZh":"数字；号码；数量","examples":["What is your phone number?"]},{"part":"verb","definition":"To give items numbers in order, or to amount to a particular total.","definitionZh":"按顺序给项目编号；总数达到某个数量。","examples":["Number the pages before you submit the report.","The visitors numbered more than five hundred."]}]},{"word":"college","part":"noun","phonetic":"/ˈkɑːlɪdʒ/","definition":"An educational institution where people study after secondary school, often for a diploma or degree.","definitionZh":"学院；大学；专科学校","examples":["She plans to attend college next year.","The college offers courses in design and technology."],"tip":"The meaning and level of a college differ between countries.","course":"en","breakdown":"A place for further education after secondary school.","related":"university; student; campus","categories":["Education"],"senses":[{"part":"noun","definition":"An educational institution for study after secondary school.","definitionZh":"中学毕业后继续学习的教育机构；学院或大学。","examples":["He teaches at a local college.","My sister is applying to college."]}]},{"word":"countryside","part":"noun","phonetic":"/ˈkʌntrisaɪd/","definition":"Land and areas outside towns and cities, especially places with fields, villages, and natural scenery.","definitionZh":"乡村；农村地区；乡间","examples":["We spent the weekend in the countryside.","The countryside is quiet after sunset."],"tip":"“Countryside” usually refers to rural areas as a whole rather than one specific village.","course":"en","breakdown":"The rural area beyond towns and cities.","related":"rural; village; farmland","categories":["Places","Nature & Environment"],"senses":[{"part":"noun","definition":"Areas of land outside towns and cities, often with farms and natural landscapes.","definitionZh":"城镇和城市以外的地区，通常有农田和自然景观；乡村。","examples":["They moved to the countryside for a quieter life.","The countryside attracts visitors in spring."]}]},{"word":"court","part":"noun","phonetic":"/kɔːrt/","definition":"A place where legal cases are heard; an area marked for playing sports; or a formal group or royal household.","definitionZh":"法院；法庭；球场；宫廷","examples":["The case will be heard in court.","They practised tennis on the outdoor court."],"tip":"The meaning depends strongly on context: legal, sporting, or historical.","course":"en","breakdown":"A word used for legal venues, sports areas, and some formal institutions.","related":"judge; law; tennis; courtroom","categories":["Places","Everyday Terms"],"senses":[{"part":"noun — legal venue","definition":"A place or institution where a judge hears legal cases.","definitionZh":"法官审理法律案件的场所或机构；法院或法庭。","examples":["The witness arrived at court early.","The court delivered its decision."]},{"part":"noun — sports area","definition":"An area marked for playing a sport such as tennis or basketball.","definitionZh":"用于进行网球或篮球等运动的划定场地；球场。","examples":["The children played basketball on the court.","The tennis court was wet after the rain."]}]},{"word":"object","part":"noun","phonetic":"/ˈɑːbdʒekt/","definition":"A thing that can be seen or touched, rather than a person or idea.","definitionZh":"物体；物品；对象","examples":["She placed the small object on the table.","The museum displayed objects from daily life."],"tip":"Use “object” for a physical thing; in grammar and computing it can have more specific meanings.","course":"en","breakdown":"A thing that can be seen or touched, rather than a person or idea.","related":"item;thing","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A thing that can be seen or touched, rather than a person or idea.","definitionZh":"物体；物品；对象","examples":["She placed the small object on the table.","The museum displayed objects from daily life."]}]},{"word":"order","part":"noun / verb","phonetic":"/ˈɔːrdər/","definition":"A request for goods or food; an arrangement; or to ask for something to be supplied.","definitionZh":"订单；点餐；顺序；命令","examples":["We placed an order for two coffees.","Please put the books in alphabetical order."],"tip":"“In order” can mean arranged correctly; “order” can also mean to request or command.","course":"en","breakdown":"A request for goods or food; an arrangement; or to ask for something to be supplied.","related":"request;arrangement","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A request for goods or services, or the way things are arranged.","definitionZh":"订单；点餐；顺序；排列","examples":["We placed an order for a new dictionary.","The books are arranged in alphabetical order."]},{"part":"verb","definition":"To ask for goods or services to be supplied, or to tell someone to do something.","definitionZh":"订购；点餐；命令；指示","examples":["We ordered two cups of tea.","The manager ordered the team to leave."]}]},{"word":"owner","part":"noun","phonetic":"/ˈoʊnər/","definition":"A person or organisation that legally possesses something.","definitionZh":"所有者；主人；业主","examples":["The owner of the shop greeted us.","Please return the keys to their owner."],"tip":"Use “owner of” before the thing or place someone possesses.","course":"en","breakdown":"A person or organisation that legally possesses something.","related":"ownership;possessor","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A person or organisation that legally possesses something.","definitionZh":"所有者；主人；业主","examples":["The owner of the shop greeted us.","Please return the keys to their owner."]}]},{"word":"page","part":"noun","phonetic":"/peɪdʒ/","definition":"One side of a sheet in a book, magazine or document; or a section of a website.","definitionZh":"页；页面","examples":["Turn to page twelve, please.","The information is on the last page of the website."],"tip":"A page can be part of a printed book or a digital document.","course":"en","breakdown":"One side of a sheet in a book, magazine or document; or a section of a website.","related":"sheet;webpage","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"One side of a sheet in a book, magazine or document; or a section of a website.","definitionZh":"页；页面","examples":["Turn to page twelve, please.","The information is on the last page of the website."]}]},{"word":"pair","part":"noun","phonetic":"/per/","definition":"Two people or things that are used or considered together.","definitionZh":"一对；一双；一副","examples":["I bought a pair of comfortable shoes.","The pair of friends walked home together."],"tip":"Use “a pair of” with plural countable nouns, such as shoes or gloves.","course":"en","breakdown":"Two people or things that are used or considered together.","related":"couple;duo","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Two people or things that are used or considered together.","definitionZh":"一对；一双；一副","examples":["I bought a pair of comfortable shoes.","The pair of friends walked home together."]}]},{"word":"paper","part":"noun","phonetic":"/ˈpeɪpər/","definition":"Thin material used for writing or printing; also a newspaper, document or academic article.","definitionZh":"纸；报纸；文件；论文","examples":["Could you give me a piece of paper?","She presented her research in a scientific paper."],"tip":"“Paper” is usually uncountable when it means the material, but countable for a newspaper or article.","course":"en","breakdown":"Thin material used for writing or printing; also a newspaper, document or academic article.","related":"document;sheet","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Thin material used for writing or printing; also a newspaper, document or academic article.","definitionZh":"纸；报纸；文件；论文","examples":["Could you give me a piece of paper?","She presented her research in a scientific paper."]}]},{"word":"part","part":"noun","phonetic":"/pɑːrt/","definition":"A piece or section of something; or a role in an activity or performance.","definitionZh":"部分；部件；角色","examples":["This is the most difficult part of the task.","He played the main part in the school show."],"tip":"“Part of” means one section or member of a larger whole.","course":"en","breakdown":"A piece or section of something; or a role in an activity or performance.","related":"section;piece","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A piece or section of something; or a role in an activity or performance.","definitionZh":"部分；部件；角色","examples":["This is the most difficult part of the task.","He played the main part in the school show."]}]},{"word":"party","part":"noun","phonetic":"/ˈpɑːrti/","definition":"A social event where people meet for enjoyment; or a group involved in an agreement or activity.","definitionZh":"派对；聚会；一方；团体","examples":["We're having a small party on Saturday.","Both parties agreed to the new plan."],"tip":"In everyday conversation, “party” often means a celebration; in formal contexts it can mean a side in an agreement.","course":"en","breakdown":"A social event where people meet for enjoyment; or a group involved in an agreement or activity.","related":"celebration;group","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A social event where people meet for enjoyment; or a group involved in an agreement or activity.","definitionZh":"派对；聚会；一方；团体","examples":["We're having a small party on Saturday.","Both parties agreed to the new plan."]}]},{"word":"period","part":"noun","phonetic":"/ˈpɪriəd/","definition":"A length of time; or a lesson or stage within a timetable or process.","definitionZh":"时期；期间；课时","examples":["She lived in Japan for a short period.","Our next class is during the second period."],"tip":"“For a period of time” describes duration; “period” can also mean a punctuation mark in American English.","course":"en","breakdown":"A length of time; or a lesson or stage within a timetable or process.","related":"time;stage","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A length of time; or a lesson or stage within a timetable or process.","definitionZh":"时期；期间；课时","examples":["She lived in Japan for a short period.","Our next class is during the second period."]}]},{"word":"place","part":"noun / verb","phonetic":"/pleɪs/","definition":"A particular location or position; or to put something somewhere.","definitionZh":"地方；地点；位置；放置","examples":["This is a quiet place to study.","Please place your bag under the desk."],"tip":"“Place” can be a noun for a location or a verb meaning to put something somewhere.","course":"en","breakdown":"A particular location or position; or to put something somewhere.","related":"location;spot","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A particular location, area, or position.","definitionZh":"地方；地点；位置","examples":["This is a quiet place to read.","The place was crowded after lunch."]},{"part":"verb","definition":"To put or set something in a particular position.","definitionZh":"放置；安放；安排","examples":["Please place the keys on the table.","They placed the chairs in a circle."]}]},{"word":"position","part":"noun / verb","phonetic":"/pəˈzɪʃən/","definition":"The place where someone or something is; a job or role; or to put something in a particular place.","definitionZh":"位置；职位；立场；安置","examples":["The chairs are in the correct position.","She applied for a teaching position."],"tip":"The meaning may be physical location, employment, or someone's opinion, depending on context.","course":"en","breakdown":"The place where someone or something is; a job or role; or to put something in a particular place.","related":"location;role","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The place where someone or something is, a job or role, or an opinion on an issue.","definitionZh":"位置；职位；立场","examples":["The camera is in the correct position.","She applied for a teaching position."]},{"part":"verb","definition":"To put someone or something in a particular place or arrangement.","definitionZh":"安置；放置；使处于某个位置","examples":["Position the lamp beside the desk.","The team positioned the sign near the entrance."]}]},{"word":"power","part":"noun","phonetic":"/ˈpaʊər/","definition":"The ability or authority to control, influence or do something; or energy supplied to operate equipment.","definitionZh":"力量；权力；电力","examples":["The new manager has the power to make that decision.","The storm caused a power cut."],"tip":"“Power” can refer to authority, physical ability or electricity; check the context.","course":"en","breakdown":"The ability or authority to control, influence or do something; or energy supplied to operate equipment.","related":"authority;energy","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The ability or authority to control, influence or do something; or energy supplied to operate equipment.","definitionZh":"力量；权力；电力","examples":["The new manager has the power to make that decision.","The storm caused a power cut."]}]},{"word":"price","part":"noun / verb","phonetic":"/praɪs/","definition":"The amount of money needed to buy something; or to set that amount.","definitionZh":"价格；价钱；定价","examples":["The price of the ticket has increased.","The shop priced the items clearly."],"tip":"Use “price of” for the cost of something; “price” is different from “cost” in some contexts.","course":"en","breakdown":"The amount of money needed to buy something; or to set that amount.","related":"cost;fee","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The amount of money that must be paid to buy something or use a service.","definitionZh":"价格；价钱；费用","examples":["The price includes delivery.","We compared the prices of three models."]},{"part":"verb","definition":"To decide or state how much something will cost.","definitionZh":"给……定价；标价","examples":["The shop priced each item clearly.","They priced the tickets at twenty dollars."]}]},{"word":"problem","part":"noun","phonetic":"/ˈprɑːbləm/","definition":"A situation or matter that causes difficulty and needs attention or a solution.","definitionZh":"问题；难题；困难","examples":["We need to find a solution to this problem.","There was a problem with the train service."],"tip":"A problem is something difficult; a question is something asked to get information or an answer.","course":"en","breakdown":"A situation or matter that causes difficulty and needs attention or a solution.","related":"difficulty;issue","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A situation or matter that causes difficulty and needs attention or a solution.","definitionZh":"问题；难题；困难","examples":["We need to find a solution to this problem.","There was a problem with the train service."]}]},{"word":"product","part":"noun","phonetic":"/ˈprɑːdʌkt/","definition":"Something made or grown to be sold or used; or the result of multiplying numbers.","definitionZh":"产品；制品；乘积","examples":["This product is made from recycled materials.","The product of six and four is twenty-four."],"tip":"In shopping, a product is an item for sale; in mathematics, it is the result of multiplication.","course":"en","breakdown":"Something made or grown to be sold or used; or the result of multiplying numbers.","related":"item;goods","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Something made or grown to be sold or used; or the result of multiplying numbers.","definitionZh":"产品；制品；乘积","examples":["This product is made from recycled materials.","The product of six and four is twenty-four."]}]},{"word":"quality","part":"noun","phonetic":"/ˈkwɑːləti/","definition":"How good or bad something is; or a feature or characteristic of a person or thing.","definitionZh":"质量；品质；特征","examples":["The hotel is known for its high quality of service.","Patience is an important quality in a teacher."],"tip":"“Quality” can describe a level of excellence or a characteristic someone or something has.","course":"en","breakdown":"How good or bad something is; or a feature or characteristic of a person or thing.","related":"standard;characteristic","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"How good or bad something is; or a feature or characteristic of a person or thing.","definitionZh":"质量；品质；特征","examples":["The hotel is known for its high quality of service.","Patience is an important quality in a teacher."]}]},{"word":"reason","part":"noun / verb","phonetic":"/ˈriːzən/","definition":"An explanation for why something happens or is done; or to think logically.","definitionZh":"原因；理由；推理","examples":["What is the reason for the delay?","We reasoned that taking the earlier train would be safer."],"tip":"Use “reason for” to introduce a cause and “reason why” to introduce an explanation.","course":"en","breakdown":"An explanation for why something happens or is done; or to think logically.","related":"cause;explanation","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An explanation for why something happens or is done.","definitionZh":"原因；理由；解释","examples":["There is a good reason to wait.","She explained the reason for the change."]},{"part":"verb","definition":"To think logically about something in order to reach a conclusion.","definitionZh":"推理；思考；推断","examples":["We reasoned that the earlier train would be safer.","He reasoned through each step before deciding."]}]},{"word":"record","part":"noun / verb","phonetic":"/ˈrekərd/","definition":"Information kept for future reference; or to write down, store or capture information.","definitionZh":"记录；档案；录制","examples":["Keep a record of your expenses.","The camera records video in high definition."],"tip":"The noun is usually stressed on the first syllable (/ˈrekərd/); the verb is stressed on the second (/rɪˈkɔːrd/).","course":"en","breakdown":"Information kept for future reference; or to write down, store or capture information.","related":"document;log","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Information kept in written or digital form for future reference.","definitionZh":"记录；档案；纪录","examples":["Keep a record of your expenses.","The school has a record of every student's attendance."]},{"part":"verb","definition":"To write down, store, or capture information, sounds, or images.","definitionZh":"记录；录下；录制","examples":["The camera records video in high definition.","Please record the meeting's main points."]}]},{"word":"role","part":"noun","phonetic":"/roʊl/","definition":"The function or part that someone or something has in a situation, group or activity.","definitionZh":"角色；作用；职责","examples":["Everyone has a role to play in the project.","Parents play an important role in a child's development."],"tip":"Use “role in” to describe someone's function within an activity or situation.","course":"en","breakdown":"The function or part that someone or something has in a situation, group or activity.","related":"function;part","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The function or part that someone or something has in a situation, group or activity.","definitionZh":"角色；作用；职责","examples":["Everyone has a role to play in the project.","Parents play an important role in a child's development."]}]},{"word":"room","part":"noun","phonetic":"/ruːm/","definition":"A part of a building enclosed by walls; or space available for someone or something.","definitionZh":"房间；空间","examples":["There are two bedrooms in the apartment.","There isn't enough room for another chair."],"tip":"“Room” is countable for a separate space in a building, but often uncountable when it means available space.","course":"en","breakdown":"A part of a building enclosed by walls; or space available for someone or something.","related":"space;bedroom","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A part of a building enclosed by walls; or space available for someone or something.","definitionZh":"房间；空间","examples":["There are two bedrooms in the apartment.","There isn't enough room for another chair."]}]},{"word":"rule","part":"noun / verb","phonetic":"/ruːl/","definition":"An official or accepted instruction that controls what people may do; or to control or decide something.","definitionZh":"规则；规定；裁定","examples":["Every player must follow the rules.","The judge ruled that the evidence could be used."],"tip":"“Rule” can mean a regulation, while “rule out” means to decide that something is not possible.","course":"en","breakdown":"An official or accepted instruction that controls what people may do; or to control or decide something.","related":"regulation;law","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An official or accepted instruction that states what people may or may not do.","definitionZh":"规则；规定；条例","examples":["Every player must follow the rules.","The new rule applies to all visitors."]},{"part":"verb","definition":"To make an official decision, especially in a court, or to govern a place or group.","definitionZh":"裁定；判决；统治","examples":["The judge ruled that the evidence could be used.","The court ruled in favour of the applicant."]}]},{"word":"safety","part":"noun","phonetic":"/ˈseɪfti/","definition":"The condition of being protected from danger, injury or harm.","definitionZh":"安全；平安","examples":["Please read the safety instructions before using the machine.","The children arrived home in safety."],"tip":"“Safety” is usually uncountable; use “safe” as the adjective.","course":"en","breakdown":"The condition of being protected from danger, injury or harm.","related":"protection;security","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The condition of being protected from danger, injury or harm.","definitionZh":"安全；平安","examples":["Please read the safety instructions before using the machine.","The children arrived home in safety."]}]},{"word":"sample","part":"noun / verb","phonetic":"/ˈsæmpəl/","definition":"A small amount or example used to represent or test a larger group; or to try a small amount.","definitionZh":"样本；样品；试用","examples":["The shop gave us a free sample of the new drink.","Researchers sampled water from the river."],"tip":"A sample is a small part chosen to represent a larger whole.","course":"en","breakdown":"A small amount or example used to represent or test a larger group; or to try a small amount.","related":"specimen;example","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A small amount or example used to represent or test a larger group.","definitionZh":"样本；样品；标本","examples":["The shop gave us a free sample.","Researchers tested a sample of the water."]},{"part":"verb","definition":"To take or examine a small part of something to learn about the whole.","definitionZh":"抽样；取样；品尝","examples":["The lab sampled water from the river.","The survey sampled households in each district."]}]},{"word":"science","part":"noun","phonetic":"/ˈsaɪəns/","definition":"The systematic study of the natural world through observation and experiments.","definitionZh":"科学","examples":["Science helps us understand how the natural world works.","She is interested in science and technology."],"tip":"“Science” is generally uncountable when referring to the field of study.","course":"en","breakdown":"The systematic study of the natural world through observation and experiments.","related":"research;study","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The systematic study of the natural world through observation and experiments.","definitionZh":"科学","examples":["Science helps us understand how the natural world works.","She is interested in science and technology."]}]},{"word":"service","part":"noun / verb","phonetic":"/ˈsɜːrvɪs/","definition":"Work done to help or meet the needs of others; or to provide maintenance or assistance.","definitionZh":"服务；维修；服役","examples":["The restaurant is known for its friendly service.","The technician services the machines every month."],"tip":"“Service” can mean help provided to customers or regular maintenance of equipment.","course":"en","breakdown":"Work done to help or meet the needs of others; or to provide maintenance or assistance.","related":"assistance;maintenance","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Work done to help people or meet their needs, or a system that provides such help.","definitionZh":"服务；公共服务；业务","examples":["The restaurant is known for friendly service.","The bus service stops running at midnight."]},{"part":"verb","definition":"To inspect, maintain, or repair a machine or vehicle so that it works properly.","definitionZh":"维修；保养；检修","examples":["The technician services the machines every month.","The company services air conditioners across the city."]}]},{"word":"shape","part":"noun / verb","phonetic":"/ʃeɪp/","definition":"The form or outline of something; or to influence how something develops.","definitionZh":"形状；外形；塑造","examples":["The table has a round shape.","Early experiences can shape a person's character."],"tip":"“Shape” can refer to physical form or the process of influencing development.","course":"en","breakdown":"The form or outline of something; or to influence how something develops.","related":"form;outline","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The form or outline of an object, especially its external appearance.","definitionZh":"形状；外形；轮廓","examples":["The table has a round shape.","The shape of the leaf is easy to recognise."]},{"part":"verb","definition":"To influence how something develops, or to give something a particular form.","definitionZh":"塑造；形成；使成形","examples":["Early experiences shape a person's character.","The artist shaped the clay into a bowl."]}]},{"word":"side","part":"noun","phonetic":"/saɪd/","definition":"One of the surfaces, edges or parts of something; or one group in a disagreement or competition.","definitionZh":"侧面；一边；一方","examples":["Write your name on the other side of the paper.","Which side are you supporting in the match?"],"tip":"“On the other hand” introduces a contrasting point; “side” can also mean a team or position.","course":"en","breakdown":"One of the surfaces, edges or parts of something; or one group in a disagreement or competition.","related":"edge;part","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"One of the surfaces, edges or parts of something; or one group in a disagreement or competition.","definitionZh":"侧面；一边；一方","examples":["Write your name on the other side of the paper.","Which side are you supporting in the match?"]}]},{"word":"sign","part":"noun / verb","phonetic":"/saɪn/","definition":"A mark, notice or movement that gives information; or to write one's name on a document.","definitionZh":"标志；迹象；签名；签署","examples":["The sign shows where the exit is.","Please sign the form at the bottom."],"tip":"As a noun, a sign gives information; as a verb, “sign” often means to write your name.","course":"en","breakdown":"A mark, notice or movement that gives information; or to write one's name on a document.","related":"notice;symbol","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A mark, notice, or movement that gives information or shows that something exists.","definitionZh":"标志；标牌；迹象；征兆","examples":["The sign shows where the exit is.","Dark clouds can be a sign of rain."]},{"part":"verb","definition":"To write your name on a document to show agreement or approval.","definitionZh":"签名；签署；签字","examples":["Please sign the form at the bottom.","Both sides signed the agreement yesterday."]}]},{"word":"skill","part":"noun","phonetic":"/skɪl/","definition":"The ability to do something well, usually gained through practice or training.","definitionZh":"技能；技巧","examples":["Communication is an important skill at work.","She developed her drawing skills through daily practice."],"tip":"Use “skill in” or “skill at” to describe an area someone is good at.","course":"en","breakdown":"The ability to do something well, usually gained through practice or training.","related":"ability;talent","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The ability to do something well, usually gained through practice or training.","definitionZh":"技能；技巧","examples":["Communication is an important skill at work.","She developed her drawing skills through daily practice."]}]},{"word":"situation","part":"noun","phonetic":"/ˌsɪtʃuˈeɪʃən/","definition":"The set of conditions or facts that exist at a particular time and place.","definitionZh":"情况；局面；处境","examples":["We need to understand the situation before making a decision.","The emergency team handled the situation calmly."],"tip":"“Situation” describes the circumstances, not necessarily a problem.","course":"en","breakdown":"The set of conditions or facts that exist at a particular time and place.","related":"circumstances;condition","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The set of conditions or facts that exist at a particular time and place.","definitionZh":"情况；局面；处境","examples":["We need to understand the situation before making a decision.","The emergency team handled the situation calmly."]}]},{"word":"size","part":"noun / verb","phonetic":"/saɪz/","definition":"How large or small something is; or to classify or prepare something according to size.","definitionZh":"大小；尺寸；尺码","examples":["What size shirt do you wear?","The company sizes the boxes to fit each product."],"tip":"Use “size” for measurements or clothing labels; “size up” can mean to assess something.","course":"en","breakdown":"How large or small something is; or to classify or prepare something according to size.","related":"measurement;dimension","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"How large or small something is, especially its measurements or dimensions.","definitionZh":"大小；尺寸；尺码","examples":["What size shirt do you wear?","The size of the room surprised us."]},{"part":"verb","definition":"To classify, make, or adjust something according to a particular size.","definitionZh":"按尺寸分类；调整尺寸；定尺","examples":["The company sizes the boxes to fit each product.","The tailor sized the jacket before making alterations."]}]},{"word":"society","part":"noun","phonetic":"/səˈsaɪəti/","definition":"People living together in an organised community, or the system and culture they share.","definitionZh":"社会；社群；协会","examples":["Education plays an important role in society.","The society organises events for local artists."],"tip":"“Society” can mean the wider community or a formal organisation formed around a shared interest.","course":"en","breakdown":"People living together in an organised community, or the system and culture they share.","related":"community;public","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"People living together in an organised community, or the system and culture they share.","definitionZh":"社会；社群；协会","examples":["Education plays an important role in society.","The society organises events for local artists."]}]},{"word":"sound","part":"noun / verb","phonetic":"/saʊnd/","definition":"Something that can be heard; or to seem a particular way when spoken about.","definitionZh":"声音；声响；听起来","examples":["I heard a strange sound outside.","Your plan sounds reasonable to me."],"tip":"As a noun, “sound” is something heard; as a linking verb, it describes an impression.","course":"en","breakdown":"Something that can be heard; or to seem a particular way when spoken about.","related":"noise;audio","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"Something that can be heard, such as a noise, voice, or musical note.","definitionZh":"声音；声响；音响","examples":["I heard a strange sound outside.","The sound of the bell filled the hall."]},{"part":"verb","definition":"To seem a particular way when heard or described, or to produce a particular sound.","definitionZh":"听起来；发出声音；鸣响","examples":["Your plan sounds reasonable to me.","The engine sounded louder after the repair."]}]},{"word":"space","part":"noun","phonetic":"/speɪs/","definition":"An empty area or the amount of room available; or the area beyond Earth's atmosphere.","definitionZh":"空间；空地；太空","examples":["There is not enough space in the cupboard.","The astronauts travelled into space."],"tip":"“Space” is usually uncountable when it means room or the universe beyond Earth.","course":"en","breakdown":"An empty area or the amount of room available; or the area beyond Earth's atmosphere.","related":"room;area","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"An empty area or the amount of room available; or the area beyond Earth's atmosphere.","definitionZh":"空间；空地；太空","examples":["There is not enough space in the cupboard.","The astronauts travelled into space."]}]},{"word":"sport","part":"noun","phonetic":"/spɔːrt/","definition":"A physical activity or game, often involving skill, competition and rules.","definitionZh":"运动；体育项目","examples":["Basketball is a popular sport at our school.","He enjoys watching sport on television."],"tip":"In British English, “sport” is often uncountable when referring to sports in general; individual activities are countable.","course":"en","breakdown":"A physical activity or game, often involving skill, competition and rules.","related":"game;athletics","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A physical activity or game, often involving skill, competition and rules.","definitionZh":"运动；体育项目","examples":["Basketball is a popular sport at our school.","He enjoys watching sport on television."]}]},{"word":"staff","part":"noun","phonetic":"/stæf/","definition":"The people who work for an organisation or business.","definitionZh":"全体员工；职员","examples":["The hotel staff were helpful and polite.","All staff must attend the safety meeting."],"tip":"“Staff” is usually treated as a plural group in British English and as a collective noun in American English.","course":"en","breakdown":"The people who work for an organisation or business.","related":"employees;personnel","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The people who work for an organisation or business.","definitionZh":"全体员工；职员","examples":["The hotel staff were helpful and polite.","All staff must attend the safety meeting."]}]},{"word":"story","part":"noun","phonetic":"/ˈstɔːri/","definition":"A description of real or imagined events; or one level of a building in American English.","definitionZh":"故事；叙述；楼层","examples":["Grandpa told us a story before bed.","Their office is on the third story of the building."],"tip":"“Story” can mean a narrative; in American English it can also mean a floor of a building.","course":"en","breakdown":"A description of real or imagined events; or one level of a building in American English.","related":"tale;narrative","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A description of real or imagined events; or one level of a building in American English.","definitionZh":"故事；叙述；楼层","examples":["Grandpa told us a story before bed.","Their office is on the third story of the building."]}]},{"word":"success","part":"noun","phonetic":"/səkˈses/","definition":"The achievement of an aim or a result that is wanted or admired.","definitionZh":"成功；成就","examples":["Her success came from years of hard work.","The event was a great success."],"tip":"“Success” is a noun; use “successful” as the adjective and “succeed” as the verb.","course":"en","breakdown":"The achievement of an aim or a result that is wanted or admired.","related":"achievement;accomplishment","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"The achievement of an aim or a result that is wanted or admired.","definitionZh":"成功；成就","examples":["Her success came from years of hard work.","The event was a great success."]}]},{"word":"task","part":"noun","phonetic":"/tæsk/","definition":"A piece of work or an activity that someone needs to complete.","definitionZh":"任务；工作","examples":["I have one more task to finish today.","The teacher gave the class a short writing task."],"tip":"A task is a specific piece of work, while a job can refer to regular employment or a larger responsibility.","course":"en","breakdown":"A piece of work or an activity that someone needs to complete.","related":"assignment;duty","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A piece of work or an activity that someone needs to complete.","definitionZh":"任务；工作","examples":["I have one more task to finish today.","The teacher gave the class a short writing task."]}]},{"word":"team","part":"noun","phonetic":"/tiːm/","definition":"A group of people who work or play together to achieve a shared goal.","definitionZh":"团队；队伍","examples":["Our team finished the project ahead of schedule.","She plays on the school basketball team."],"tip":"Use “team” for people working together; “teamwork” describes their cooperation.","course":"en","breakdown":"A group of people who work or play together to achieve a shared goal.","related":"group;squad","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A group of people who work or play together to achieve a shared goal.","definitionZh":"团队；队伍","examples":["Our team finished the project ahead of schedule.","She plays on the school basketball team."]}]},{"word":"person","part":"noun","phonetic":"/ˈpɜːrsən/","definition":"A human being, considered as an individual.","definitionZh":"人；个人","examples":["Each person needs a ticket to enter.","She is the right person for the job."],"tip":"Use “person” for one individual; the usual plural is “people,” not “persons,” in everyday speech.","course":"en","breakdown":"A human being, considered as an individual.","related":"individual;human","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A human being, considered as an individual.","definitionZh":"人；个人","examples":["Each person needs a ticket to enter.","She is the right person for the job."]}]},{"word":"question","part":"noun / verb","phonetic":"/ˈkwestʃən/","definition":"A sentence or request asking for information; or to express doubt about something.","definitionZh":"问题；疑问；质疑","examples":["The teacher asked us a difficult question.","No one questioned the need for more time."],"tip":"A question asks for information; “question” as a verb can mean to challenge whether something is true.","course":"en","breakdown":"A sentence or request asking for information; or to express doubt about something.","related":"query;inquiry","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A sentence or request asking for information","definitionZh":"问题；疑问","examples":["The teacher asked us a difficult question."]},{"part":"verb","definition":"to express doubt about something.","definitionZh":"质疑","examples":["No one questioned the need for more time."]}]},{"word":"office","part":"noun","phonetic":"/ˈɔːfɪs/","definition":"A room or building where people work, especially doing administrative or professional tasks.","definitionZh":"办公室；办事处","examples":["My office is on the fourth floor.","Please contact the admissions office for details."],"tip":"“Office” can mean a workplace or a department that provides a particular service.","course":"en","breakdown":"A room or building where people work, especially doing administrative or professional tasks.","related":"workplace;department","categories":["Places"],"senses":[{"part":"noun","definition":"A room or building where people work, especially doing administrative or professional tasks.","definitionZh":"办公室；办事处","examples":["My office is on the fourth floor.","Please contact the admissions office for details."]}]},{"word":"school","part":"noun","phonetic":"/skuːl/","definition":"A place where children or students receive education; or a group with shared ideas or methods.","definitionZh":"学校；学派","examples":["The children walk to school every morning.","She studied at an art school."],"tip":"“At school” refers to being a student or attending classes; “the school” identifies the institution.","course":"en","breakdown":"A place where children or students receive education; or a group with shared ideas or methods.","related":"academy;institution","categories":["Education"],"senses":[{"part":"noun","definition":"A place where children or students receive education; or a group with shared ideas or methods.","definitionZh":"学校；学派","examples":["The children walk to school every morning.","She studied at an art school."]}]},{"word":"subject","part":"noun","phonetic":"/ˈsʌbdʒɪkt/","definition":"A topic studied or discussed; or a person or thing being examined or described.","definitionZh":"科目；主题；对象","examples":["Science is my favourite subject.","The article deals with a difficult subject."],"tip":"A school subject is an area of study; a subject can also be the topic of a conversation or text.","course":"en","breakdown":"A topic studied or discussed; or a person or thing being examined or described.","related":"topic;course","categories":["Education"],"senses":[{"part":"noun","definition":"A topic studied or discussed; or a person or thing being examined or described.","definitionZh":"科目；主题；对象","examples":["Science is my favourite subject.","The article deals with a difficult subject."]}]},{"word":"type","part":"noun / verb","phonetic":"/taɪp/","definition":"A kind, category or group of things with shared features; or to write using a keyboard.","definitionZh":"类型；种类；打字","examples":["What type of music do you enjoy?","Please type your name into the box."],"tip":"“Type” can mean a category or the action of entering text on a keyboard.","course":"en","breakdown":"A kind, category or group of things with shared features; or to write using a keyboard.","related":"kind;category","categories":["Everyday Terms"],"senses":[{"part":"noun","definition":"A kind, category or group of things with shared features","definitionZh":"类型；种类","examples":["What type of music do you enjoy?"]},{"part":"verb","definition":"to write using a keyboard.","definitionZh":"打字","examples":["Please type your name into the box."]}]},{"word":"tradition","part":"noun","phonetic":"/trəˈdɪʃən/","definition":"A custom, belief or way of doing something that has continued in a group or society over time.","definitionZh":"传统；惯例","examples":["It is a family tradition to cook together on holidays.","The festival celebrates a local tradition."],"tip":"A tradition is passed on over time; a habit is usually an individual's repeated behaviour.","course":"en","breakdown":"A custom, belief or way of doing something that has continued in a group or society over time.","related":"custom;practice","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A custom, belief or way of doing something that has continued in a group or society over time.","definitionZh":"传统；惯例","examples":["It is a family tradition to cook together on holidays.","The festival celebrates a local tradition."]}]},{"word":"student","part":"noun","phonetic":"/ˈstuːdənt/","definition":"A person who is studying at a school, college or university.","definitionZh":"学生","examples":["Every student must bring a notebook to class.","The university has students from many countries."],"tip":"Use “student” for someone who studies; “pupil” is more common for children at school in British English.","course":"en","breakdown":"A person who is studying at a school, college or university.","related":"learner;pupil","categories":["Education"],"senses":[{"part":"noun","definition":"A person who is studying at a school, college or university.","definitionZh":"学生","examples":["Every student must bring a notebook to class.","The university has students from many countries."]}]},{"word":"assignment","part":"noun","phonetic":"/əˈsaɪnmənt/","definition":"A piece of work given to someone, especially a student or employee, to complete.","definitionZh":"作业；任务；分配","examples":["I have to finish my history assignment tonight.","The manager gave him a new assignment."],"tip":"An assignment is usually a specific task given by someone else.","course":"en","breakdown":"A piece of work given to someone, especially a student or employee, to complete.","related":"task;homework","categories":["Education"],"senses":[{"part":"noun","definition":"A piece of work given to someone, especially a student or employee, to complete.","definitionZh":"作业；任务；分配","examples":["I have to finish my history assignment tonight.","The manager gave him a new assignment."]}]},{"word":"classroom","part":"noun","phonetic":"/ˈklæsruːm/","definition":"A room where a class of students is taught.","definitionZh":"教室","examples":["Please keep the classroom clean.","The students returned to the classroom after lunch."],"tip":"Use “in the classroom” for the place where teaching happens.","course":"en","breakdown":"A room where a class of students is taught.","related":"class;schoolroom","categories":["Education"],"senses":[{"part":"noun","definition":"A room where a class of students is taught.","definitionZh":"教室","examples":["Please keep the classroom clean.","The students returned to the classroom after lunch."]}]},{"word":"dictionary","part":"noun","phonetic":"/ˈdɪkʃəneri/","definition":"A book or digital resource that explains the meanings, pronunciation and use of words.","definitionZh":"词典；字典","examples":["I checked the spelling in an online dictionary.","This dictionary includes example sentences."],"tip":"A dictionary explains words; a glossary usually explains terms related to one subject or text.","course":"en","breakdown":"A book or digital resource that explains the meanings, pronunciation and use of words.","related":"glossary;wordbook","categories":["Education"],"senses":[{"part":"noun","definition":"A book or digital resource that explains the meanings, pronunciation and use of words.","definitionZh":"词典；字典","examples":["I checked the spelling in an online dictionary.","This dictionary includes example sentences."]}]},{"word":"essay","part":"noun","phonetic":"/ˈeseɪ/","definition":"A short piece of writing that presents information, ideas or an argument about a subject.","definitionZh":"短文；文章；议论文","examples":["She wrote an essay about climate change.","The assignment requires a 500-word essay."],"tip":"An essay usually develops one main topic or argument in connected paragraphs.","course":"en","breakdown":"A short piece of writing that presents information, ideas or an argument about a subject.","related":"composition;paper","categories":["Education"],"senses":[{"part":"noun","definition":"A short piece of writing that presents information, ideas or an argument about a subject.","definitionZh":"短文；文章；议论文","examples":["She wrote an essay about climate change.","The assignment requires a 500-word essay."]}]},{"word":"exam","part":"noun","phonetic":"/ɪɡˈzæm/","definition":"A formal test of someone's knowledge or ability in a subject.","definitionZh":"考试","examples":["He studied every evening before the exam.","The final exam covers all six chapters."],"tip":"“Exam” is a shortened form of “examination”; “take an exam” means sit for a test.","course":"en","breakdown":"A formal test of someone's knowledge or ability in a subject.","related":"test;examination","categories":["Education"],"senses":[{"part":"noun","definition":"A formal test of someone's knowledge or ability in a subject.","definitionZh":"考试","examples":["He studied every evening before the exam.","The final exam covers all six chapters."]}]},{"word":"grammar","part":"noun","phonetic":"/ˈɡræmər/","definition":"The rules and patterns that describe how words are formed and combined in a language.","definitionZh":"语法","examples":["Good grammar makes your writing easier to understand.","We are learning English grammar this term."],"tip":"“Grammar” is generally uncountable when referring to the rules of a language.","course":"en","breakdown":"The rules and patterns that describe how words are formed and combined in a language.","related":"syntax;language","categories":["Education"],"senses":[{"part":"noun","definition":"The rules and patterns that describe how words are formed and combined in a language.","definitionZh":"语法","examples":["Good grammar makes your writing easier to understand.","We are learning English grammar this term."]}]},{"word":"homework","part":"noun","phonetic":"/ˈhoʊmwɜːrk/","definition":"Schoolwork that students are expected to do outside class.","definitionZh":"家庭作业","examples":["I usually do my homework after dinner.","The teacher gave us too much homework today."],"tip":"“Homework” is uncountable; say “a piece of homework” or “some homework,” not “homeworks.”","course":"en","breakdown":"Schoolwork that students are expected to do outside class.","related":"schoolwork;assignment","categories":["Education"],"senses":[{"part":"noun","definition":"Schoolwork that students are expected to do outside class.","definitionZh":"家庭作业","examples":["I usually do my homework after dinner.","The teacher gave us too much homework today."]}]},{"word":"lesson","part":"noun","phonetic":"/ˈlesən/","definition":"A period of teaching or learning about a particular subject or skill; or something learned from experience.","definitionZh":"课程；课；教训","examples":["Our English lesson starts at nine.","The accident taught him an important lesson."],"tip":"A lesson can be a teaching session or an experience that helps someone learn.","course":"en","breakdown":"A period of teaching or learning about a particular subject or skill; or something learned from experience.","related":"class;session","categories":["Education"],"senses":[{"part":"noun","definition":"A period of teaching or learning about a particular subject or skill; or something learned from experience.","definitionZh":"课程；课；教训","examples":["Our English lesson starts at nine.","The accident taught him an important lesson."]}]},{"word":"meaning","part":"noun","phonetic":"/ˈmiːnɪŋ/","definition":"The idea or message that a word, sign, action or event expresses.","definitionZh":"意思；含义；意义","examples":["Can you explain the meaning of this word?","The poem has a deeper meaning."],"tip":"Use “meaning of” to introduce what a word, sign or action expresses.","course":"en","breakdown":"The idea or message that a word, sign, action or event expresses.","related":"definition;significance","categories":["Education"],"senses":[{"part":"noun","definition":"The idea or message that a word, sign, action or event expresses.","definitionZh":"意思；含义；意义","examples":["Can you explain the meaning of this word?","The poem has a deeper meaning."]}]},{"word":"notebook","part":"noun","phonetic":"/ˈnoʊtbʊk/","definition":"A small book of blank or lined pages used for writing notes.","definitionZh":"笔记本","examples":["She wrote the new vocabulary in her notebook.","I left my notebook in the classroom."],"tip":"A notebook is used for writing notes; a laptop is a portable computer.","course":"en","breakdown":"A small book of blank or lined pages used for writing notes.","related":"notepad;journal","categories":["Education"],"senses":[{"part":"noun","definition":"A small book of blank or lined pages used for writing notes.","definitionZh":"笔记本","examples":["She wrote the new vocabulary in her notebook.","I left my notebook in the classroom."]}]},{"word":"paragraph","part":"noun","phonetic":"/ˈpærəɡræf/","definition":"A section of writing that develops one main idea and usually begins on a new line.","definitionZh":"段落","examples":["Write one main idea in each paragraph.","The final paragraph summarises the argument."],"tip":"A paragraph is part of a text; a sentence is a complete grammatical unit within it.","course":"en","breakdown":"A section of writing that develops one main idea and usually begins on a new line.","related":"section;passage","categories":["Education"],"senses":[{"part":"noun","definition":"A section of writing that develops one main idea and usually begins on a new line.","definitionZh":"段落","examples":["Write one main idea in each paragraph.","The final paragraph summarises the argument."]}]},{"word":"pencil","part":"noun","phonetic":"/ˈpensəl/","definition":"A writing or drawing tool with a narrow piece of graphite or another marking material inside.","definitionZh":"铅笔","examples":["You can erase the marks made by a pencil.","He sketched the design with a soft pencil."],"tip":"Use “a pencil” for the tool; “pencil in” as a verb means to make a temporary arrangement.","course":"en","breakdown":"A writing or drawing tool with a narrow piece of graphite or another marking material inside.","related":"pen;writing tool","categories":["Education"],"senses":[{"part":"noun","definition":"A writing or drawing tool with a narrow piece of graphite or another marking material inside.","definitionZh":"铅笔","examples":["You can erase the marks made by a pencil.","He sketched the design with a soft pencil."]}]},{"word":"sentence","part":"noun","phonetic":"/ˈsentəns/","definition":"A group of words that expresses a complete thought; or a punishment given by a court.","definitionZh":"句子；判决；刑罚","examples":["Write a complete sentence for each word.","The judge announced the sentence in court."],"tip":"In language learning, a sentence expresses a complete thought; in law, it can mean a court's punishment.","course":"en","breakdown":"A group of words that expresses a complete thought; or a punishment given by a court.","related":"statement;phrase","categories":["Education"],"senses":[{"part":"noun","definition":"A group of words that expresses a complete thought; or a punishment given by a court.","definitionZh":"句子；判决；刑罚","examples":["Write a complete sentence for each word.","The judge announced the sentence in court."]}]},{"word":"teacher","part":"noun","phonetic":"/ˈtiːtʃər/","definition":"A person whose job is to help others learn, especially in a school.","definitionZh":"教师；老师","examples":["Our teacher explained the grammar clearly.","The new teacher joined the school in August."],"tip":"Use “teacher of” before the subject, such as “a teacher of science.”","course":"en","breakdown":"A person whose job is to help others learn, especially in a school.","related":"instructor;educator","categories":["Education"],"senses":[{"part":"noun","definition":"A person whose job is to help others learn, especially in a school.","definitionZh":"教师；老师","examples":["Our teacher explained the grammar clearly.","The new teacher joined the school in August."]}]},{"word":"textbook","part":"noun","phonetic":"/ˈtekstbʊk/","definition":"A book that presents information about a subject for students to study.","definitionZh":"教科书；课本","examples":["The textbook includes exercises at the end of each chapter.","We use a different textbook for mathematics."],"tip":"A textbook is designed for learning a subject; a workbook usually contains exercises to complete.","course":"en","breakdown":"A book that presents information about a subject for students to study.","related":"coursebook;workbook","categories":["Education"],"senses":[{"part":"noun","definition":"A book that presents information about a subject for students to study.","definitionZh":"教科书；课本","examples":["The textbook includes exercises at the end of each chapter.","We use a different textbook for mathematics."]}]},{"word":"vocabulary","part":"noun","phonetic":"/vəˈkæbjəleri/","definition":"The words known or used by a person, group or language.","definitionZh":"词汇；词汇量","examples":["Reading regularly can improve your vocabulary.","The lesson introduces vocabulary about travel."],"tip":"“Vocabulary” is usually uncountable; use “a vocabulary item” or “a set of words” for individual entries.","course":"en","breakdown":"The words known or used by a person, group or language.","related":"word stock;lexicon","categories":["Education"],"senses":[{"part":"noun","definition":"The words known or used by a person, group or language.","definitionZh":"词汇；词汇量","examples":["Reading regularly can improve your vocabulary.","The lesson introduces vocabulary about travel."]}]},{"word":"chapter","part":"noun","phonetic":"/ˈtʃæptər/","definition":"One of the main sections of a book or a period in someone's life or in an organisation's history.","definitionZh":"章节；篇章；阶段","examples":["We read the first chapter before class.","Moving abroad began a new chapter in her life."],"tip":"A chapter can be a section of a book or a figurative new stage in life.","course":"en","breakdown":"One of the main sections of a book or a period in someone's life or in an organisation's history.","related":"section;part","categories":["Education"],"senses":[{"part":"noun","definition":"One of the main sections of a book or a period in someone's life or in an organisation's history.","definitionZh":"章节；篇章；阶段","examples":["We read the first chapter before class.","Moving abroad began a new chapter in her life."]}]},{"word":"lecture","part":"noun / verb","phonetic":"/ˈlektʃər/","definition":"A formal talk given to teach people about a subject; or to give such a talk.","definitionZh":"讲座；演讲；授课","examples":["The professor gave a lecture on modern history.","She lectures at the university twice a week."],"tip":"A lecture is usually a formal teaching talk; “lecture someone” can also mean to criticise them in a long, serious way.","course":"en","breakdown":"A formal talk given to teach people about a subject; or to give such a talk.","related":"talk;presentation","categories":["Education"],"senses":[{"part":"noun","definition":"A formal talk given to teach people about a subject","definitionZh":"讲座；演讲","examples":["The professor gave a lecture on modern history."]},{"part":"verb","definition":"to give such a talk.","definitionZh":"授课","examples":["She lectures at the university twice a week."]}]},{"word":"research","part":"noun / verb","phonetic":"/ˈriːsɜːrtʃ/","definition":"Careful study to discover facts or reach new understanding; or to carry out such study.","definitionZh":"研究；调查","examples":["The students conducted research on local history.","I need to research the topic before writing."],"tip":"“Research” is usually uncountable as a noun; say “some research” or “a research project.”","course":"en","breakdown":"Careful study to discover facts or reach new understanding; or to carry out such study.","related":"study;investigation","categories":["Education"],"senses":[{"part":"noun","definition":"Careful study to discover facts or reach new understanding","definitionZh":"研究","examples":["The students conducted research on local history."]},{"part":"verb","definition":"to carry out such study.","definitionZh":"调查","examples":["I need to research the topic before writing."]}]},{"word":"study","part":"noun / verb","phonetic":"/ˈstʌdi/","definition":"The activity of learning about a subject; or to spend time learning, reading or investigating it carefully.","definitionZh":"学习；研究；书房","examples":["She studies English for an hour each day.","The study found a link between sleep and memory."],"tip":"As a verb, “study” means to learn or investigate; as a noun, it can mean learning or a research project.","course":"en","breakdown":"The activity of learning about a subject; or to spend time learning, reading or investigating it carefully.","related":"learning;research","categories":["Education"],"senses":[{"part":"noun","definition":"An activity or period spent learning about a subject; a piece of research; or a room used for reading or working.","definitionZh":"学习；研究；书房","examples":["The study found a link between sleep and memory."]},{"part":"verb","definition":"To spend time learning about a subject, reading, or investigating it carefully.","definitionZh":"学习；研究","examples":["She studies English for an hour each day."]}]},{"word":"university","part":"noun","phonetic":"/ˌjuːnɪˈvɜːrsəti/","definition":"An institution where students study for degrees and where research is carried out.","definitionZh":"大学","examples":["He hopes to attend university next year.","The university offers courses in design and engineering."],"tip":"In British English, people often say “go to university”; in American English, “go to college” is also common.","course":"en","breakdown":"An institution where students study for degrees and where research is carried out.","related":"college;institution","categories":["Education"],"senses":[{"part":"noun","definition":"An institution where students study for degrees and where research is carried out.","definitionZh":"大学","examples":["He hopes to attend university next year.","The university offers courses in design and engineering."]}]},{"word":"hotel","part":"noun","phonetic":"/hoʊˈtel/","definition":"A building where people pay to stay for a short time, usually while travelling.","definitionZh":"酒店；旅馆","examples":["We booked a hotel near the station.","The hotel offers breakfast to its guests."],"tip":"Use “stay at a hotel” when talking about accommodation.","course":"en","breakdown":"A building where people pay to stay for a short time, usually while travelling.","related":"accommodation;inn","categories":["Places"],"senses":[{"part":"noun","definition":"A building where people pay to stay for a short time, usually while travelling.","definitionZh":"酒店；旅馆","examples":["We booked a hotel near the station.","The hotel offers breakfast to its guests."]}]},{"word":"neighbourhood","part":"noun","phonetic":"/ˈneɪbərhʊd/","definition":"An area of a town or city where people live, often considered as a community.","definitionZh":"街区；社区；邻近地区","examples":["There is a small park in our neighbourhood.","The neighbourhood has become quieter in recent years."],"tip":"“Neighbourhood” is the British spelling; “neighborhood” is the American spelling.","course":"en","breakdown":"An area of a town or city where people live, often considered as a community.","related":"district;community","categories":["Places"],"senses":[{"part":"noun","definition":"An area of a town or city where people live, often considered as a community.","definitionZh":"街区；社区；邻近地区","examples":["There is a small park in our neighbourhood.","The neighbourhood has become quieter in recent years."]}]},{"word":"park","part":"noun / verb","phonetic":"/pɑːrk/","definition":"A public area of land for recreation; or to leave a vehicle in a particular place.","definitionZh":"公园；停车","examples":["The children played football in the park.","You cannot park your car here."],"tip":"As a noun, “park” is a public green space; as a verb, it often means to leave a vehicle somewhere.","course":"en","breakdown":"A public area of land for recreation; or to leave a vehicle in a particular place.","related":"garden;parking area","categories":["Places"],"senses":[{"part":"noun","definition":"A public area of land for recreation","definitionZh":"公园","examples":["The children played football in the park."]},{"part":"verb","definition":"to leave a vehicle in a particular place.","definitionZh":"停车","examples":["You cannot park your car here."]}]},{"word":"pharmacy","part":"noun","phonetic":"/ˈfɑːrməsi/","definition":"A shop or department where medicines are prepared or sold.","definitionZh":"药房；药店","examples":["I bought some medicine at the pharmacy.","The pharmacy closes at six this evening."],"tip":"In some countries, “chemist” is also used for a pharmacy or the person who prepares medicines.","course":"en","breakdown":"A shop or department where medicines are prepared or sold.","related":"drugstore;chemist","categories":["Places"],"senses":[{"part":"noun","definition":"A shop or department where medicines are prepared or sold.","definitionZh":"药房；药店","examples":["I bought some medicine at the pharmacy.","The pharmacy closes at six this evening."]}]},{"word":"desert","part":"noun / verb","phonetic":"/ˈdezərt/","definition":"A large, dry area of land that receives very little rain; or to leave someone or something when support is needed.","definitionZh":"沙漠；抛弃；遗弃","examples":["Few plants can survive in the desert.","He felt that his friends had deserted him."],"tip":"The noun is stressed on the first syllable (/ˈdezərt/); the verb is stressed on the second (/dɪˈzɜːrt/).","course":"en","breakdown":"A large, dry area of land that receives very little rain; or to leave someone or something when support is needed.","related":"dryland;wilderness","categories":["Places"],"senses":[{"part":"noun","definition":"A large, dry area of land that receives very little rain","definitionZh":"沙漠；抛弃","examples":["Few plants can survive in the desert."]},{"part":"verb","definition":"to leave someone or something when support is needed.","definitionZh":"遗弃","examples":["He felt that his friends had deserted him."]}]},{"word":"destination","part":"noun","phonetic":"/ˌdestɪˈneɪʃən/","definition":"The place that someone or something is going to.","definitionZh":"目的地；终点","examples":["Our final destination is the coast.","Check the destination before boarding the train."],"tip":"Use “destination” for the place at the end of a journey.","course":"en","breakdown":"The place that someone or something is going to.","related":"endpoint;arrival point","categories":["Places"],"senses":[{"part":"noun","definition":"The place that someone or something is going to.","definitionZh":"目的地；终点","examples":["Our final destination is the coast.","Check the destination before boarding the train."]}]},{"word":"downtown","part":"noun / adjective / adverb","phonetic":"/ˌdaʊnˈtaʊn/","definition":"The central business or shopping area of a town or city.","definitionZh":"市中心；闹市区","examples":["The hotel is located downtown.","We took a bus to the downtown area."],"tip":"“Downtown” is especially common in North American English; British English often uses “city centre” or “town centre.”","course":"en","breakdown":"The central business or shopping area of a town or city.","related":"city centre;centre","categories":["Places"],"senses":[{"part":"noun","definition":"The central business or shopping area of a town or city.","definitionZh":"市中心；闹市区","examples":["We walked around downtown after lunch."]},{"part":"adjective","definition":"Located in or relating to the central area of a town or city.","definitionZh":"市中心的；闹市区的","examples":["They rented a downtown apartment."]},{"part":"adverb","definition":"In or towards the central area of a town or city.","definitionZh":"在市中心；往市中心","examples":["The hotel is located downtown."]}]},{"word":"factory","part":"noun","phonetic":"/ˈfæktəri/","definition":"A building or group of buildings where goods are made, usually by machines.","definitionZh":"工厂","examples":["The factory makes parts for cars.","Hundreds of people work at the factory."],"tip":"Use “in a factory” for the workplace and “at the factory” for the site.","course":"en","breakdown":"A building or group of buildings where goods are made, usually by machines.","related":"plant;workshop","categories":["Places"],"senses":[{"part":"noun","definition":"A building or group of buildings where goods are made, usually by machines.","definitionZh":"工厂","examples":["The factory makes parts for cars.","Hundreds of people work at the factory."]}]},{"word":"farm","part":"noun / verb","phonetic":"/fɑːrm/","definition":"An area of land used for growing crops or keeping animals; or to grow crops or raise animals for a living.","definitionZh":"农场；务农","examples":["My grandparents live on a small farm.","They farm rice in the valley."],"tip":"A farm is the place; “to farm” describes the work of producing food or raising animals.","course":"en","breakdown":"An area of land used for growing crops or keeping animals; or to grow crops or raise animals for a living.","related":"ranch;agricultural land","categories":["Places"],"senses":[{"part":"noun","definition":"An area of land used for growing crops or keeping animals","definitionZh":"农场","examples":["My grandparents live on a small farm."]},{"part":"verb","definition":"to grow crops or raise animals for a living.","definitionZh":"务农","examples":["They farm rice in the valley."]}]},{"word":"forest","part":"noun","phonetic":"/ˈfɔːrɪst/","definition":"A large area covered mainly with trees and other plants.","definitionZh":"森林","examples":["We walked through the forest in the morning.","Many animals depend on the forest for shelter."],"tip":"A forest is generally larger and more densely wooded than a small group of trees.","course":"en","breakdown":"A large area covered mainly with trees and other plants.","related":"woodland;woods","categories":["Places"],"senses":[{"part":"noun","definition":"A large area covered mainly with trees and other plants.","definitionZh":"森林","examples":["We walked through the forest in the morning.","Many animals depend on the forest for shelter."]}]},{"word":"garage","part":"noun","phonetic":"/ɡəˈrɑːʒ/","definition":"A building or part of a building where a car is kept or repaired.","definitionZh":"车库；汽车修理厂","examples":["He parked his bicycle in the garage.","The car is being repaired at a local garage."],"tip":"A home garage stores vehicles; a commercial garage may repair them.","course":"en","breakdown":"A building or part of a building where a car is kept or repaired.","related":"carport;workshop","categories":["Places"],"senses":[{"part":"noun","definition":"A building or part of a building where a car is kept or repaired.","definitionZh":"车库；汽车修理厂","examples":["He parked his bicycle in the garage.","The car is being repaired at a local garage."]}]},{"word":"gym","part":"noun","phonetic":"/dʒɪm/","definition":"A place with equipment for exercise, fitness training or indoor sports.","definitionZh":"健身房；体育馆","examples":["I go to the gym three times a week.","The school gym is used for basketball practice."],"tip":"“Gym” is short for “gymnasium”; it can refer to a fitness centre or a school sports hall.","course":"en","breakdown":"A place with equipment for exercise, fitness training or indoor sports.","related":"fitness centre;gymnasium","categories":["Places"],"senses":[{"part":"noun","definition":"A place with equipment for exercise, fitness training or indoor sports.","definitionZh":"健身房；体育馆","examples":["I go to the gym three times a week.","The school gym is used for basketball practice."]}]},{"word":"harbour","part":"noun / verb","phonetic":"/ˈhɑːrbər/","definition":"A sheltered area of water where ships and boats can stay safely; or to keep a thought or feeling.","definitionZh":"港口；海港；心怀","examples":["The fishing boats returned to the harbour.","She still harbours doubts about the plan."],"tip":"“Harbour” is the British spelling; “harbor” is the American spelling.","course":"en","breakdown":"A sheltered area of water where ships and boats can stay safely; or to keep a thought or feeling.","related":"port;dock","categories":["Places"],"senses":[{"part":"noun","definition":"A sheltered area of water where ships and boats can stay safely","definitionZh":"港口；海港","examples":["The fishing boats returned to the harbour."]},{"part":"verb","definition":"to keep a thought or feeling.","definitionZh":"心怀","examples":["She still harbours doubts about the plan."]}]},{"word":"island","part":"noun","phonetic":"/ˈaɪlənd/","definition":"An area of land completely surrounded by water.","definitionZh":"岛；岛屿","examples":["They spent their holiday on a tropical island.","The island can only be reached by boat."],"tip":"An island is surrounded by water on all sides; a peninsula is connected to a larger land area.","course":"en","breakdown":"An area of land completely surrounded by water.","related":"isle;atoll","categories":["Places"],"senses":[{"part":"noun","definition":"An area of land completely surrounded by water.","definitionZh":"岛；岛屿","examples":["They spent their holiday on a tropical island.","The island can only be reached by boat."]}]},{"word":"kitchen","part":"noun","phonetic":"/ˈkɪtʃən/","definition":"A room or area where food is prepared and cooked.","definitionZh":"厨房","examples":["The kitchen smells of fresh bread.","We keep the plates in the kitchen cupboard."],"tip":"Use “in the kitchen” for the room where meals are prepared.","course":"en","breakdown":"A room or area where food is prepared and cooked.","related":"cookroom;galley","categories":["Places"],"senses":[{"part":"noun","definition":"A room or area where food is prepared and cooked.","definitionZh":"厨房","examples":["The kitchen smells of fresh bread.","We keep the plates in the kitchen cupboard."]}]},{"word":"lake","part":"noun","phonetic":"/leɪk/","definition":"A large area of water surrounded by land.","definitionZh":"湖；湖泊","examples":["We went fishing at the lake.","The lake freezes during some winters."],"tip":"A lake is surrounded by land; a sea is a much larger body of salt water.","course":"en","breakdown":"A large area of water surrounded by land.","related":"pond;reservoir","categories":["Places"],"senses":[{"part":"noun","definition":"A large area of water surrounded by land.","definitionZh":"湖；湖泊","examples":["We went fishing at the lake.","The lake freezes during some winters."]}]},{"word":"path","part":"noun","phonetic":"/pæθ/","definition":"A narrow way or track for people to walk along; or a route to reach a goal.","definitionZh":"小路；路径；途径","examples":["Follow the path through the garden.","Education can provide a path to new opportunities."],"tip":"A path can be a physical walkway or a figurative route toward a goal.","course":"en","breakdown":"A narrow way or track for people to walk along; or a route to reach a goal.","related":"trail;route","categories":["Places"],"senses":[{"part":"noun","definition":"A narrow way or track for people to walk along; or a route to reach a goal.","definitionZh":"小路；路径；途径","examples":["Follow the path through the garden.","Education can provide a path to new opportunities."]}]},{"word":"playground","part":"noun","phonetic":"/ˈpleɪɡraʊnd/","definition":"An outdoor area designed for children to play, often with swings and climbing equipment.","definitionZh":"游乐场；操场","examples":["The children ran to the playground after school.","The new playground has a safe surface."],"tip":"A playground is usually for children's play; a playing field is a larger open area for sports.","course":"en","breakdown":"An outdoor area designed for children to play, often with swings and climbing equipment.","related":"play area;park","categories":["Places"],"senses":[{"part":"noun","definition":"An outdoor area designed for children to play, often with swings and climbing equipment.","definitionZh":"游乐场；操场","examples":["The children ran to the playground after school.","The new playground has a safe surface."]}]},{"word":"police station","part":"noun","phonetic":"/pəˈliːs ˌsteɪʃən/","definition":"A local office or building where police officers work and members of the public can report incidents.","definitionZh":"警察局；派出所","examples":["She went to the police station to report her lost bag.","The police station is next to the town hall."],"tip":"Use “at the police station” for the location and “report something to the police” for the action.","course":"en","breakdown":"A local office or building where police officers work and members of the public can report incidents.","related":"station;police office","categories":["Places"],"senses":[{"part":"noun","definition":"A local office or building where police officers work and members of the public can report incidents.","definitionZh":"警察局；派出所","examples":["She went to the police station to report her lost bag.","The police station is next to the town hall."]}]},{"word":"post office","part":"noun","phonetic":"/ˈpoʊst ˌɔːfɪs/","definition":"A place where people can send letters and parcels and access postal services.","definitionZh":"邮局","examples":["I went to the post office to send a parcel.","The post office closes at five."],"tip":"A post office handles postal services; a mailbox is a container where letters are collected.","course":"en","breakdown":"A place where people can send letters and parcels and access postal services.","related":"postal office;mail centre","categories":["Places"],"senses":[{"part":"noun","definition":"A place where people can send letters and parcels and access postal services.","definitionZh":"邮局","examples":["I went to the post office to send a parcel.","The post office closes at five."]}]},{"word":"prison","part":"noun","phonetic":"/ˈprɪzən/","definition":"A place where people are kept as punishment after being convicted of a crime or while awaiting trial.","definitionZh":"监狱","examples":["The prisoner was transferred to another prison.","The prison has a library and education programmes."],"tip":"“Prison” is the institution; “prisoner” is a person held there.","course":"en","breakdown":"A place where people are kept as punishment after being convicted of a crime or while awaiting trial.","related":"jail;correctional facility","categories":["Places"],"senses":[{"part":"noun","definition":"A place where people are kept as punishment after being convicted of a crime or while awaiting trial.","definitionZh":"监狱","examples":["The prisoner was transferred to another prison.","The prison has a library and education programmes."]}]},{"word":"rooftop","part":"noun","phonetic":"/ˈruːftɑːp/","definition":"The outside upper surface or top of a building.","definitionZh":"屋顶；楼顶","examples":["They watched the sunset from the rooftop.","The hotel has a rooftop garden."],"tip":"A rooftop is the top surface of a building; an attic is a space inside the roof.","course":"en","breakdown":"The outside upper surface or top of a building.","related":"roof;terrace","categories":["Places"],"senses":[{"part":"noun","definition":"The outside upper surface or top of a building.","definitionZh":"屋顶；楼顶","examples":["They watched the sunset from the rooftop.","The hotel has a rooftop garden."]}]},{"word":"sidewalk","part":"noun","phonetic":"/ˈsaɪdwɔːk/","definition":"A paved path beside a road for people to walk on.","definitionZh":"人行道","examples":["Please keep bicycles off the sidewalk.","A tree had fallen across the sidewalk."],"tip":"“Sidewalk” is American English; British English usually uses “pavement.”","course":"en","breakdown":"A paved path beside a road for people to walk on.","related":"pavement;footpath","categories":["Places"],"senses":[{"part":"noun","definition":"A paved path beside a road for people to walk on.","definitionZh":"人行道","examples":["Please keep bicycles off the sidewalk.","A tree had fallen across the sidewalk."]}]},{"word":"supermarket","part":"noun","phonetic":"/ˈsuːpərˌmɑːrkɪt/","definition":"A large shop that sells food and many household products for customers to choose themselves.","definitionZh":"超市","examples":["We buy fresh vegetables at the supermarket.","The supermarket is open until ten tonight."],"tip":"A supermarket is generally larger than a small grocery shop.","course":"en","breakdown":"A large shop that sells food and many household products for customers to choose themselves.","related":"grocery store;market","categories":["Places"],"senses":[{"part":"noun","definition":"A large shop that sells food and many household products for customers to choose themselves.","definitionZh":"超市","examples":["We buy fresh vegetables at the supermarket.","The supermarket is open until ten tonight."]}]},{"word":"temple","part":"noun","phonetic":"/ˈtempəl/","definition":"A building used for religious worship, especially in some Asian religions.","definitionZh":"寺庙；庙宇","examples":["Visitors removed their shoes before entering the temple.","The ancient temple attracts many tourists."],"tip":"A temple is a place of worship; the exact design and use vary across religions and cultures.","course":"en","breakdown":"A building used for religious worship, especially in some Asian religions.","related":"shrine;place of worship","categories":["Places"],"senses":[{"part":"noun","definition":"A building used for religious worship, especially in some Asian religions.","definitionZh":"寺庙；庙宇","examples":["Visitors removed their shoes before entering the temple.","The ancient temple attracts many tourists."]}]},{"word":"village","part":"noun","phonetic":"/ˈvɪlɪdʒ/","definition":"A small community or settlement, usually smaller than a town.","definitionZh":"村庄；乡村","examples":["My aunt lives in a quiet village.","The village holds a market every Sunday."],"tip":"A village is usually smaller than a town, though the distinction varies by country.","course":"en","breakdown":"A small community or settlement, usually smaller than a town.","related":"settlement;hamlet","categories":["Places"],"senses":[{"part":"noun","definition":"A small community or settlement, usually smaller than a town.","definitionZh":"村庄；乡村","examples":["My aunt lives in a quiet village.","The village holds a market every Sunday."]}]},{"word":"warehouse","part":"noun","phonetic":"/ˈwerhaʊs/","definition":"A large building used for storing goods before they are sold or transported.","definitionZh":"仓库","examples":["The company stores its products in a warehouse.","Trucks deliver goods to the warehouse every morning."],"tip":"A warehouse is for storage; a factory is where products are made.","course":"en","breakdown":"A large building used for storing goods before they are sold or transported.","related":"storage facility;depot","categories":["Places"],"senses":[{"part":"noun","definition":"A large building used for storing goods before they are sold or transported.","definitionZh":"仓库","examples":["The company stores its products in a warehouse.","Trucks deliver goods to the warehouse every morning."]}]},{"word":"waterfall","part":"noun","phonetic":"/ˈwɔːtərˌfɔːl/","definition":"A place where water flows over a steep edge or down a high drop in a river.","definitionZh":"瀑布","examples":["We could hear the waterfall before we saw it.","The waterfall is especially powerful after heavy rain."],"tip":"A waterfall is a natural drop in flowing water; a cascade is a series of smaller drops.","course":"en","breakdown":"A place where water flows over a steep edge or down a high drop in a river.","related":"cascade;falls","categories":["Places"],"senses":[{"part":"noun","definition":"A place where water flows over a steep edge or down a high drop in a river.","definitionZh":"瀑布","examples":["We could hear the waterfall before we saw it.","The waterfall is especially powerful after heavy rain."]}]},{"word":"workplace","part":"noun","phonetic":"/ˈwɜːrkˌpleɪs/","definition":"A place where a person works, such as an office, shop, factory or other location.","definitionZh":"工作场所；职场","examples":["Everyone should feel safe in the workplace.","The company moved to a larger workplace."],"tip":"“Workplace” is a general term and does not specify the kind of building or job.","course":"en","breakdown":"A place where a person works, such as an office, shop, factory or other location.","related":"work environment;office","categories":["Places"],"senses":[{"part":"noun","definition":"A place where a person works, such as an office, shop, factory or other location.","definitionZh":"工作场所；职场","examples":["Everyone should feel safe in the workplace.","The company moved to a larger workplace."]}]},{"word":"zoo","part":"noun","phonetic":"/zuː/","definition":"A place where wild animals are kept so that people can see and learn about them.","definitionZh":"动物园","examples":["The children saw elephants at the zoo.","The zoo runs a programme to protect endangered species."],"tip":"A modern zoo may also support animal care, education and conservation.","course":"en","breakdown":"A place where wild animals are kept so that people can see and learn about them.","related":"zoological park;wildlife park","categories":["Places"],"senses":[{"part":"noun","definition":"A place where wild animals are kept so that people can see and learn about them.","definitionZh":"动物园","examples":["The children saw elephants at the zoo.","The zoo runs a programme to protect endangered species."]}]},{"word":"child","part":"noun","phonetic":"/tʃaɪld/","definition":"A young person who has not reached adulthood; or a son or daughter of any age when viewed in relation to a parent.","definitionZh":"孩子；儿童；子女","examples":["The child was excited about the school trip.","They have one child and two grandchildren."],"tip":"The plural of “child” is “children,” not “childs.”","course":"en","breakdown":"A young person who has not reached adulthood; or a son or daughter of any age when viewed in relation to a parent.","related":"kid;youngster","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A young person who has not reached adulthood; or a son or daughter of any age when viewed in relation to a parent.","definitionZh":"孩子；儿童；子女","examples":["The child was excited about the school trip.","They have one child and two grandchildren."]}]},{"word":"father","part":"noun / verb","phonetic":"/ˈfɑːðər/","definition":"A male parent; or to become the father of a child or create something.","definitionZh":"父亲；爸爸；创立","examples":["Her father taught her how to ride a bicycle.","The project was fathered by a small research team."],"tip":"“Father” is more formal than “dad”; as a verb, it can mean to create or originate something.","course":"en","breakdown":"A male parent; or to become the father of a child or create something.","related":"dad;parent","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A male parent","definitionZh":"父亲；爸爸","examples":["Her father taught her how to ride a bicycle."]},{"part":"verb","definition":"to become the father of a child or create something.","definitionZh":"创立","examples":["The project was fathered by a small research team."]}]},{"word":"friend","part":"noun","phonetic":"/frend/","definition":"A person whom someone knows well and likes, and with whom they have a relationship of trust and affection.","definitionZh":"朋友","examples":["My friend helped me prepare for the interview.","We have been friends since primary school."],"tip":"Use “a friend of mine” to mean one of your friends.","course":"en","breakdown":"A person whom someone knows well and likes, and with whom they have a relationship of trust and affection.","related":"companion;mate","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person whom someone knows well and likes, and with whom they have a relationship of trust and affection.","definitionZh":"朋友","examples":["My friend helped me prepare for the interview.","We have been friends since primary school."]}]},{"word":"girl","part":"noun","phonetic":"/ɡɜːrl/","definition":"A female child or young person.","definitionZh":"女孩；女孩子","examples":["The girl is reading a book by the window.","When she was a girl, she lived near the sea."],"tip":"Use “girl” for a child or young person; “woman” is generally used for an adult.","course":"en","breakdown":"A female child or young person.","related":"young woman;child","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A female child or young person.","definitionZh":"女孩；女孩子","examples":["The girl is reading a book by the window.","When she was a girl, she lived near the sea."]}]},{"word":"husband","part":"noun","phonetic":"/ˈhʌzbənd/","definition":"A man who is married to someone.","definitionZh":"丈夫","examples":["Her husband works as a chef.","They celebrated their tenth wedding anniversary with her husband."],"tip":"“Husband” describes a marital relationship; “partner” is a broader term.","course":"en","breakdown":"A man who is married to someone.","related":"spouse;partner","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A man who is married to someone.","definitionZh":"丈夫","examples":["Her husband works as a chef.","They celebrated their tenth wedding anniversary with her husband."]}]},{"word":"infant","part":"noun / adjective","phonetic":"/ˈɪnfənt/","definition":"A very young child, especially a baby during the first year or early stage of life.","definitionZh":"婴儿；幼儿","examples":["The clinic provides care for infants.","The infant was sleeping peacefully."],"tip":"“Infant” is more formal than “baby” and is common in medical or official contexts.","course":"en","breakdown":"A very young child, especially a baby during the first year or early stage of life.","related":"baby;newborn","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A very young child, especially a baby during the first year or early stage of life.","definitionZh":"婴儿；幼儿","examples":["The clinic provides care for infants."]},{"part":"adjective","definition":"Relating to very young children or an early stage of development.","definitionZh":"婴儿的；幼儿的；初期的","examples":["The infant-care unit is open around the clock."]}]},{"word":"leader","part":"noun","phonetic":"/ˈliːdər/","definition":"A person who guides or directs a group, organisation or activity.","definitionZh":"领导者；领袖；负责人","examples":["The team leader explained the new plan.","A good leader listens to different opinions."],"tip":"A leader guides a group; a manager is usually responsible for organising work or resources.","course":"en","breakdown":"A person who guides or directs a group, organisation or activity.","related":"chief;guide","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who guides or directs a group, organisation or activity.","definitionZh":"领导者；领袖；负责人","examples":["The team leader explained the new plan.","A good leader listens to different opinions."]}]},{"word":"manager","part":"noun","phonetic":"/ˈmænɪdʒər/","definition":"A person responsible for organising and controlling the work of a business, team or department.","definitionZh":"经理；管理者","examples":["The store manager welcomed the new employees.","She spoke to her manager about the schedule."],"tip":"Use “manager of” before the organisation or team being managed.","course":"en","breakdown":"A person responsible for organising and controlling the work of a business, team or department.","related":"supervisor;director","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person responsible for organising and controlling the work of a business, team or department.","definitionZh":"经理；管理者","examples":["The store manager welcomed the new employees.","She spoke to her manager about the schedule."]}]},{"word":"member","part":"noun","phonetic":"/ˈmembər/","definition":"A person who belongs to a group, organisation, team or community.","definitionZh":"成员；会员","examples":["Each member of the club received a card.","She is a member of the school debate team."],"tip":"Use “member of” to identify the group someone belongs to.","course":"en","breakdown":"A person who belongs to a group, organisation, team or community.","related":"participant;associate","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who belongs to a group, organisation, team or community.","definitionZh":"成员；会员","examples":["Each member of the club received a card.","She is a member of the school debate team."]}]},{"word":"mentor","part":"noun / verb","phonetic":"/ˈmentɔːr/","definition":"An experienced person who advises and supports someone with less experience; or to provide that guidance.","definitionZh":"导师；指导者；指导","examples":["My mentor helped me prepare my portfolio.","She mentors new employees at the studio."],"tip":"A mentor offers guidance over time; a teacher may focus more directly on instruction.","course":"en","breakdown":"An experienced person who advises and supports someone with less experience; or to provide that guidance.","related":"adviser;guide","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"An experienced person who advises and supports someone with less experience","definitionZh":"导师；指导者","examples":["My mentor helped me prepare my portfolio."]},{"part":"verb","definition":"to provide that guidance.","definitionZh":"指导","examples":["She mentors new employees at the studio."]}]},{"word":"mother","part":"noun / verb","phonetic":"/ˈmʌðər/","definition":"A female parent; or to care for someone in a protective way.","definitionZh":"母亲；妈妈；照料","examples":["His mother works at a local school.","She mothered the younger children when their parents were away."],"tip":"“Mother” is more formal than “mum” or “mom”; as a verb it can mean to care for someone protectively.","course":"en","breakdown":"A female parent; or to care for someone in a protective way.","related":"mum;mom;parent","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A female parent","definitionZh":"母亲；妈妈","examples":["His mother works at a local school."]},{"part":"verb","definition":"to care for someone in a protective way.","definitionZh":"照料","examples":["She mothered the younger children when their parents were away."]}]},{"word":"nephew","part":"noun","phonetic":"/ˈnefjuː/","definition":"The son of someone's brother or sister, or of their spouse's brother or sister.","definitionZh":"侄子；外甥","examples":["My nephew is starting secondary school this year.","She bought a birthday present for her nephew."],"tip":"A nephew is a male child of your sibling; a niece is a female child of your sibling.","course":"en","breakdown":"The son of someone's brother or sister, or of their spouse's brother or sister.","related":"niece;relative","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"The son of someone's brother or sister, or of their spouse's brother or sister.","definitionZh":"侄子；外甥","examples":["My nephew is starting secondary school this year.","She bought a birthday present for her nephew."]}]},{"word":"niece","part":"noun","phonetic":"/niːs/","definition":"The daughter of someone's brother or sister, or of their spouse's brother or sister.","definitionZh":"侄女；外甥女","examples":["My niece enjoys drawing animals.","He is taking his niece to the museum."],"tip":"A niece is a female child of your sibling; a nephew is a male child of your sibling.","course":"en","breakdown":"The daughter of someone's brother or sister, or of their spouse's brother or sister.","related":"nephew;relative","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"The daughter of someone's brother or sister, or of their spouse's brother or sister.","definitionZh":"侄女；外甥女","examples":["My niece enjoys drawing animals.","He is taking his niece to the museum."]}]},{"word":"partner","part":"noun / verb","phonetic":"/ˈpɑːrtnər/","definition":"A person someone works or does an activity with; or someone in a marriage or romantic relationship.","definitionZh":"伙伴；搭档；伴侣；合伙人","examples":["Please discuss the question with your partner.","Her business partner manages the accounts."],"tip":"“Partner” can refer to a workmate, business associate or relationship partner; context makes the meaning clear.","course":"en","breakdown":"A person someone works or does an activity with; or someone in a marriage or romantic relationship.","related":"colleague;companion","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person someone works or does an activity with, or someone in a marriage, romantic relationship, or business partnership.","definitionZh":"伙伴；搭档；伴侣；合伙人","examples":["Please discuss the question with your partner.","Her business partner manages the accounts."]},{"part":"verb","definition":"To work or take part in an activity with another person or organisation as a partner.","definitionZh":"合作；结成伙伴","examples":["The two studios partnered on the project."]}]},{"word":"passenger","part":"noun","phonetic":"/ˈpæsɪndʒər/","definition":"A person travelling in a vehicle, ship or aircraft who is not operating it.","definitionZh":"乘客","examples":["All passengers must wear their seat belts.","The bus was full of passengers."],"tip":"A passenger travels in a vehicle but is not the driver, pilot or crew member operating it.","course":"en","breakdown":"A person travelling in a vehicle, ship or aircraft who is not operating it.","related":"traveller;commuter","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person travelling in a vehicle, ship or aircraft who is not operating it.","definitionZh":"乘客","examples":["All passengers must wear their seat belts.","The bus was full of passengers."]}]},{"word":"parent","part":"noun / verb","phonetic":"/ˈperənt/","definition":"A person's mother or father; or to raise and care for a child.","definitionZh":"父母；家长；养育","examples":["Every parent wants their child to feel supported.","They parent their children with patience and care."],"tip":"“Parent” can refer to one mother or father; “parents” usually refers to both.","course":"en","breakdown":"A person's mother or father; or to raise and care for a child.","related":"mother;father;guardian","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person's mother or father","definitionZh":"父母；家长","examples":["Every parent wants their child to feel supported."]},{"part":"verb","definition":"to raise and care for a child.","definitionZh":"养育","examples":["They parent their children with patience and care."]}]},{"word":"pedestrian","part":"noun / adjective","phonetic":"/pəˈdestriən/","definition":"A person travelling on foot rather than in a vehicle; or relating to walking.","definitionZh":"行人；步行者","examples":["Pedestrians should use the crossing.","The street has a pedestrian-only area."],"tip":"A pedestrian is someone walking in a public place; a pedestrian crossing is a marked place to cross a road.","course":"en","breakdown":"A person travelling on foot rather than in a vehicle; or relating to walking.","related":"walker;passer-by","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person travelling on foot rather than in a vehicle","definitionZh":"行人","examples":["Pedestrians should use the crossing."]},{"part":"adjective","definition":"relating to walking.","definitionZh":"步行者","examples":["The street has a pedestrian-only area."]}]},{"word":"player","part":"noun","phonetic":"/ˈpleɪər/","definition":"A person who takes part in a sport, game or musical performance; or an important participant in an activity.","definitionZh":"选手；球员；演奏者；参与者","examples":["The player scored two goals in the final.","She is a talented piano player."],"tip":"A player can take part in a sport, game or music; it can also describe an influential participant in a field.","course":"en","breakdown":"A person who takes part in a sport, game or musical performance; or an important participant in an activity.","related":"athlete;performer","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who takes part in a sport, game or musical performance; or an important participant in an activity.","definitionZh":"选手；球员；演奏者；参与者","examples":["The player scored two goals in the final.","She is a talented piano player."]}]},{"word":"professor","part":"noun","phonetic":"/prəˈfesər/","definition":"A senior academic who teaches and conducts research at a university or similar institution.","definitionZh":"教授","examples":["The professor gave a talk about modern design.","She became a professor of biology last year."],"tip":"Academic titles differ by country; in some systems, “professor” is a senior rank rather than a general term for any university teacher.","course":"en","breakdown":"A senior academic who teaches and conducts research at a university or similar institution.","related":"academic;lecturer","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A senior academic who teaches and conducts research at a university or similar institution.","definitionZh":"教授","examples":["The professor gave a talk about modern design.","She became a professor of biology last year."]}]},{"word":"relative","part":"noun / adjective","phonetic":"/ˈrelətɪv/","definition":"A member of someone's family; or considered in relation to something else rather than absolutely.","definitionZh":"亲戚；亲属；相对的","examples":["We visited several relatives during the holiday.","The cost is low relative to the quality."],"tip":"As a noun, “relative” means a family member; as an adjective, it means considered in comparison with something else.","course":"en","breakdown":"A member of someone's family; or considered in relation to something else rather than absolutely.","related":"family member;relation","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A member of someone's family","definitionZh":"亲戚；亲属","examples":["We visited several relatives during the holiday."]},{"part":"adjective","definition":"considered in relation to something else rather than absolutely.","definitionZh":"相对的","examples":["The cost is low relative to the quality."]}]},{"word":"roommate","part":"noun","phonetic":"/ˈruːmˌmeɪt/","definition":"A person who shares a room, apartment or house with another person.","definitionZh":"室友；合租伙伴","examples":["My roommate and I share the cooking.","She found a new roommate near campus."],"tip":"“Roommate” is common in American English; “flatmate” is common in British English for someone sharing a flat.","course":"en","breakdown":"A person who shares a room, apartment or house with another person.","related":"flatmate;housemate","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who shares a room, apartment or house with another person.","definitionZh":"室友；合租伙伴","examples":["My roommate and I share the cooking.","She found a new roommate near campus."]}]},{"word":"scientist","part":"noun","phonetic":"/ˈsaɪəntɪst/","definition":"A person who studies or works in science, often carrying out research or experiments.","definitionZh":"科学家","examples":["The scientist studied how plants respond to light.","A team of scientists published the results."],"tip":"A scientist may specialise in fields such as biology, chemistry or physics.","course":"en","breakdown":"A person who studies or works in science, often carrying out research or experiments.","related":"researcher;scholar","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who studies or works in science, often carrying out research or experiments.","definitionZh":"科学家","examples":["The scientist studied how plants respond to light.","A team of scientists published the results."]}]},{"word":"sibling","part":"noun","phonetic":"/ˈsɪblɪŋ/","definition":"A person's brother or sister.","definitionZh":"兄弟姐妹","examples":["She has two siblings, an older brother and a younger sister.","The siblings grew up in the same town."],"tip":"“Sibling” is a gender-neutral word for a brother or sister.","course":"en","breakdown":"A person's brother or sister.","related":"brother;sister","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person's brother or sister.","definitionZh":"兄弟姐妹","examples":["She has two siblings, an older brother and a younger sister.","The siblings grew up in the same town."]}]},{"word":"stranger","part":"noun","phonetic":"/ˈstreɪndʒər/","definition":"A person whom someone does not know.","definitionZh":"陌生人","examples":["Do not share personal information with a stranger.","A stranger offered to help carry the bags."],"tip":"A stranger is someone unfamiliar to you; “foreigner” specifically refers to someone from another country.","course":"en","breakdown":"A person whom someone does not know.","related":"unknown person;outsider","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person whom someone does not know.","definitionZh":"陌生人","examples":["Do not share personal information with a stranger.","A stranger offered to help carry the bags."]}]},{"word":"teenager","part":"noun","phonetic":"/ˈtiːnˌeɪdʒər/","definition":"A person aged from thirteen to nineteen.","definitionZh":"青少年；十几岁的年轻人","examples":["The programme is designed for teenagers.","Many teenagers enjoy spending time with friends."],"tip":"The ages thirteen to nineteen end in “-teen,” which is why they are called the teenage years.","course":"en","breakdown":"A person aged from thirteen to nineteen.","related":"adolescent;young person","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person aged from thirteen to nineteen.","definitionZh":"青少年；十几岁的年轻人","examples":["The programme is designed for teenagers.","Many teenagers enjoy spending time with friends."]}]},{"word":"tourist","part":"noun","phonetic":"/ˈtʊrɪst/","definition":"A person who travels to a place for pleasure or interest, usually for a limited time.","definitionZh":"游客；观光客","examples":["The city attracts tourists from around the world.","A tourist asked us for directions to the museum."],"tip":"A tourist visits a place; a traveller is a broader term for someone who travels.","course":"en","breakdown":"A person who travels to a place for pleasure or interest, usually for a limited time.","related":"visitor;sightseer","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who travels to a place for pleasure or interest, usually for a limited time.","definitionZh":"游客；观光客","examples":["The city attracts tourists from around the world.","A tourist asked us for directions to the museum."]}]},{"word":"visitor","part":"noun","phonetic":"/ˈvɪzɪtər/","definition":"A person who goes to a place for a short time, often as a guest.","definitionZh":"访客；来访者","examples":["All visitors must sign in at reception.","We had visitors from another city this weekend."],"tip":"A visitor may come to a home, workplace, institution or tourist attraction.","course":"en","breakdown":"A person who goes to a place for a short time, often as a guest.","related":"guest;caller","categories":["People & Relationships"],"senses":[{"part":"noun","definition":"A person who goes to a place for a short time, often as a guest.","definitionZh":"访客；来访者","examples":["All visitors must sign in at reception.","We had visitors from another city this weekend."]}]},{"word":"afraid","part":"adjective","phonetic":"/əˈfreɪd/","definition":"Feeling fear or worry about something that may happen or cause harm.","definitionZh":"害怕的；恐惧的","examples":["The child was afraid of the dark.","She felt afraid when she heard the strange noise."],"tip":"Use “afraid of” before a noun or “afraid to” before an action.","course":"en","breakdown":"Feeling fear or worry about something that may happen or cause harm.","related":"scared;frightened","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Feeling fear or worry about something that may happen or cause harm.","definitionZh":"害怕的；恐惧的","examples":["The child was afraid of the dark.","She felt afraid when she heard the strange noise."]}]},{"word":"alive","part":"adjective","phonetic":"/əˈlaɪv/","definition":"Living and not dead; or still active, present or full of energy.","definitionZh":"活着的；有活力的","examples":["The flowers are still alive after the cold night.","The city comes alive after sunset."],"tip":"“Alive” usually follows a verb such as “be,” “stay” or “remain”; it is not normally placed before a noun.","course":"en","breakdown":"Living and not dead; or still active, present or full of energy.","related":"living;active","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Living and not dead; or still active, present or full of energy.","definitionZh":"活着的；有活力的","examples":["The flowers are still alive after the cold night.","The city comes alive after sunset."]}]},{"word":"amazing","part":"adjective","phonetic":"/əˈmeɪzɪŋ/","definition":"Causing great surprise, admiration or pleasure.","definitionZh":"令人惊叹的；了不起的","examples":["The view from the mountain was amazing.","She did an amazing job on the project."],"tip":"“Amazing” describes something that causes amazement; “amazed” describes how a person feels.","course":"en","breakdown":"Causing great surprise, admiration or pleasure.","related":"astonishing;wonderful","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Causing great surprise, admiration or pleasure.","definitionZh":"令人惊叹的；了不起的","examples":["The view from the mountain was amazing.","She did an amazing job on the project."]}]},{"word":"angry","part":"adjective","phonetic":"/ˈæŋɡri/","definition":"Feeling strong annoyance or displeasure because of something unfair, upsetting or unwanted.","definitionZh":"生气的；愤怒的","examples":["He was angry about the unfair decision.","Please do not get angry with your sister."],"tip":"Use “angry with” for a person and “angry about” for a situation or issue.","course":"en","breakdown":"Feeling strong annoyance or displeasure because of something unfair, upsetting or unwanted.","related":"annoyed;upset","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Feeling strong annoyance or displeasure because of something unfair, upsetting or unwanted.","definitionZh":"生气的；愤怒的","examples":["He was angry about the unfair decision.","Please do not get angry with your sister."]}]},{"word":"attractive","part":"adjective","phonetic":"/əˈtræktɪv/","definition":"Pleasant or interesting to look at; or likely to make someone interested.","definitionZh":"有吸引力的；迷人的","examples":["The building has an attractive design.","The company offered an attractive salary."],"tip":"“Attractive” can describe appearance, qualities or an offer that appeals to people.","course":"en","breakdown":"Pleasant or interesting to look at; or likely to make someone interested.","related":"appealing;beautiful","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Pleasant or interesting to look at; or likely to make someone interested.","definitionZh":"有吸引力的；迷人的","examples":["The building has an attractive design.","The company offered an attractive salary."]}]},{"word":"awful","part":"adjective","phonetic":"/ˈɔːfəl/","definition":"Very bad, unpleasant or upsetting.","definitionZh":"糟糕的；可怕的","examples":["The weather was awful during our trip.","I felt awful after staying up all night."],"tip":"“Awful” is a strong negative adjective and is more intense than “bad.”","course":"en","breakdown":"Very bad, unpleasant or upsetting.","related":"terrible;horrible","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Very bad, unpleasant or upsetting.","definitionZh":"糟糕的；可怕的","examples":["The weather was awful during our trip.","I felt awful after staying up all night."]}]},{"word":"beautiful","part":"adjective","phonetic":"/ˈbjuːtɪfəl/","definition":"Very pleasing to see, hear or experience.","definitionZh":"美丽的；漂亮的；美好的","examples":["They watched a beautiful sunset over the sea.","She has a beautiful singing voice."],"tip":"“Beautiful” can describe appearance, sound, places and experiences.","course":"en","breakdown":"Very pleasing to see, hear or experience.","related":"lovely;attractive","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Very pleasing to see, hear or experience.","definitionZh":"美丽的；漂亮的；美好的","examples":["They watched a beautiful sunset over the sea.","She has a beautiful singing voice."]}]},{"word":"bright","part":"adjective","phonetic":"/braɪt/","definition":"Giving or reflecting a lot of light; or intelligent, cheerful or likely to be successful.","definitionZh":"明亮的；聪明的；有希望的","examples":["The room is bright in the morning.","She is a bright student with many ideas."],"tip":"“Bright” can describe light, intelligence, colour or a promising future.","course":"en","breakdown":"Giving or reflecting a lot of light; or intelligent, cheerful or likely to be successful.","related":"shiny;clever","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Giving or reflecting a lot of light; or intelligent, cheerful or likely to be successful.","definitionZh":"明亮的；聪明的；有希望的","examples":["The room is bright in the morning.","She is a bright student with many ideas."]}]},{"word":"careful","part":"adjective","phonetic":"/ˈkerfəl/","definition":"Taking care to avoid mistakes, danger or damage.","definitionZh":"小心的；仔细的","examples":["Be careful when you cross the busy road.","She is careful with her money."],"tip":"Use “careful with” for handling something and “careful about” for a concern or decision.","course":"en","breakdown":"Taking care to avoid mistakes, danger or damage.","related":"cautious;attentive","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Taking care to avoid mistakes, danger or damage.","definitionZh":"小心的；仔细的","examples":["Be careful when you cross the busy road.","She is careful with her money."]}]},{"word":"cheerful","part":"adjective","phonetic":"/ˈtʃɪrfəl/","definition":"Happy and positive, or showing happiness through behaviour and expression.","definitionZh":"快乐的；开朗的","examples":["He gave us a cheerful greeting.","The bright colours make the room feel cheerful."],"tip":"“Cheerful” describes a generally positive mood; “cheered” often describes a change in someone's mood.","course":"en","breakdown":"Happy and positive, or showing happiness through behaviour and expression.","related":"happy;positive","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Happy and positive, or showing happiness through behaviour and expression.","definitionZh":"快乐的；开朗的","examples":["He gave us a cheerful greeting.","The bright colours make the room feel cheerful."]}]},{"word":"clever","part":"adjective","phonetic":"/ˈklevər/","definition":"Quick to understand, learn or find solutions; showing intelligence or skill.","definitionZh":"聪明的；机灵的","examples":["That was a clever way to solve the problem.","She is clever at finding practical solutions."],"tip":"“Clever” often suggests quick thinking or skill; “intelligent” is a broader description of mental ability.","course":"en","breakdown":"Quick to understand, learn or find solutions; showing intelligence or skill.","related":"smart;bright","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Quick to understand, learn or find solutions; showing intelligence or skill.","definitionZh":"聪明的；机灵的","examples":["That was a clever way to solve the problem.","She is clever at finding practical solutions."]}]},{"word":"comfortable","part":"adjective","phonetic":"/ˈkʌmftərbəl/","definition":"Providing physical ease or making someone feel relaxed and free from worry.","definitionZh":"舒适的；自在的","examples":["These shoes are comfortable for walking.","I feel comfortable speaking in front of the class."],"tip":"Use “comfortable with” for feeling at ease about a person, situation or idea.","course":"en","breakdown":"Providing physical ease or making someone feel relaxed and free from worry.","related":"cosy;relaxed","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Providing physical ease or making someone feel relaxed and free from worry.","definitionZh":"舒适的；自在的","examples":["These shoes are comfortable for walking.","I feel comfortable speaking in front of the class."]}]},{"word":"confused","part":"adjective","phonetic":"/kənˈfjuːzd/","definition":"Unable to understand something clearly or to think clearly about it.","definitionZh":"困惑的；迷茫的","examples":["I was confused by the new instructions.","The students looked confused after the explanation."],"tip":"“Confused” describes a person's feeling; “confusing” describes something that causes that feeling.","course":"en","breakdown":"Unable to understand something clearly or to think clearly about it.","related":"puzzled;uncertain","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Unable to understand something clearly or to think clearly about it.","definitionZh":"困惑的；迷茫的","examples":["I was confused by the new instructions.","The students looked confused after the explanation."]}]},{"word":"cool","part":"adjective / noun / verb","phonetic":"/kuːl/","definition":"Slightly cold; calm and confident; or fashionable and admired.","definitionZh":"凉爽的；冷静的；很酷的","examples":["The evening air feels cool.","She stayed cool during the difficult interview."],"tip":"“Cool” has several informal meanings; context shows whether it refers to temperature, behaviour or style.","course":"en","breakdown":"Slightly cold; calm and confident; or fashionable and admired.","related":"chilly;calm","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Slightly cold; calm and confident; or fashionable and admired.","definitionZh":"凉爽的；冷静的；很酷的","examples":["The evening air feels cool.","She stayed cool during the difficult interview."]},{"part":"noun","definition":"A calm, confident manner or a pleasantly low temperature.","definitionZh":"冷静；凉爽","examples":["He kept his cool during the argument."]},{"part":"verb","definition":"To make something less warm, or to become less warm.","definitionZh":"使冷却；变凉","examples":["Let the soup cool before serving."]}]},{"word":"dangerous","part":"adjective","phonetic":"/ˈdeɪndʒərəs/","definition":"Likely to cause harm, injury or damage.","definitionZh":"危险的","examples":["It is dangerous to swim during a storm.","The road becomes dangerous when it is wet."],"tip":"Use “dangerous to” before an action and “dangerous for” before the person or thing at risk.","course":"en","breakdown":"Likely to cause harm, injury or damage.","related":"unsafe;risky","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Likely to cause harm, injury or damage.","definitionZh":"危险的","examples":["It is dangerous to swim during a storm.","The road becomes dangerous when it is wet."]}]},{"word":"delighted","part":"adjective","phonetic":"/dɪˈlaɪtɪd/","definition":"Very pleased and happy about something.","definitionZh":"高兴的；欣喜的","examples":["We were delighted to hear the good news.","She was delighted with her exam results."],"tip":"Use “delighted to” before an action and “delighted with” before the thing that pleased someone.","course":"en","breakdown":"Very pleased and happy about something.","related":"pleased;thrilled","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Very pleased and happy about something.","definitionZh":"高兴的；欣喜的","examples":["We were delighted to hear the good news.","She was delighted with her exam results."]}]},{"word":"different","part":"adjective","phonetic":"/ˈdɪfərənt/","definition":"Not the same as another person or thing; having distinct qualities.","definitionZh":"不同的；有差异的","examples":["The two designs look very different.","We tried a different approach to the problem."],"tip":"Use “different from” in standard formal English; “different to” is also common in some varieties.","course":"en","breakdown":"Not the same as another person or thing; having distinct qualities.","related":"distinct;unlike","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Not the same as another person or thing; having distinct qualities.","definitionZh":"不同的；有差异的","examples":["The two designs look very different.","We tried a different approach to the problem."]}]},{"word":"difficult","part":"adjective","phonetic":"/ˈdɪfɪkəlt/","definition":"Not easy to do, understand or deal with.","definitionZh":"困难的；艰难的","examples":["The final question was difficult to answer.","It can be difficult to change a long-standing habit."],"tip":"Use “difficult to” before a verb and “difficult for” before the person facing the challenge.","course":"en","breakdown":"Not easy to do, understand or deal with.","related":"hard;challenging","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Not easy to do, understand or deal with.","definitionZh":"困难的；艰难的","examples":["The final question was difficult to answer.","It can be difficult to change a long-standing habit."]}]},{"word":"dirty","part":"adjective / verb","phonetic":"/ˈdɜːrti/","definition":"Not clean; covered with dust, marks or other unwanted material; or to make something unclean.","definitionZh":"脏的；弄脏","examples":["Your shoes are dirty from the rain.","Be careful not to dirty the white shirt."],"tip":"“Dirty” describes something unclean; as a verb, it means to make something dirty.","course":"en","breakdown":"Not clean; covered with dust, marks or other unwanted material; or to make something unclean.","related":"unclean;soiled","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Not clean; covered with dust, marks or other unwanted material","definitionZh":"脏的","examples":["Your shoes are dirty from the rain."]},{"part":"verb","definition":"to make something unclean.","definitionZh":"弄脏","examples":["Be careful not to dirty the white shirt."]}]},{"word":"easy","part":"adjective","phonetic":"/ˈiːzi/","definition":"Not difficult to do, understand or achieve; requiring little effort.","definitionZh":"容易的；轻松的","examples":["The first exercise is easy to understand.","It is not easy to learn a new language quickly."],"tip":"Use “easy to” before a verb; “easy for” identifies the person who finds something simple.","course":"en","breakdown":"Not difficult to do, understand or achieve; requiring little effort.","related":"simple;effortless","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Not difficult to do, understand or achieve; requiring little effort.","definitionZh":"容易的；轻松的","examples":["The first exercise is easy to understand.","It is not easy to learn a new language quickly."]}]},{"word":"empty","part":"adjective / verb","phonetic":"/ˈempti/","definition":"Containing nothing or no one; or to remove everything from a container or place.","definitionZh":"空的；倒空","examples":["The room was empty when we arrived.","Please empty the box before recycling it."],"tip":"“Empty” can describe a container with nothing inside or the action of removing its contents.","course":"en","breakdown":"Containing nothing or no one; or to remove everything from a container or place.","related":"vacant;blank","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Containing nothing or no one","definitionZh":"空的","examples":["The room was empty when we arrived."]},{"part":"verb","definition":"to remove everything from a container or place.","definitionZh":"倒空","examples":["Please empty the box before recycling it."]}]},{"word":"excited","part":"adjective","phonetic":"/ɪkˈsaɪtɪd/","definition":"Feeling very happy and enthusiastic about something that is going to happen.","definitionZh":"兴奋的；激动的","examples":["The children were excited about the school trip.","I am excited to start my new job."],"tip":"“Excited” describes how someone feels; “exciting” describes something that causes excitement.","course":"en","breakdown":"Feeling very happy and enthusiastic about something that is going to happen.","related":"enthusiastic;eager","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Feeling very happy and enthusiastic about something that is going to happen.","definitionZh":"兴奋的；激动的","examples":["The children were excited about the school trip.","I am excited to start my new job."]}]},{"word":"famous","part":"adjective","phonetic":"/ˈfeɪməs/","definition":"Known by many people, usually because of an achievement, quality or public role.","definitionZh":"著名的；有名的","examples":["The city is famous for its old buildings.","She became famous after winning the competition."],"tip":"Use “famous for” to explain why someone or something is well known.","course":"en","breakdown":"Known by many people, usually because of an achievement, quality or public role.","related":"well-known;celebrated","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Known by many people, usually because of an achievement, quality or public role.","definitionZh":"著名的；有名的","examples":["The city is famous for its old buildings.","She became famous after winning the competition."]}]},{"word":"fantastic","part":"adjective","phonetic":"/fænˈtæstɪk/","definition":"Extremely good, enjoyable or impressive.","definitionZh":"极好的；了不起的","examples":["We had a fantastic time at the festival.","Your idea sounds fantastic."],"tip":"“Fantastic” is an enthusiastic informal way to say that something is excellent.","course":"en","breakdown":"Extremely good, enjoyable or impressive.","related":"excellent;wonderful","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Extremely good, enjoyable or impressive.","definitionZh":"极好的；了不起的","examples":["We had a fantastic time at the festival.","Your idea sounds fantastic."]}]},{"word":"fast","part":"adjective / adverb / noun","phonetic":"/fæst/","definition":"Moving, happening or operating at high speed; or a period of not eating.","definitionZh":"快的；迅速地；禁食","examples":["This train is faster than the local service.","She can type very fast."],"tip":"“Fast” can be an adjective or adverb; the adverb form is not “fastly.”","course":"en","breakdown":"Moving, happening or operating at high speed; or a period of not eating.","related":"quick;rapid","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Moving, happening or operating at high speed.","definitionZh":"快的；迅速的","examples":["This train is faster than the local service."]},{"part":"adverb","definition":"At high speed or in a short amount of time.","definitionZh":"迅速地；快速地","examples":["She can type very fast."]},{"part":"noun","definition":"A period during which a person chooses not to eat.","definitionZh":"禁食；斋戒","examples":["He completed a one-day fast."]}]},{"word":"favourite","part":"adjective / noun","phonetic":"/ˈfeɪvərɪt/","definition":"Liked more than others; or a person or thing someone likes best.","definitionZh":"最喜欢的；特别喜爱的；最爱","examples":["Blue is my favourite colour.","That café is one of my favourites."],"tip":"“Favourite” is the British spelling; American English uses “favorite.”","course":"en","breakdown":"Liked more than others; or a person or thing someone likes best.","related":"preferred;beloved","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Liked more than others","definitionZh":"最喜欢的；特别喜爱的","examples":["Blue is my favourite colour."]},{"part":"noun","definition":"a person or thing someone likes best.","definitionZh":"最爱","examples":["That café is one of my favourites."]}]},{"word":"fine","part":"adjective / adverb / noun","phonetic":"/faɪn/","definition":"Good or satisfactory; healthy or well; or a sum of money paid as punishment.","definitionZh":"好的；不错的；罚款","examples":["Are you feeling fine today?","The driver had to pay a fine for parking illegally."],"tip":"“Fine” can mean satisfactory, well or a financial penalty; the intended meaning depends on context.","course":"en","breakdown":"Good or satisfactory; healthy or well; or a sum of money paid as punishment.","related":"well;acceptable","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Good or satisfactory; healthy or well; or made up of very small or delicate parts.","definitionZh":"好的；不错的；健康的；精细的","examples":["Are you feeling fine today?"]},{"part":"adverb","definition":"In a satisfactory or acceptable way.","definitionZh":"很好地；令人满意地","examples":["The old computer still works fine."]},{"part":"noun","definition":"A sum of money that someone must pay as punishment for breaking a rule or law.","definitionZh":"罚款","examples":["The driver had to pay a fine for parking illegally."]}]},{"word":"fit","part":"adjective / verb / noun","phonetic":"/fɪt/","definition":"Healthy and physically strong; the right size or shape; or to be the correct size or to place something into position.","definitionZh":"健康的；合适的；安装","examples":["He stays fit by cycling to work.","This key does not fit the lock."],"tip":"“Fit” can describe health or suitability; as a verb, it can mean to be the right size or to install something.","course":"en","breakdown":"Healthy and physically strong; the right size or shape; or to be the correct size or to place something into position.","related":"healthy;suitable","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Healthy and physically strong; or suitable for a particular purpose or situation.","definitionZh":"健康的；强健的；合适的","examples":["He stays fit by cycling to work."]},{"part":"verb","definition":"To be the correct size or shape for something, or to put something into a particular position.","definitionZh":"合身；适合；安装","examples":["This key does not fit the lock."]},{"part":"noun","definition":"A sudden attack or episode of an illness, or a suitable match between things.","definitionZh":"发作；一阵；适合","examples":["The child had a coughing fit during the night."]}]},{"word":"flat","part":"adjective / noun","phonetic":"/flæt/","definition":"Level and smooth, without a raised or curved surface; or a set of rooms forming one home.","definitionZh":"平的；平坦的；公寓","examples":["The road is flat for most of the route.","They rented a small flat near the station."],"tip":"“Flat” is British English for an apartment; it can also describe a surface or something that has lost air.","course":"en","breakdown":"Level and smooth, without a raised or curved surface; or a set of rooms forming one home.","related":"level;apartment","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Level and smooth, without a raised or curved surface","definitionZh":"平的；平坦的","examples":["The road is flat for most of the route."]},{"part":"noun","definition":"a set of rooms forming one home.","definitionZh":"公寓","examples":["They rented a small flat near the station."]}]},{"word":"fresh","part":"adjective","phonetic":"/freʃ/","definition":"Recently made, gathered or prepared; clean, cool or new in quality.","definitionZh":"新鲜的；清新的；新近的","examples":["We bought fresh vegetables at the market.","A fresh breeze came through the window."],"tip":"“Fresh” can refer to food, air, ideas or something recently made or started.","course":"en","breakdown":"Recently made, gathered or prepared; clean, cool or new in quality.","related":"new;recent","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Recently made, gathered or prepared; clean, cool or new in quality.","definitionZh":"新鲜的；清新的；新近的","examples":["We bought fresh vegetables at the market.","A fresh breeze came through the window."]}]},{"word":"friendly","part":"adjective","phonetic":"/ˈfrendli/","definition":"Kind, pleasant and welcoming towards other people.","definitionZh":"友好的；亲切的","examples":["The staff were friendly and helpful.","Our new neighbour seems very friendly."],"tip":"“Friendly” describes behaviour or atmosphere; use “friendly to” or “friendly with” depending on the relationship.","course":"en","breakdown":"Kind, pleasant and welcoming towards other people.","related":"kind;welcoming","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Kind, pleasant and welcoming towards other people.","definitionZh":"友好的；亲切的","examples":["The staff were friendly and helpful.","Our new neighbour seems very friendly."]}]},{"word":"funny","part":"adjective","phonetic":"/ˈfʌni/","definition":"Causing laughter or amusement; or strange and difficult to explain.","definitionZh":"有趣的；好笑的；奇怪的","examples":["He told a funny story at dinner.","There is a funny smell coming from the kitchen."],"tip":"“Funny” can mean humorous or strange; context determines which meaning is intended.","course":"en","breakdown":"Causing laughter or amusement; or strange and difficult to explain.","related":"humorous;strange","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Causing laughter or amusement; or strange and difficult to explain.","definitionZh":"有趣的；好笑的；奇怪的","examples":["He told a funny story at dinner.","There is a funny smell coming from the kitchen."]}]},{"word":"gentle","part":"adjective","phonetic":"/ˈdʒentəl/","definition":"Kind, calm and careful, or not strong, rough or severe.","definitionZh":"温柔的；轻柔的；温和的","examples":["Use gentle movements when handling the baby.","A gentle rain began to fall."],"tip":"“Gentle” can describe a person's manner, a movement, weather or a mild effect.","course":"en","breakdown":"Kind, calm and careful, or not strong, rough or severe.","related":"mild;soft","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Kind, calm and careful, or not strong, rough or severe.","definitionZh":"温柔的；轻柔的；温和的","examples":["Use gentle movements when handling the baby.","A gentle rain began to fall."]}]},{"word":"glad","part":"adjective","phonetic":"/ɡlæd/","definition":"Feeling pleased, happy or grateful about something.","definitionZh":"高兴的；乐意的","examples":["I am glad you arrived safely.","She was glad to help her classmates."],"tip":"Use “glad to” before an action and “glad that” before a statement.","course":"en","breakdown":"Feeling pleased, happy or grateful about something.","related":"pleased;happy","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Feeling pleased, happy or grateful about something.","definitionZh":"高兴的；乐意的","examples":["I am glad you arrived safely.","She was glad to help her classmates."]}]},{"word":"healthy","part":"adjective","phonetic":"/ˈhelθi/","definition":"In good physical or mental condition; or likely to support good health or development.","definitionZh":"健康的；有益健康的","examples":["A healthy diet includes a variety of foods.","Regular exercise helps people stay healthy."],"tip":"“Healthy” describes a person or something that supports health; “healthful” is a less common alternative for beneficial things.","course":"en","breakdown":"In good physical or mental condition; or likely to support good health or development.","related":"well;fit","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"In good physical or mental condition; or likely to support good health or development.","definitionZh":"健康的；有益健康的","examples":["A healthy diet includes a variety of foods.","Regular exercise helps people stay healthy."]}]},{"word":"helpful","part":"adjective","phonetic":"/ˈhelpfəl/","definition":"Giving useful assistance, information or support.","definitionZh":"有帮助的；乐于助人的","examples":["The guide was very helpful during our visit.","It is helpful to write down new words."],"tip":"“Helpful” can describe a person who gives help or information that makes a task easier.","course":"en","breakdown":"Giving useful assistance, information or support.","related":"useful;supportive","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Giving useful assistance, information or support.","definitionZh":"有帮助的；乐于助人的","examples":["The guide was very helpful during our visit.","It is helpful to write down new words."]}]},{"word":"hungry","part":"adjective","phonetic":"/ˈhʌŋɡri/","definition":"Needing or wanting food; or strongly wanting something.","definitionZh":"饥饿的；渴望的","examples":["I am hungry because I skipped breakfast.","The team is hungry for success."],"tip":"Use “hungry for” to describe a strong desire for something beyond food.","course":"en","breakdown":"Needing or wanting food; or strongly wanting something.","related":"starving;keen","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Needing or wanting food; or strongly wanting something.","definitionZh":"饥饿的；渴望的","examples":["I am hungry because I skipped breakfast.","The team is hungry for success."]}]},{"word":"important","part":"adjective","phonetic":"/ɪmˈpɔːrtənt/","definition":"Having great value, influence or meaning; deserving attention.","definitionZh":"重要的；有意义的","examples":["It is important to save your work regularly.","Family is important to her."],"tip":"Use “important to” for the person or group that values something and “important for” for its purpose or benefit.","course":"en","breakdown":"Having great value, influence or meaning; deserving attention.","related":"significant;essential","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Having great value, influence or meaning; deserving attention.","definitionZh":"重要的；有意义的","examples":["It is important to save your work regularly.","Family is important to her."]}]},{"word":"impossible","part":"adjective","phonetic":"/ɪmˈpɑːsəbəl/","definition":"Unable to happen, be done or be achieved.","definitionZh":"不可能的；办不到的","examples":["It is impossible to finish the project in one hour.","The task seemed impossible at first."],"tip":"Use “impossible to” before a verb to describe something that cannot be done.","course":"en","breakdown":"Unable to happen, be done or be achieved.","related":"unachievable;infeasible","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Unable to happen, be done or be achieved.","definitionZh":"不可能的；办不到的","examples":["It is impossible to finish the project in one hour.","The task seemed impossible at first."]}]},{"word":"lazy","part":"adjective","phonetic":"/ˈleɪzi/","definition":"Unwilling to make an effort or work when effort is needed.","definitionZh":"懒惰的；懒散的","examples":["I felt lazy and stayed on the sofa all afternoon.","It was a lazy Sunday with no plans."],"tip":"“Lazy” can describe a person, action or relaxed period; avoid using it as a judgment without context.","course":"en","breakdown":"Unwilling to make an effort or work when effort is needed.","related":"idle;inactive","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Unwilling to make an effort or work when effort is needed.","definitionZh":"懒惰的；懒散的","examples":["I felt lazy and stayed on the sofa all afternoon.","It was a lazy Sunday with no plans."]}]},{"word":"loud","part":"adjective / adverb","phonetic":"/laʊd/","definition":"Making or producing a lot of sound; or in a way that can be heard clearly.","definitionZh":"大声的；响亮的","examples":["The music was too loud for the small room.","Please do not speak so loud in the library."],"tip":"“Loud” is commonly used as an adjective and informally as an adverb; “loudly” is the standard adverb form.","course":"en","breakdown":"Making or producing a lot of sound; or in a way that can be heard clearly.","related":"noisy;strong","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Making or producing a lot of sound","definitionZh":"大声的","examples":["The music was too loud for the small room."]},{"part":"adverb","definition":"in a way that can be heard clearly.","definitionZh":"响亮的","examples":["Please do not speak so loud in the library."]}]},{"word":"lucky","part":"adjective","phonetic":"/ˈlʌki/","definition":"Having good things happen by chance; or bringing good fortune.","definitionZh":"幸运的；走运的","examples":["We were lucky to catch the last train.","Some people believe this number is lucky."],"tip":"Use “lucky to” before an action and “lucky that” before a statement.","course":"en","breakdown":"Having good things happen by chance; or bringing good fortune.","related":"fortunate;blessed","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Having good things happen by chance; or bringing good fortune.","definitionZh":"幸运的；走运的","examples":["We were lucky to catch the last train.","Some people believe this number is lucky."]}]},{"word":"nice","part":"adjective","phonetic":"/naɪs/","definition":"Pleasant, enjoyable or kind; often used to express general approval.","definitionZh":"好的；愉快的；友善的","examples":["We had a nice meal at the new restaurant.","It was nice of you to help me."],"tip":"“Nice” is common in everyday English but can be vague; choose a more specific adjective when precision matters.","course":"en","breakdown":"Pleasant, enjoyable or kind; often used to express general approval.","related":"pleasant;kind","categories":["Emotions & Descriptions"],"senses":[{"part":"adjective","definition":"Pleasant, enjoyable or kind; often used to express general approval.","definitionZh":"好的；愉快的；友善的","examples":["We had a nice meal at the new restaurant.","It was nice of you to help me."]}]},{"word":"act","part":"noun / verb","phonetic":"/ækt/","definition":"To do something or behave in a particular way; or one thing someone does.","definitionZh":"行动；行为；表演","examples":["You must act quickly in an emergency.","The first act of the play begins with a song."],"tip":"As a verb, “act” means to do or behave; as a noun, it can mean an action or a section of a play.","course":"en","breakdown":"To do something or behave in a particular way; or one thing someone does.","related":"do;perform","categories":["Activities"],"senses":[{"part":"verb","definition":"To do something or behave in a particular way.","definitionZh":"行动；表现","examples":["You must act quickly in an emergency."]},{"part":"noun","definition":"One thing that someone does, or a section of a play or performance.","definitionZh":"行为；举动；表演的一幕","examples":["The first act of the play begins with a song."]}]},{"word":"yoga","part":"noun","phonetic":"/ˈjoʊɡə/","definition":"A practice involving physical postures, breathing and meditation to support health and wellbeing.","definitionZh":"瑜伽","examples":["She does yoga every morning before work.","The yoga class focuses on balance and breathing."],"tip":"“Do yoga” is the usual expression for taking part in this activity.","course":"en","breakdown":"A practice involving physical postures, breathing and meditation to support health and wellbeing.","related":"meditation;exercise","categories":["Activities"],"senses":[{"part":"noun","definition":"A practice involving physical postures, breathing and meditation to support health and wellbeing.","definitionZh":"瑜伽","examples":["She does yoga every morning before work.","The yoga class focuses on balance and breathing."]}]},{"word":"cycle","part":"verb / noun","phonetic":"/ˈsaɪkəl/","definition":"To ride a bicycle; or a series of events that repeats in the same order.","definitionZh":"骑自行车；循环；周期","examples":["We cycle to the park on weekends.","The seasons form a yearly cycle."],"tip":"As a verb, “cycle” can mean ride a bicycle; as a noun, it can describe a repeating sequence.","course":"en","breakdown":"To ride a bicycle; or a series of events that repeats in the same order.","related":"ride;revolve","categories":["Activities"],"senses":[{"part":"verb","definition":"To ride a bicycle","definitionZh":"骑自行车；循环","examples":["We cycle to the park on weekends."]},{"part":"noun","definition":"a series of events that repeats in the same order.","definitionZh":"周期","examples":["The seasons form a yearly cycle."]}]},{"word":"meditate","part":"verb","phonetic":"/ˈmedɪteɪt/","definition":"To spend time quietly focusing the mind, often to become calm or more aware.","definitionZh":"冥想；沉思","examples":["He meditates for ten minutes each morning.","She sat quietly to meditate before the meeting."],"tip":"Use “meditate on” when describing a subject someone thinks about deeply.","course":"en","breakdown":"To spend time quietly focusing the mind, often to become calm or more aware.","related":"reflect;contemplate","categories":["Activities"],"senses":[{"part":"verb","definition":"To spend time quietly focusing the mind, often to become calm or more aware.","definitionZh":"冥想；沉思","examples":["He meditates for ten minutes each morning.","She sat quietly to meditate before the meeting."]}]},{"word":"sew","part":"verb","phonetic":"/soʊ/","definition":"To join or repair pieces of cloth using a needle and thread.","definitionZh":"缝纫；缝补","examples":["My grandmother taught me how to sew a button.","She sewed a small bag from leftover fabric."],"tip":"The past tense and past participle are both “sewed” or “sewn,” depending on use.","course":"en","breakdown":"To join or repair pieces of cloth using a needle and thread.","related":"stitch;embroider","categories":["Activities"],"senses":[{"part":"verb","definition":"To join or repair pieces of cloth using a needle and thread.","definitionZh":"缝纫；缝补","examples":["My grandmother taught me how to sew a button.","She sewed a small bag from leftover fabric."]}]},{"word":"sail","part":"verb / noun","phonetic":"/seɪl/","definition":"To travel across water in a boat or ship; or a large piece of cloth that catches the wind.","definitionZh":"航行；扬帆；帆","examples":["They sailed around the island for a week.","The boat's white sail caught the wind."],"tip":"“Sail” can describe travelling by boat or the fabric that moves a sailing boat.","course":"en","breakdown":"To travel across water in a boat or ship; or a large piece of cloth that catches the wind.","related":"navigate;cruise","categories":["Activities"],"senses":[{"part":"verb","definition":"To travel across water in a boat or ship","definitionZh":"航行；扬帆","examples":["They sailed around the island for a week."]},{"part":"noun","definition":"a large piece of cloth that catches the wind.","definitionZh":"帆","examples":["The boat's white sail caught the wind."]}]},{"word":"surf","part":"verb / noun","phonetic":"/sɜːrf/","definition":"To ride on waves using a surfboard; or to move from one website or page to another online.","definitionZh":"冲浪；浏览网页","examples":["We learned to surf at the beach.","I surf the web to find design references."],"tip":"“Surf” can refer to the water sport or, informally, browsing the internet.","course":"en","breakdown":"To ride on waves using a surfboard; or to move from one website or page to another online.","related":"wave-ride;browse","categories":["Activities"],"senses":[{"part":"verb","definition":"To ride on waves using a surfboard, or to move from one website or page to another online.","definitionZh":"冲浪；浏览网页","examples":["We learned to surf at the beach.","I surf the web to find design references."]},{"part":"noun","definition":"The waves of the sea, especially when they break near the shore.","definitionZh":"海浪；拍岸浪","examples":["The sound of the surf kept us awake."]}]},{"word":"snorkel","part":"verb / noun","phonetic":"/ˈsnɔːrkəl/","definition":"To swim near the surface while breathing through a tube and looking underwater; or the tube used for this activity.","definitionZh":"浮潜；呼吸管","examples":["We snorkelled near the coral reef.","He bought a new snorkel for the trip."],"tip":"“Snorkel” can be used as a verb for the activity or a noun for the breathing tube.","course":"en","breakdown":"To swim near the surface while breathing through a tube and looking underwater; or the tube used for this activity.","related":"dive;swim","categories":["Activities"],"senses":[{"part":"verb","definition":"To swim near the surface while breathing through a tube and looking underwater","definitionZh":"浮潜","examples":["We snorkelled near the coral reef."]},{"part":"noun","definition":"the tube used for this activity.","definitionZh":"呼吸管","examples":["He bought a new snorkel for the trip."]}]},{"word":"picnic","part":"noun / verb","phonetic":"/ˈpɪknɪk/","definition":"A meal eaten outdoors, often in a park or countryside; or to eat such a meal.","definitionZh":"野餐","examples":["We had a picnic beside the lake.","They plan to picnic in the park if the weather is fine."],"tip":"“Have a picnic” is more common than using “picnic” as a verb in everyday conversation.","course":"en","breakdown":"A meal eaten outdoors, often in a park or countryside; or to eat such a meal.","related":"outdoor meal;outing","categories":["Activities"],"senses":[{"part":"noun","definition":"A meal eaten outdoors, often in a park or countryside","definitionZh":"野餐","examples":["We had a picnic beside the lake."]},{"part":"verb","definition":"to eat such a meal.","definitionZh":"野餐","examples":["They plan to picnic in the park if the weather is fine."]}]},{"word":"barbecue","part":"noun / verb","phonetic":"/ˈbɑːrbɪkjuː/","definition":"A meal or gathering where food is cooked outdoors over a fire or grill; or to cook food in this way.","definitionZh":"烧烤；户外烤肉","examples":["We are having a barbecue in the garden.","He barbecued vegetables for dinner."],"tip":"“Barbecue” can refer to the cooking method, the food or the social event; “BBQ” is a common abbreviation.","course":"en","breakdown":"A meal or gathering where food is cooked outdoors over a fire or grill; or to cook food in this way.","related":"grill;cookout","categories":["Activities"],"senses":[{"part":"noun","definition":"A meal or gathering where food is cooked outdoors over a fire or grill","definitionZh":"烧烤","examples":["We are having a barbecue in the garden."]},{"part":"verb","definition":"to cook food in this way.","definitionZh":"户外烤肉","examples":["He barbecued vegetables for dinner."]}]},{"word":"bowl","part":"noun / verb","phonetic":"/boʊl/","definition":"A round, deep container for food; or to roll a ball in a game such as bowling or cricket.","definitionZh":"碗；投球；打保龄球","examples":["She served the soup in a large bowl.","They bowl together every Friday evening."],"tip":"As a noun, “bowl” is a container; as a verb, it can refer to playing bowling or delivering a ball in cricket.","course":"en","breakdown":"A round, deep container for food; or to roll a ball in a game such as bowling or cricket.","related":"dish;roll","categories":["Activities"],"senses":[{"part":"noun","definition":"A round, deep container for food","definitionZh":"碗；投球","examples":["She served the soup in a large bowl."]},{"part":"verb","definition":"to roll a ball in a game such as bowling or cricket.","definitionZh":"打保龄球","examples":["They bowl together every Friday evening."]}]},{"word":"box","part":"noun / verb","phonetic":"/bɑːks/","definition":"A container with flat sides; or to fight using boxing techniques.","definitionZh":"盒子；拳击","examples":["The books arrived in a cardboard box.","He learned to box at a local sports club."],"tip":"“Box” as a verb usually refers to the sport; “box up” means to put items into boxes.","course":"en","breakdown":"A container with flat sides; or to fight using boxing techniques.","related":"container;boxing","categories":["Activities"],"senses":[{"part":"noun","definition":"A container with flat sides","definitionZh":"盒子","examples":["The books arrived in a cardboard box."]},{"part":"verb","definition":"to fight using boxing techniques.","definitionZh":"拳击","examples":["He learned to box at a local sports club."]}]},{"word":"canoe","part":"noun / verb","phonetic":"/kəˈnuː/","definition":"A narrow, light boat moved with a paddle; or to travel in such a boat.","definitionZh":"独木舟；划独木舟","examples":["We hired a canoe on the river.","They canoed across the lake in the afternoon."],"tip":"Use “go canoeing” for the activity and “a canoe” for the boat.","course":"en","breakdown":"A narrow, light boat moved with a paddle; or to travel in such a boat.","related":"kayak;paddle","categories":["Activities"],"senses":[{"part":"noun","definition":"A narrow, light boat moved with a paddle","definitionZh":"独木舟","examples":["We hired a canoe on the river."]},{"part":"verb","definition":"to travel in such a boat.","definitionZh":"划独木舟","examples":["They canoed across the lake in the afternoon."]}]},{"word":"debate","part":"noun / verb","phonetic":"/dɪˈbeɪt/","definition":"A formal discussion in which people present different opinions; or to discuss a subject from different sides.","definitionZh":"辩论；讨论","examples":["The class held a debate about school uniforms.","Experts continue to debate the best solution."],"tip":"Use “debate about” or “debate whether” to introduce the topic being discussed.","course":"en","breakdown":"A formal discussion in which people present different opinions; or to discuss a subject from different sides.","related":"discussion;argument","categories":["Activities"],"senses":[{"part":"noun","definition":"A formal discussion in which people present different opinions","definitionZh":"辩论","examples":["The class held a debate about school uniforms."]},{"part":"verb","definition":"to discuss a subject from different sides.","definitionZh":"讨论","examples":["Experts continue to debate the best solution."]}]},{"word":"decorate","part":"verb","phonetic":"/ˈdekəreɪt/","definition":"To make a place or object more attractive by adding colours, objects or designs.","definitionZh":"装饰；装潢","examples":["We decorated the room with paper flowers.","She likes to decorate cakes for birthdays."],"tip":"Use “decorate with” to introduce the materials or objects added.","course":"en","breakdown":"To make a place or object more attractive by adding colours, objects or designs.","related":"adorn;embellish","categories":["Activities"],"senses":[{"part":"verb","definition":"To make a place or object more attractive by adding colours, objects or designs.","definitionZh":"装饰；装潢","examples":["We decorated the room with paper flowers.","She likes to decorate cakes for birthdays."]}]},{"word":"design","part":"noun / verb","phonetic":"/dɪˈzaɪn/","definition":"A plan or drawing showing how something will look or work; or to create such a plan.","definitionZh":"设计；设计图","examples":["The designer presented three logo designs.","They designed a simple app for students."],"tip":"As a noun, “design” is the plan or result; as a verb, it is the process of creating it.","course":"en","breakdown":"A plan or drawing showing how something will look or work; or to create such a plan.","related":"plan;create","categories":["Activities"],"senses":[{"part":"noun","definition":"A plan or drawing showing how something will look or work","definitionZh":"设计","examples":["The designer presented three logo designs."]},{"part":"verb","definition":"to create such a plan.","definitionZh":"设计图","examples":["They designed a simple app for students."]}]},{"word":"dine","part":"verb","phonetic":"/daɪn/","definition":"To eat a meal, especially dinner, often in a formal or special setting.","definitionZh":"进餐；用餐","examples":["Guests will dine in the main hall.","We dined at a small restaurant by the river."],"tip":"“Dine” is more formal than “eat”; “dine out” means to eat at a restaurant.","course":"en","breakdown":"To eat a meal, especially dinner, often in a formal or special setting.","related":"eat;have dinner","categories":["Activities"],"senses":[{"part":"verb","definition":"To eat a meal, especially dinner, often in a formal or special setting.","definitionZh":"进餐；用餐","examples":["Guests will dine in the main hall.","We dined at a small restaurant by the river."]}]},{"word":"golf","part":"noun / verb","phonetic":"/ɡɑːlf/","definition":"A sport in which players use clubs to hit a small ball into a series of holes in as few strokes as possible; or to play this sport.","definitionZh":"高尔夫球；打高尔夫","examples":["My uncle plays golf every Saturday.","They went golfing during their holiday."],"tip":"“Play golf” is the standard phrase; “go golfing” is also common in American English.","course":"en","breakdown":"A sport in which players use clubs to hit a small ball into a series of holes in as few strokes as possible; or to play this sport.","related":"sport;putting","categories":["Activities"],"senses":[{"part":"noun","definition":"A sport in which players use clubs to hit a small ball into a series of holes in as few strokes as possible","definitionZh":"高尔夫球","examples":["My uncle plays golf every Saturday."]},{"part":"verb","definition":"to play this sport.","definitionZh":"打高尔夫","examples":["They went golfing during their holiday."]}]},{"word":"hunt","part":"verb / noun","phonetic":"/hʌnt/","definition":"To search for or chase an animal in order to catch or kill it; or a search for something.","definitionZh":"狩猎；寻找；搜寻","examples":["The birds hunt for food near the river.","We went on a hunt for the missing keys."],"tip":"“Hunt for” means search for something; the noun can refer to the search itself.","course":"en","breakdown":"To search for or chase an animal in order to catch or kill it; or a search for something.","related":"search;track","categories":["Activities"],"senses":[{"part":"verb","definition":"To search for or chase an animal in order to catch or kill it.","definitionZh":"狩猎；追捕；搜寻","examples":["The birds hunt for food near the river."]},{"part":"noun","definition":"An act or period of searching for something.","definitionZh":"搜寻；寻找","examples":["We went on a hunt for the missing keys."]}]},{"word":"ice skate","part":"verb","phonetic":"/ˈaɪs skeɪt/","definition":"To move across ice using special boots with metal blades attached underneath.","definitionZh":"滑冰","examples":["The children learned to ice-skate during the winter holiday.","She ice-skates at the rink twice a week."],"tip":"Use “go ice-skating” to describe the activity as a leisure plan.","course":"en","breakdown":"To move across ice using special boots with metal blades attached underneath.","related":"skate;glide","categories":["Activities"],"senses":[{"part":"verb","definition":"To move across ice using special boots with metal blades attached underneath.","definitionZh":"滑冰","examples":["The children learned to ice-skate during the winter holiday.","She ice-skates at the rink twice a week."]}]},{"word":"kayak","part":"noun / verb","phonetic":"/ˈkaɪæk/","definition":"A small, narrow boat moved with a double-bladed paddle; or to travel in one.","definitionZh":"皮划艇；划皮划艇","examples":["We rented a kayak near the beach.","They kayaked along the quiet river."],"tip":"Use “go kayaking” for the activity and “a kayak” for the boat.","course":"en","breakdown":"A small, narrow boat moved with a double-bladed paddle; or to travel in one.","related":"canoe;paddle","categories":["Activities"],"senses":[{"part":"noun","definition":"A small, narrow boat moved with a double-bladed paddle","definitionZh":"皮划艇","examples":["We rented a kayak near the beach."]},{"part":"verb","definition":"to travel in one.","definitionZh":"划皮划艇","examples":["They kayaked along the quiet river."]}]},{"word":"march","part":"verb / noun","phonetic":"/mɑːrtʃ/","definition":"To walk with regular, deliberate steps, often as a group; or an organised public walk to express an opinion.","definitionZh":"行进；齐步走；游行","examples":["The band marched through the town.","Thousands joined a peaceful march."],"tip":"As a verb, “march” can mean walk in a disciplined way; as a noun, it can mean a public demonstration.","course":"en","breakdown":"To walk with regular, deliberate steps, often as a group; or an organised public walk to express an opinion.","related":"parade;walk","categories":["Activities"],"senses":[{"part":"verb","definition":"To walk with regular, deliberate steps, often as a group","definitionZh":"行进；齐步走","examples":["The band marched through the town."]},{"part":"noun","definition":"an organised public walk to express an opinion.","definitionZh":"游行","examples":["Thousands joined a peaceful march."]}]},{"word":"model","part":"noun / verb","phonetic":"/ˈmɑːdəl/","definition":"A small copy or representation of something; or to display clothes, products or ideas for others to see.","definitionZh":"模型；模特；展示","examples":["The students built a model of the solar system.","She models clothes for an online shop."],"tip":"“Model” can mean a representation, a person who displays products or the act of presenting them.","course":"en","breakdown":"A small copy or representation of something; or to display clothes, products or ideas for others to see.","related":"replica;demonstrate","categories":["Activities"],"senses":[{"part":"noun","definition":"A small copy or representation of something","definitionZh":"模型；模特","examples":["The students built a model of the solar system."]},{"part":"verb","definition":"to display clothes, products or ideas for others to see.","definitionZh":"展示","examples":["She models clothes for an online shop."]}]},{"word":"motor","part":"noun / verb","phonetic":"/ˈmoʊtər/","definition":"A machine that changes energy into movement; or to travel using a motor vehicle.","definitionZh":"发动机；马达；驾车行驶","examples":["The motor makes a strange noise.","They motored along the coast after lunch."],"tip":"“Motor” is often used as a noun for an engine; as a verb it is less common and means travel by motor vehicle.","course":"en","breakdown":"A machine that changes energy into movement; or to travel using a motor vehicle.","related":"engine;drive","categories":["Activities"],"senses":[{"part":"noun","definition":"A machine that changes energy into movement","definitionZh":"发动机；马达","examples":["The motor makes a strange noise."]},{"part":"verb","definition":"to travel using a motor vehicle.","definitionZh":"驾车行驶","examples":["They motored along the coast after lunch."]}]},{"word":"tweet","part":"noun / verb","phonetic":"/twiːt/","definition":"A short message posted on the social media platform X; or to make a short, high-pitched sound like a small bird.","definitionZh":"推文；发短消息；鸟鸣","examples":["She posted a tweet about the event.","Small birds tweeted in the trees."],"tip":"The social-media meaning is platform-specific; the original verb also describes a bird's short call.","course":"en","breakdown":"A short message posted on the social media platform X; or to make a short, high-pitched sound like a small bird.","related":"post;chirp","categories":["Activities"],"senses":[{"part":"noun","definition":"A short message posted on the social media platform X","definitionZh":"推文；发短消息","examples":["She posted a tweet about the event."]},{"part":"verb","definition":"To post a short message on the social media platform X, or to make a short, high-pitched sound like a small bird.","definitionZh":"发推文；啾啾叫","examples":["She tweeted about the concert after it ended.","Small birds tweeted in the trees."]}]},{"word":"algorithm","part":"noun","phonetic":"/ˈælɡəˌrɪðəm/","definition":"A set of ordered steps or rules used to solve a problem or perform a calculation, especially by a computer.","definitionZh":"算法","examples":["The search engine uses an algorithm to rank results.","Students wrote a simple algorithm for sorting numbers."],"tip":"An algorithm is a method or procedure; it is not limited to computer software.","course":"en","breakdown":"A set of ordered steps or rules used to solve a problem or perform a calculation, especially by a computer.","related":"procedure;method","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A set of ordered steps or rules used to solve a problem or perform a calculation, especially by a computer.","definitionZh":"算法","examples":["The search engine uses an algorithm to rank results.","Students wrote a simple algorithm for sorting numbers."]}]},{"word":"app","part":"noun","phonetic":"/æp/","definition":"A software programme designed to perform a particular task on a phone, tablet or computer.","definitionZh":"应用程序；应用软件","examples":["I use a language-learning app every day.","The app needs permission to access the camera."],"tip":"“App” is short for “application”; it usually refers to software used on a digital device.","course":"en","breakdown":"A software programme designed to perform a particular task on a phone, tablet or computer.","related":"application;software","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A software programme designed to perform a particular task on a phone, tablet or computer.","definitionZh":"应用程序；应用软件","examples":["I use a language-learning app every day.","The app needs permission to access the camera."]}]},{"word":"battery","part":"noun","phonetic":"/ˈbætəri/","definition":"A device that stores chemical energy and supplies electrical power to equipment.","definitionZh":"电池","examples":["My phone battery is almost empty.","The remote control needs two batteries."],"tip":"Use “battery life” for how long a battery can power a device before it needs charging.","course":"en","breakdown":"A device that stores chemical energy and supplies electrical power to equipment.","related":"cell;power source","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A device that stores chemical energy and supplies electrical power to equipment.","definitionZh":"电池","examples":["My phone battery is almost empty.","The remote control needs two batteries."]}]},{"word":"browser","part":"noun","phonetic":"/ˈbraʊzər/","definition":"A computer programme used to access and view websites on the internet.","definitionZh":"浏览器","examples":["Open the page in your web browser.","The browser saved the website in its history."],"tip":"A browser displays websites; a search engine helps users find information online.","course":"en","breakdown":"A computer programme used to access and view websites on the internet.","related":"web browser;client","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A computer programme used to access and view websites on the internet.","definitionZh":"浏览器","examples":["Open the page in your web browser.","The browser saved the website in its history."]}]},{"word":"cable","part":"noun / verb","phonetic":"/ˈkeɪbəl/","definition":"A thick wire or group of wires used to carry electricity or data; or to send a message by cable.","definitionZh":"电缆；电线；有线电视","examples":["The monitor is connected to the computer by a cable.","Please check that the power cable is plugged in."],"tip":"A cable may carry electricity, data or signals; “wire” often refers to a single metal conductor.","course":"en","breakdown":"A thick wire or group of wires used to carry electricity or data; or to send a message by cable.","related":"wire;cord","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A thick wire or group of wires used to carry electricity or data.","definitionZh":"电缆；电线；缆线","examples":["The monitor is connected to the computer by a cable.","Please check that the power cable is plugged in."]},{"part":"verb","definition":"To send someone a message by cable; this use is now uncommon.","definitionZh":"通过电报电缆发送信息（现已少用）","examples":["The agent cabled the news to the office."]}]},{"word":"camera","part":"noun","phonetic":"/ˈkæmərə/","definition":"A device used to take photographs or record video.","definitionZh":"相机；摄像机","examples":["The camera takes clear photos in low light.","She used her phone camera to record the presentation."],"tip":"A camera can capture still images or moving video; a lens is one of its main optical parts.","course":"en","breakdown":"A device used to take photographs or record video.","related":"photographic device;camcorder","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A device used to take photographs or record video.","definitionZh":"相机；摄像机","examples":["The camera takes clear photos in low light.","She used her phone camera to record the presentation."]}]},{"word":"computer","part":"noun","phonetic":"/kəmˈpjuːtər/","definition":"An electronic device that stores and processes information according to instructions from software.","definitionZh":"电脑；计算机","examples":["I use a computer to edit videos.","The computer needs to restart after the update."],"tip":"A computer includes hardware and software; a laptop is a portable type of computer.","course":"en","breakdown":"An electronic device that stores and processes information according to instructions from software.","related":"PC;machine","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"An electronic device that stores and processes information according to instructions from software.","definitionZh":"电脑；计算机","examples":["I use a computer to edit videos.","The computer needs to restart after the update."]}]},{"word":"data","part":"noun","phonetic":"/ˈdeɪtə/","definition":"Facts or information collected for reference, analysis or use by a computer.","definitionZh":"数据；资料","examples":["The team analysed data from the survey.","Please back up your data before updating the system."],"tip":"“Data” is commonly treated as an uncountable singular noun in everyday use, though formal scientific writing may use a plural verb.","course":"en","breakdown":"Facts or information collected for reference, analysis or use by a computer.","related":"information;statistics","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"Facts or information collected for reference, analysis or use by a computer.","definitionZh":"数据；资料","examples":["The team analysed data from the survey.","Please back up your data before updating the system."]}]},{"word":"device","part":"noun","phonetic":"/dɪˈvaɪs/","definition":"A piece of equipment made for a particular purpose, especially an electronic or mechanical one.","definitionZh":"设备；装置；器械","examples":["This device measures the room temperature.","Connect the device to a power source."],"tip":"A device is a general term for a piece of equipment; “gadget” often suggests a small, useful electronic item.","course":"en","breakdown":"A piece of equipment made for a particular purpose, especially an electronic or mechanical one.","related":"equipment;gadget","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A piece of equipment made for a particular purpose, especially an electronic or mechanical one.","definitionZh":"设备；装置；器械","examples":["This device measures the room temperature.","Connect the device to a power source."]}]},{"word":"digital","part":"adjective","phonetic":"/ˈdɪdʒɪtəl/","definition":"Using or relating to information represented electronically, especially by computers.","definitionZh":"数字的；数码的","examples":["The library offers digital copies of old books.","She keeps a digital record of her expenses."],"tip":"“Digital” often describes electronic information or technology, in contrast with analogue systems.","course":"en","breakdown":"Using or relating to information represented electronically, especially by computers.","related":"electronic;computerised","categories":["Science & Technology"],"senses":[{"part":"adjective","definition":"Using or relating to information represented electronically, especially by computers.","definitionZh":"数字的；数码的","examples":["The library offers digital copies of old books.","She keeps a digital record of her expenses."]}]},{"word":"download","part":"verb / noun","phonetic":"/ˌdaʊnˈloʊd/","definition":"To copy data or a file from the internet or another computer to your own device; or the file or process itself.","definitionZh":"下载；下载内容","examples":["You can download the document from the website.","The download took less than a minute."],"tip":"“Download” usually means receive a file; “upload” means send a file from your device to another system.","course":"en","breakdown":"To copy data or a file from the internet or another computer to your own device; or the file or process itself.","related":"save;transfer","categories":["Science & Technology"],"senses":[{"part":"verb","definition":"To copy data or a file from the internet or another computer to your own device.","definitionZh":"下载；将文件或数据保存到本地设备","examples":["You can download the document from the website."]},{"part":"noun","definition":"A file that has been copied to a device, or the process of downloading it.","definitionZh":"下载内容；下载过程","examples":["The download took less than a minute."]}]},{"word":"email","part":"noun / verb","phonetic":"/ˈiːmeɪl/","definition":"A message sent electronically over the internet; or to send someone such a message.","definitionZh":"电子邮件；发邮件","examples":["I received an email from the school.","Please email the completed form to the office."],"tip":"“Email” can be a message or the act of sending one; “an email address” identifies the recipient.","course":"en","breakdown":"A message sent electronically over the internet; or to send someone such a message.","related":"message;electronic mail","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A message sent electronically over the internet","definitionZh":"电子邮件","examples":["I received an email from the school."]},{"part":"verb","definition":"to send someone such a message.","definitionZh":"发邮件","examples":["Please email the completed form to the office."]}]},{"word":"file","part":"noun / verb","phonetic":"/faɪl/","definition":"A collection of information stored under one name on a computer; or to arrange documents or submit them officially.","definitionZh":"文件；档案；归档","examples":["Save the image as a separate file.","Please file the report with the other documents."],"tip":"A computer file stores digital information; as a verb, “file” can mean organise papers or submit a formal document.","course":"en","breakdown":"A collection of information stored under one name on a computer; or to arrange documents or submit them officially.","related":"document;record","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A collection of information stored under one name on a computer","definitionZh":"文件；档案","examples":["Save the image as a separate file."]},{"part":"verb","definition":"to arrange documents or submit them officially.","definitionZh":"归档","examples":["Please file the report with the other documents."]}]},{"word":"internet","part":"noun","phonetic":"/ˈɪntərnet/","definition":"The worldwide system of connected computer networks that allows people to share information and communicate.","definitionZh":"互联网","examples":["The internet makes it easy to find information.","We lost our internet connection during the storm."],"tip":"“Internet” refers to the global network; the web is one service that operates through it.","course":"en","breakdown":"The worldwide system of connected computer networks that allows people to share information and communicate.","related":"online network;web","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"The worldwide system of connected computer networks that allows people to share information and communicate.","definitionZh":"互联网","examples":["The internet makes it easy to find information.","We lost our internet connection during the storm."]}]},{"word":"keyboard","part":"noun","phonetic":"/ˈkiːbɔːrd/","definition":"A set of keys used to enter letters, numbers and commands into a computer or other device.","definitionZh":"键盘","examples":["The keyboard is not working properly.","She typed the password on the keyboard."],"tip":"A keyboard can be physical or displayed on a touchscreen.","course":"en","breakdown":"A set of keys used to enter letters, numbers and commands into a computer or other device.","related":"keypad;input device","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A set of keys used to enter letters, numbers and commands into a computer or other device.","definitionZh":"键盘","examples":["The keyboard is not working properly.","She typed the password on the keyboard."]}]},{"word":"laptop","part":"noun","phonetic":"/ˈlæptɑːp/","definition":"A portable computer with a screen and keyboard joined together, designed to be used on a person's lap or desk.","definitionZh":"笔记本电脑","examples":["He takes his laptop to the library.","My laptop battery lasts about six hours."],"tip":"“Laptop” is a type of portable computer; “notebook computer” is another name for a similar device.","course":"en","breakdown":"A portable computer with a screen and keyboard joined together, designed to be used on a person's lap or desk.","related":"notebook computer;portable PC","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A portable computer with a screen and keyboard joined together, designed to be used on a person's lap or desk.","definitionZh":"笔记本电脑","examples":["He takes his laptop to the library.","My laptop battery lasts about six hours."]}]},{"word":"network","part":"noun / verb","phonetic":"/ˈnetwɜːrk/","definition":"A group of connected people, computers or systems; or to connect with others for information or opportunities.","definitionZh":"网络；人际关系网；建立联系","examples":["The office network stopped working this morning.","Designers network with other professionals at events."],"tip":"A network may connect devices or people; “networking” often refers to building professional relationships.","course":"en","breakdown":"A group of connected people, computers or systems; or to connect with others for information or opportunities.","related":"system;connection","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A group of connected people, computers or systems","definitionZh":"网络；人际关系网","examples":["The office network stopped working this morning."]},{"part":"verb","definition":"to connect with others for information or opportunities.","definitionZh":"建立联系","examples":["Designers network with other professionals at events."]}]},{"word":"password","part":"noun","phonetic":"/ˈpæsˌwɜːrd/","definition":"A secret word or combination of characters used to prove a user's identity and access a system.","definitionZh":"密码","examples":["Choose a strong password for your account.","Never share your password with strangers."],"tip":"A password should be unique and difficult to guess; a passcode is often a shorter numeric or device code.","course":"en","breakdown":"A secret word or combination of characters used to prove a user's identity and access a system.","related":"passcode;credential","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A secret word or combination of characters used to prove a user's identity and access a system.","definitionZh":"密码","examples":["Choose a strong password for your account.","Never share your password with strangers."]}]},{"word":"printer","part":"noun","phonetic":"/ˈprɪntər/","definition":"A machine that produces text or images on paper from a computer or other digital device.","definitionZh":"打印机","examples":["The printer is out of paper.","I printed the document using the office printer."],"tip":"A printer creates a paper copy; a scanner does the reverse by turning paper documents into digital files.","course":"en","breakdown":"A machine that produces text or images on paper from a computer or other digital device.","related":"printing machine;scanner","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A machine that produces text or images on paper from a computer or other digital device.","definitionZh":"打印机","examples":["The printer is out of paper.","I printed the document using the office printer."]}]},{"word":"robot","part":"noun","phonetic":"/ˈroʊbɑːt/","definition":"A machine that can carry out tasks automatically, often controlled by a computer.","definitionZh":"机器人","examples":["The factory uses a robot to assemble small parts.","The robot can move objects from one shelf to another."],"tip":"A robot may be programmed to perform physical tasks or software-based actions.","course":"en","breakdown":"A machine that can carry out tasks automatically, often controlled by a computer.","related":"automaton;machine","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A machine that can carry out tasks automatically, often controlled by a computer.","definitionZh":"机器人","examples":["The factory uses a robot to assemble small parts.","The robot can move objects from one shelf to another."]}]},{"word":"screen","part":"noun / verb","phonetic":"/skriːn/","definition":"The flat surface on a device that displays images and information; or to examine people or things for a particular purpose.","definitionZh":"屏幕；显示器；筛查","examples":["The phone screen is cracked.","The company screens applicants before interviews."],"tip":"As a noun, “screen” often means a display; as a verb, it can mean check or filter.","course":"en","breakdown":"The flat surface on a device that displays images and information; or to examine people or things for a particular purpose.","related":"display;monitor","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"The flat surface on a device that displays images and information","definitionZh":"屏幕；显示器","examples":["The phone screen is cracked."]},{"part":"verb","definition":"to examine people or things for a particular purpose.","definitionZh":"筛查","examples":["The company screens applicants before interviews."]}]},{"word":"software","part":"noun","phonetic":"/ˈsɔːftwer/","definition":"The programmes and instructions that tell a computer or device what to do.","definitionZh":"软件","examples":["The software needs to be updated.","This design software is easy to use."],"tip":"“Software” is uncountable; use “a software programme” or “an application” for one item.","course":"en","breakdown":"The programmes and instructions that tell a computer or device what to do.","related":"programme;application","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"The programmes and instructions that tell a computer or device what to do.","definitionZh":"软件","examples":["The software needs to be updated.","This design software is easy to use."]}]},{"word":"animal","part":"noun","phonetic":"/ˈænɪməl/","definition":"A living creature that can move and sense its surroundings, but is not a plant or human being.","definitionZh":"动物","examples":["The animal moved quietly through the grass.","Some animals are active at night."],"tip":"“Animal” is a broad term that includes mammals, birds, fish, insects and many other groups.","course":"en","breakdown":"A living creature that can move and sense its surroundings, but is not a plant or human being.","related":"creature;wildlife","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A living creature that can move and sense its surroundings, but is not a plant or human being.","definitionZh":"动物","examples":["The animal moved quietly through the grass.","Some animals are active at night."]}]},{"word":"atmosphere","part":"noun","phonetic":"/ˈætməsfɪr/","definition":"The layer of gases surrounding a planet; or the feeling or mood of a place or situation.","definitionZh":"大气层；气氛","examples":["Earth's atmosphere helps protect life on the planet.","The café has a relaxed atmosphere."],"tip":"“Atmosphere” can refer to gases around a planet or the mood created by a place.","course":"en","breakdown":"The layer of gases surrounding a planet; or the feeling or mood of a place or situation.","related":"air;ambience","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The layer of gases surrounding a planet; or the feeling or mood of a place or situation.","definitionZh":"大气层；气氛","examples":["Earth's atmosphere helps protect life on the planet.","The café has a relaxed atmosphere."]}]},{"word":"autumn","part":"noun","phonetic":"/ˈɔːtəm/","definition":"The season between summer and winter, when temperatures become cooler and many trees lose their leaves.","definitionZh":"秋天；秋季","examples":["The leaves turn red and gold in autumn.","We usually travel in early autumn."],"tip":"“Autumn” is common in British English; “fall” is common in American English.","course":"en","breakdown":"The season between summer and winter, when temperatures become cooler and many trees lose their leaves.","related":"fall;season","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The season between summer and winter, when temperatures become cooler and many trees lose their leaves.","definitionZh":"秋天；秋季","examples":["The leaves turn red and gold in autumn.","We usually travel in early autumn."]}]},{"word":"breeze","part":"noun / verb","phonetic":"/briːz/","definition":"A light, gentle wind; or to move easily and quickly through something.","definitionZh":"微风；轻风","examples":["A cool breeze came through the open window.","She breezed through the first part of the test."],"tip":"As a noun, “breeze” is a gentle wind; informally, the verb can mean complete something easily.","course":"en","breakdown":"A light, gentle wind; or to move easily and quickly through something.","related":"wind;gust","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A light, gentle wind","definitionZh":"微风","examples":["A cool breeze came through the open window."]},{"part":"verb","definition":"to move easily and quickly through something.","definitionZh":"轻风","examples":["She breezed through the first part of the test."]}]},{"word":"climate","part":"noun","phonetic":"/ˈklaɪmət/","definition":"The usual weather conditions of a region over a long period of time; or the general atmosphere of a situation.","definitionZh":"气候；氛围","examples":["The region has a warm, humid climate.","The company is trying to create a supportive work climate."],"tip":"Climate describes long-term patterns; weather describes conditions at a particular time.","course":"en","breakdown":"The usual weather conditions of a region over a long period of time; or the general atmosphere of a situation.","related":"weather pattern;conditions","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The usual weather conditions of a region over a long period of time; or the general atmosphere of a situation.","definitionZh":"气候；氛围","examples":["The region has a warm, humid climate.","The company is trying to create a supportive work climate."]}]},{"word":"cloud","part":"noun / verb","phonetic":"/klaʊd/","definition":"A mass of tiny water droplets or ice crystals in the sky; or to make something difficult to see or understand.","definitionZh":"云；云层；使模糊","examples":["Dark clouds gathered before the storm.","Anger can cloud a person's judgement."],"tip":"As a noun, “cloud” refers to a visible mass in the sky; as a verb, it can mean obscure or confuse.","course":"en","breakdown":"A mass of tiny water droplets or ice crystals in the sky; or to make something difficult to see or understand.","related":"vapour;mist","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A mass of tiny water droplets or ice crystals in the sky","definitionZh":"云；云层","examples":["Dark clouds gathered before the storm."]},{"part":"verb","definition":"to make something difficult to see or understand.","definitionZh":"使模糊","examples":["Anger can cloud a person's judgement."]}]},{"word":"coral","part":"noun / adjective","phonetic":"/ˈkɔːrəl/","definition":"A hard substance formed by tiny sea animals, often creating reefs; or relating to coral.","definitionZh":"珊瑚；珊瑚色的","examples":["The reef is home to many kinds of coral.","Coral reefs support a wide range of marine life."],"tip":"Coral reefs are living ecosystems and can be damaged by warming seas and pollution.","course":"en","breakdown":"A hard substance formed by tiny sea animals, often creating reefs; or relating to coral.","related":"reef;marine organism","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A hard substance formed by tiny sea animals, often creating reefs","definitionZh":"珊瑚","examples":["The reef is home to many kinds of coral."]},{"part":"adjective","definition":"relating to coral.","definitionZh":"珊瑚色的","examples":["Coral reefs support a wide range of marine life."]}]},{"word":"crop","part":"noun / verb","phonetic":"/krɑːp/","definition":"A plant grown and collected for food or other use; or to cut something short.","definitionZh":"农作物；庄稼；裁剪","examples":["Rice is an important crop in many countries.","Farmers grow crops during the rainy season."],"tip":"A crop is a plant grown for harvest; “crop” as a verb can also mean cut an image or hair shorter.","course":"en","breakdown":"A plant grown and collected for food or other use; or to cut something short.","related":"harvest;produce","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A plant grown and collected for food or other use","definitionZh":"农作物；庄稼","examples":["Rice is an important crop in many countries."]},{"part":"verb","definition":"To cut part of an image, photograph, or plant away, or to shorten something by cutting.","definitionZh":"裁剪；剪短；修剪","examples":["She cropped the photograph to remove the empty space."]}]},{"word":"earth","part":"noun","phonetic":"/ɜːrθ/","definition":"The planet on which people live; or the soil and ground beneath our feet.","definitionZh":"地球；泥土；大地","examples":["Earth moves around the Sun.","The children planted seeds in the earth."],"tip":"Use “Earth” with a capital letter when referring to the planet; lowercase “earth” can mean soil.","course":"en","breakdown":"The planet on which people live; or the soil and ground beneath our feet.","related":"world;soil","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The planet on which people live; or the soil and ground beneath our feet.","definitionZh":"地球；泥土；大地","examples":["Earth moves around the Sun.","The children planted seeds in the earth."]}]},{"word":"earthquake","part":"noun","phonetic":"/ˈɜːrθkweɪk/","definition":"A sudden movement of the ground caused by activity within the Earth's crust.","definitionZh":"地震","examples":["The earthquake damaged several buildings.","Scientists monitor the region for signs of another earthquake."],"tip":"An earthquake is measured by its magnitude and can cause shaking, landslides or tsunamis.","course":"en","breakdown":"A sudden movement of the ground caused by activity within the Earth's crust.","related":"tremor;seismic event","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A sudden movement of the ground caused by activity within the Earth's crust.","definitionZh":"地震","examples":["The earthquake damaged several buildings.","Scientists monitor the region for signs of another earthquake."]}]},{"word":"ecosystem","part":"noun","phonetic":"/ˈiːkoʊˌsɪstəm/","definition":"A community of living things and the non-living environment that interact in a particular area.","definitionZh":"生态系统","examples":["A forest is an ecosystem with many connected species.","Pollution can damage a river ecosystem."],"tip":"An ecosystem includes organisms and their physical environment, not just the animals living there.","course":"en","breakdown":"A community of living things and the non-living environment that interact in a particular area.","related":"habitat;ecological community","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A community of living things and the non-living environment that interact in a particular area.","definitionZh":"生态系统","examples":["A forest is an ecosystem with many connected species.","Pollution can damage a river ecosystem."]}]},{"word":"energy","part":"noun","phonetic":"/ˈenərdʒi/","definition":"The ability to do work or cause change; or the strength and enthusiasm someone has.","definitionZh":"能量；能源；精力","examples":["Solar panels turn sunlight into electrical energy.","I have more energy after a good night's sleep."],"tip":"“Energy” can refer to physical power, sources of electricity or a person's vitality.","course":"en","breakdown":"The ability to do work or cause change; or the strength and enthusiasm someone has.","related":"power;vitality","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The ability to do work or cause change; or the strength and enthusiasm someone has.","definitionZh":"能量；能源；精力","examples":["Solar panels turn sunlight into electrical energy.","I have more energy after a good night's sleep."]}]},{"word":"flower","part":"noun / verb","phonetic":"/ˈflaʊər/","definition":"The part of a plant that produces seeds and is often colourful; or to develop successfully.","definitionZh":"花；开花","examples":["The garden is full of flowers in spring.","The project began to flower after the team received support."],"tip":"As a noun, “flower” is the reproductive part of a plant; as a verb, it can mean develop or flourish.","course":"en","breakdown":"The part of a plant that produces seeds and is often colourful; or to develop successfully.","related":"blossom;bloom","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The part of a plant that produces seeds and is often colourful","definitionZh":"花","examples":["The garden is full of flowers in spring."]},{"part":"verb","definition":"to develop successfully.","definitionZh":"开花","examples":["The project began to flower after the team received support."]}]},{"word":"habitat","part":"noun","phonetic":"/ˈhæbɪtæt/","definition":"The natural home or environment of a plant or animal.","definitionZh":"栖息地；生境","examples":["Wetlands provide a habitat for many birds.","Building roads can destroy animal habitats."],"tip":"A habitat provides the food, shelter and conditions an organism needs to live.","course":"en","breakdown":"The natural home or environment of a plant or animal.","related":"environment;home","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The natural home or environment of a plant or animal.","definitionZh":"栖息地；生境","examples":["Wetlands provide a habitat for many birds.","Building roads can destroy animal habitats."]}]},{"word":"insect","part":"noun","phonetic":"/ˈɪnsekt/","definition":"A small animal with six legs and usually one or two pairs of wings.","definitionZh":"昆虫","examples":["A butterfly is a colourful insect.","Some insects help plants by carrying pollen."],"tip":"Insects have six legs; spiders are not insects because they have eight legs.","course":"en","breakdown":"A small animal with six legs and usually one or two pairs of wings.","related":"bug;arthropod","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A small animal with six legs and usually one or two pairs of wings.","definitionZh":"昆虫","examples":["A butterfly is a colourful insect.","Some insects help plants by carrying pollen."]}]},{"word":"leaf","part":"noun","phonetic":"/liːf/","definition":"A flat, usually green part of a plant that grows from a stem or branch.","definitionZh":"叶子；叶片","examples":["A yellow leaf fell from the tree.","The plant has broad leaves that collect sunlight."],"tip":"The plural of “leaf” is “leaves.”","course":"en","breakdown":"A flat, usually green part of a plant that grows from a stem or branch.","related":"foliage;blade","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A flat, usually green part of a plant that grows from a stem or branch.","definitionZh":"叶子；叶片","examples":["A yellow leaf fell from the tree.","The plant has broad leaves that collect sunlight."]}]},{"word":"lightning","part":"noun","phonetic":"/ˈlaɪtnɪŋ/","definition":"A sudden bright flash of electricity in the sky during a storm.","definitionZh":"闪电","examples":["Lightning lit up the sky during the storm.","We went indoors when we saw the lightning."],"tip":"Lightning is the flash of electricity; thunder is the sound caused by the same event.","course":"en","breakdown":"A sudden bright flash of electricity in the sky during a storm.","related":"electric discharge;flash","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A sudden bright flash of electricity in the sky during a storm.","definitionZh":"闪电","examples":["Lightning lit up the sky during the storm.","We went indoors when we saw the lightning."]}]},{"word":"mountain","part":"noun","phonetic":"/ˈmaʊntən/","definition":"A very high natural area of land, higher and steeper than a hill.","definitionZh":"山；山脉","examples":["They climbed the mountain before sunrise.","Snow covered the top of the mountain."],"tip":"A mountain is generally higher and steeper than a hill, though exact definitions vary.","course":"en","breakdown":"A very high natural area of land, higher and steeper than a hill.","related":"peak;mount","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A very high natural area of land, higher and steeper than a hill.","definitionZh":"山；山脉","examples":["They climbed the mountain before sunrise.","Snow covered the top of the mountain."]}]},{"word":"ocean","part":"noun","phonetic":"/ˈoʊʃən/","definition":"One of the very large areas of salt water that cover most of Earth's surface.","definitionZh":"海洋","examples":["The Pacific Ocean is the largest ocean on Earth.","Many species live deep in the ocean."],"tip":"An ocean is larger than a sea; the five named oceans are connected parts of one global body of water.","course":"en","breakdown":"One of the very large areas of salt water that cover most of Earth's surface.","related":"sea;marine waters","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"One of the very large areas of salt water that cover most of Earth's surface.","definitionZh":"海洋","examples":["The Pacific Ocean is the largest ocean on Earth.","Many species live deep in the ocean."]}]},{"word":"planet","part":"noun","phonetic":"/ˈplænɪt/","definition":"A large round object in space that moves around a star and does not produce its own light.","definitionZh":"行星","examples":["Mars is the fourth planet from the Sun.","Scientists are searching for planets beyond our solar system."],"tip":"A planet orbits a star; a moon orbits a planet.","course":"en","breakdown":"A large round object in space that moves around a star and does not produce its own light.","related":"world;celestial body","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A large round object in space that moves around a star and does not produce its own light.","definitionZh":"行星","examples":["Mars is the fourth planet from the Sun.","Scientists are searching for planets beyond our solar system."]}]},{"word":"pollution","part":"noun","phonetic":"/pəˈluːʃən/","definition":"Harmful substances or waste that make air, water or land dirty or unsafe.","definitionZh":"污染","examples":["Plastic pollution threatens marine animals.","The city introduced measures to reduce air pollution."],"tip":"“Pollution” is usually uncountable; name the type, such as air, water or noise pollution.","course":"en","breakdown":"Harmful substances or waste that make air, water or land dirty or unsafe.","related":"contamination;waste","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"Harmful substances or waste that make air, water or land dirty or unsafe.","definitionZh":"污染","examples":["Plastic pollution threatens marine animals.","The city introduced measures to reduce air pollution."]}]},{"word":"recycle","part":"verb","phonetic":"/ˌriːˈsaɪkəl/","definition":"To process used materials so they can be made into new products instead of being thrown away.","definitionZh":"回收利用；再循环","examples":["Please recycle paper and plastic bottles.","The company recycles old electronic equipment."],"tip":"Use “recycle” for processing materials; “reuse” means use an item again without necessarily processing it.","course":"en","breakdown":"To process used materials so they can be made into new products instead of being thrown away.","related":"reuse;process","categories":["Nature & Environment"],"senses":[{"part":"verb","definition":"To process used materials so they can be made into new products instead of being thrown away.","definitionZh":"回收利用；再循环","examples":["Please recycle paper and plastic bottles.","The company recycles old electronic equipment."]}]},{"word":"season","part":"noun","phonetic":"/ˈsiːzən/","definition":"One of the main periods of the year, such as spring, summer, autumn or winter; or a regular period for an activity.","definitionZh":"季节；旺季；赛季","examples":["Spring is my favourite season.","The football season begins in August."],"tip":"A season can be part of the year or a period when an activity or event takes place.","course":"en","breakdown":"One of the main periods of the year, such as spring, summer, autumn or winter; or a regular period for an activity.","related":"period;time of year","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"One of the main periods of the year, such as spring, summer, autumn or winter; or a regular period for an activity.","definitionZh":"季节；旺季；赛季","examples":["Spring is my favourite season.","The football season begins in August."]}]},{"word":"seed","part":"noun / verb","phonetic":"/siːd/","definition":"The part of a plant that can grow into a new plant; or to plant seeds in an area.","definitionZh":"种子；播种","examples":["Each seed needs water and sunlight to grow.","They seeded the field with grass."],"tip":"As a noun, a seed can grow into a plant; as a verb, it means to sow seeds or arrange competitors in a tournament.","course":"en","breakdown":"The part of a plant that can grow into a new plant; or to plant seeds in an area.","related":"kernel;grain","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The part of a plant that can grow into a new plant","definitionZh":"种子","examples":["Each seed needs water and sunlight to grow."]},{"part":"verb","definition":"to plant seeds in an area.","definitionZh":"播种","examples":["They seeded the field with grass."]}]},{"word":"sky","part":"noun","phonetic":"/skaɪ/","definition":"The space above the Earth where clouds, the Sun, the Moon and stars can be seen.","definitionZh":"天空","examples":["The sky turned pink at sunset.","Dark clouds covered the sky."],"tip":"Use “in the sky” for things visible above the ground.","course":"en","breakdown":"The space above the Earth where clouds, the Sun, the Moon and stars can be seen.","related":"heavens;firmament","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The space above the Earth where clouds, the Sun, the Moon and stars can be seen.","definitionZh":"天空","examples":["The sky turned pink at sunset.","Dark clouds covered the sky."]}]},{"word":"soil","part":"noun / verb","phonetic":"/sɔɪl/","definition":"The upper layer of earth in which plants grow; or to make something dirty.","definitionZh":"土壤；泥土；弄脏","examples":["Healthy soil helps crops grow.","The rain soaked the soil in the garden."],"tip":"“Soil” is the material plants grow in; as a verb, it means make something dirty.","course":"en","breakdown":"The upper layer of earth in which plants grow; or to make something dirty.","related":"earth;ground","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"The upper layer of earth in which plants grow","definitionZh":"土壤；泥土","examples":["Healthy soil helps crops grow."]},{"part":"verb","definition":"To make something dirty, especially by marking or staining it.","definitionZh":"弄脏；玷污","examples":["Wet shoes can soil the clean floor."]}]},{"word":"star","part":"noun / verb","phonetic":"/stɑːr/","definition":"A large ball of hot gas in space that produces light; or to have an important role in a performance.","definitionZh":"星星；恒星；主演","examples":["We could see a bright star above the hills.","She will star in the school musical."],"tip":"The Sun is a star; as a verb, “star” can mean appear as the main performer.","course":"en","breakdown":"A large ball of hot gas in space that produces light; or to have an important role in a performance.","related":"sun;celestial body","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A large ball of hot gas in space that produces light","definitionZh":"星星；恒星","examples":["We could see a bright star above the hills."]},{"part":"verb","definition":"to have an important role in a performance.","definitionZh":"主演","examples":["She will star in the school musical."]}]},{"word":"storm","part":"noun / verb","phonetic":"/stɔːrm/","definition":"A period of very bad weather with strong wind, rain, snow or thunder; or to move somewhere suddenly and forcefully.","definitionZh":"暴风雨；风暴；冲进","examples":["The storm brought heavy rain and strong winds.","The children watched the storm from indoors."],"tip":"A storm can involve wind, rain, snow or thunder; “storm out” means leave angrily.","course":"en","breakdown":"A period of very bad weather with strong wind, rain, snow or thunder; or to move somewhere suddenly and forcefully.","related":"tempest;downpour","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A period of very bad weather with strong wind, rain, snow or thunder","definitionZh":"暴风雨；风暴","examples":["The storm brought heavy rain and strong winds."]},{"part":"verb","definition":"To move somewhere suddenly and forcefully, often because of anger.","definitionZh":"猛冲；气势汹汹地闯入","examples":["He stormed out of the room after the argument."]}]},{"word":"tree","part":"noun","phonetic":"/triː/","definition":"A tall plant with a hard trunk, branches and leaves or needles.","definitionZh":"树；树木","examples":["A large tree provides shade in the garden.","The birds built a nest in the tree."],"tip":"A tree has a trunk and branches; a shrub is usually smaller and has several woody stems.","course":"en","breakdown":"A tall plant with a hard trunk, branches and leaves or needles.","related":"plant;wood","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A tall plant with a hard trunk, branches and leaves or needles.","definitionZh":"树；树木","examples":["A large tree provides shade in the garden.","The birds built a nest in the tree."]}]},{"word":"valley","part":"noun","phonetic":"/ˈvæli/","definition":"A low area of land between hills or mountains, often with a river running through it.","definitionZh":"山谷；河谷","examples":["A small village lies in the valley.","The morning fog covered the valley."],"tip":"A valley is lower than the surrounding land and is often shaped by rivers or glaciers.","course":"en","breakdown":"A low area of land between hills or mountains, often with a river running through it.","related":"dale;lowland","categories":["Nature & Environment"],"senses":[{"part":"noun","definition":"A low area of land between hills or mountains, often with a river running through it.","definitionZh":"山谷；河谷","examples":["A small village lies in the valley.","The morning fog covered the valley."]}]},{"word":"ancient","part":"adjective","phonetic":"/ˈeɪnʃənt/","definition":"Belonging to a very distant past, especially a historical period long before the present.","definitionZh":"古代的；古老的","examples":["The museum displays ancient tools and pottery.","They visited the ruins of an ancient city."],"tip":"“Ancient” usually refers to a distant historical past, not simply something old.","course":"en","breakdown":"Belonging to a very distant past, especially a historical period long before the present.","related":"antique;historic","categories":["History & Culture"],"senses":[{"part":"adjective","definition":"Belonging to a very distant past, especially a historical period long before the present.","definitionZh":"古代的；古老的","examples":["The museum displays ancient tools and pottery.","They visited the ruins of an ancient city."]}]},{"word":"artist","part":"noun","phonetic":"/ˈɑːrtɪst/","definition":"A person who creates art, such as paintings, drawings, music or performances.","definitionZh":"艺术家；艺人","examples":["The artist displayed her paintings in a gallery.","He works as a digital artist for a game studio."],"tip":"An artist may work in visual art, music, performance or another creative field.","course":"en","breakdown":"A person who creates art, such as paintings, drawings, music or performances.","related":"creator;painter","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A person who creates art, such as paintings, drawings, music or performances.","definitionZh":"艺术家；艺人","examples":["The artist displayed her paintings in a gallery.","He works as a digital artist for a game studio."]}]},{"word":"ceremony","part":"noun","phonetic":"/ˈserəˌmoʊni/","definition":"A formal event held to mark an important occasion or follow a tradition.","definitionZh":"典礼；仪式","examples":["The graduation ceremony begins at ten.","They held a small ceremony to welcome the new members."],"tip":"A ceremony is usually a planned formal event; a ritual is a repeated action with cultural or religious meaning.","course":"en","breakdown":"A formal event held to mark an important occasion or follow a tradition.","related":"event;ritual","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A formal event held to mark an important occasion or follow a tradition.","definitionZh":"典礼；仪式","examples":["The graduation ceremony begins at ten.","They held a small ceremony to welcome the new members."]}]},{"word":"community","part":"noun","phonetic":"/kəˈmjuːnəti/","definition":"A group of people who live in the same area or share an interest, identity or purpose.","definitionZh":"社区；群体；社群","examples":["The local community organised a clean-up day.","An online community can connect people with shared interests."],"tip":"A community may be based on location or shared interests, not only on where people live.","course":"en","breakdown":"A group of people who live in the same area or share an interest, identity or purpose.","related":"society;group","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A group of people who live in the same area or share an interest, identity or purpose.","definitionZh":"社区；群体；社群","examples":["The local community organised a clean-up day.","An online community can connect people with shared interests."]}]},{"word":"concert","part":"noun","phonetic":"/ˈkɑːnsərt/","definition":"A public performance of music, usually given by one or more musicians or groups.","definitionZh":"音乐会；演唱会","examples":["We bought tickets for the concert next month.","The band performed live at an outdoor concert."],"tip":"A concert is a live music event; a recital is usually a smaller performance by one musician or a small group.","course":"en","breakdown":"A public performance of music, usually given by one or more musicians or groups.","related":"performance;show","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A public performance of music, usually given by one or more musicians or groups.","definitionZh":"音乐会；演唱会","examples":["We bought tickets for the concert next month.","The band performed live at an outdoor concert."]}]},{"word":"custom","part":"noun","phonetic":"/ˈkʌstəm/","definition":"A traditional way of behaving or doing something in a particular society or group.","definitionZh":"习俗；风俗；惯例","examples":["It is a local custom to greet guests with tea.","The custom has been passed down for generations."],"tip":"A custom is a social practice shared by a group; a habit is usually an individual's repeated action.","course":"en","breakdown":"A traditional way of behaving or doing something in a particular society or group.","related":"tradition;practice","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A traditional way of behaving or doing something in a particular society or group.","definitionZh":"习俗；风俗；惯例","examples":["It is a local custom to greet guests with tea.","The custom has been passed down for generations."]}]},{"word":"festival","part":"noun","phonetic":"/ˈfestɪvəl/","definition":"A special event or series of events, often held regularly, to celebrate a culture, tradition, art or activity.","definitionZh":"节日；庆典；艺术节","examples":["The city holds a music festival every summer.","Families gathered for the harvest festival."],"tip":"A festival may celebrate a cultural or religious occasion or focus on music, food or the arts.","course":"en","breakdown":"A special event or series of events, often held regularly, to celebrate a culture, tradition, art or activity.","related":"celebration;fair","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A special event or series of events, often held regularly, to celebrate a culture, tradition, art or activity.","definitionZh":"节日；庆典；艺术节","examples":["The city holds a music festival every summer.","Families gathered for the harvest festival."]}]},{"word":"heritage","part":"noun","phonetic":"/ˈherɪtɪdʒ/","definition":"The traditions, achievements, buildings and cultural features passed down from earlier generations.","definitionZh":"遗产；文化遗产","examples":["The museum protects the region's cultural heritage.","Traditional crafts are an important part of our heritage."],"tip":"“Heritage” often refers to cultural or historical things inherited from earlier generations.","course":"en","breakdown":"The traditions, achievements, buildings and cultural features passed down from earlier generations.","related":"legacy;inheritance","categories":["History & Culture"],"senses":[{"part":"noun","definition":"The traditions, achievements, buildings and cultural features passed down from earlier generations.","definitionZh":"遗产；文化遗产","examples":["The museum protects the region's cultural heritage.","Traditional crafts are an important part of our heritage."]}]},{"word":"holiday","part":"noun","phonetic":"/ˈhɑːləˌdeɪ/","definition":"A period when someone does not work or study, often spent relaxing or travelling; or a special day of celebration.","definitionZh":"假期；节日","examples":["We are going on holiday in December.","The school is closed for the public holiday."],"tip":"British English often uses “on holiday”; American English commonly uses “on vacation.”","course":"en","breakdown":"A period when someone does not work or study, often spent relaxing or travelling; or a special day of celebration.","related":"vacation;break","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A period when someone does not work or study, often spent relaxing or travelling; or a special day of celebration.","definitionZh":"假期；节日","examples":["We are going on holiday in December.","The school is closed for the public holiday."]}]},{"word":"language","part":"noun","phonetic":"/ˈlæŋɡwɪdʒ/","definition":"A system of words, sounds or signs used by people to communicate.","definitionZh":"语言","examples":["English is the main language used in the class.","Learning a new language takes regular practice."],"tip":"“Language” can refer to a spoken, written or signed system of communication.","course":"en","breakdown":"A system of words, sounds or signs used by people to communicate.","related":"speech;tongue","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A system of words, sounds or signs used by people to communicate.","definitionZh":"语言","examples":["English is the main language used in the class.","Learning a new language takes regular practice."]}]},{"word":"legend","part":"noun","phonetic":"/ˈledʒənd/","definition":"A traditional story, sometimes based on real people or events, that may include extraordinary or supernatural details.","definitionZh":"传说；传奇人物","examples":["The village has a legend about a hidden treasure.","She is a local legend in the world of football."],"tip":"A legend is a traditional story; a myth often explains beliefs about the world or gods.","course":"en","breakdown":"A traditional story, sometimes based on real people or events, that may include extraordinary or supernatural details.","related":"folktale;myth","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A traditional story, sometimes based on real people or events, that may include extraordinary or supernatural details.","definitionZh":"传说；传奇人物","examples":["The village has a legend about a hidden treasure.","She is a local legend in the world of football."]}]},{"word":"literature","part":"noun","phonetic":"/ˈlɪtərətʃər/","definition":"Written works, especially those valued for artistic quality, such as novels, poems and plays.","definitionZh":"文学；文献","examples":["She studies English literature at university.","The library has a large collection of children's literature."],"tip":"“Literature” is usually uncountable when referring to written works as a field or body of writing.","course":"en","breakdown":"Written works, especially those valued for artistic quality, such as novels, poems and plays.","related":"writing;fiction","categories":["History & Culture"],"senses":[{"part":"noun","definition":"Written works, especially those valued for artistic quality, such as novels, poems and plays.","definitionZh":"文学；文献","examples":["She studies English literature at university.","The library has a large collection of children's literature."]}]},{"word":"monument","part":"noun","phonetic":"/ˈmɑːnjəmənt/","definition":"A building, statue or other structure created to remember a person or important event.","definitionZh":"纪念碑；纪念建筑","examples":["The monument honours people who served in the war.","Tourists gathered around the ancient monument."],"tip":"A monument is built to preserve memory; a memorial can be a structure, event or other form of remembrance.","course":"en","breakdown":"A building, statue or other structure created to remember a person or important event.","related":"memorial;statue","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A building, statue or other structure created to remember a person or important event.","definitionZh":"纪念碑；纪念建筑","examples":["The monument honours people who served in the war.","Tourists gathered around the ancient monument."]}]},{"word":"nation","part":"noun","phonetic":"/ˈneɪʃən/","definition":"A country or large group of people with a shared identity, history or government.","definitionZh":"国家；民族","examples":["The nation celebrated its independence day.","The agreement was signed by leaders from several nations."],"tip":"“Nation” can refer to a country or a people with a shared identity; “nationality” refers to legal or cultural belonging.","course":"en","breakdown":"A country or large group of people with a shared identity, history or government.","related":"country;people","categories":["History & Culture"],"senses":[{"part":"noun","definition":"A country or large group of people with a shared identity, history or government.","definitionZh":"国家；民族","examples":["The nation celebrated its independence day.","The agreement was signed by leaders from several nations."]}]},{"word":"channel","part":"noun / verb","phonetic":"/ˈtʃænəl/","definition":"A route through which water, information or signals can pass; or to direct something through a particular route.","definitionZh":"频道；渠道；海峡；引导","examples":["The documentary is on a different television channel.","The company uses social media to channel customer feedback."],"tip":"“Channel” can refer to a TV station, communication route or narrow waterway; context determines the meaning.","course":"en","breakdown":"A route through which water, information or signals can pass; or to direct something through a particular route.","related":"station;route","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A route through which water, information or signals can pass","definitionZh":"频道；渠道；海峡","examples":["The documentary is on a different television channel."]},{"part":"verb","definition":"to direct something through a particular route.","definitionZh":"引导","examples":["The company uses social media to channel customer feedback."]}]},{"word":"chip","part":"noun / verb","phonetic":"/tʃɪp/","definition":"A small piece broken from a larger object; a thin slice of food; or a tiny electronic circuit.","definitionZh":"碎片；薯片；芯片","examples":["A chip of paint came off the wall.","The new phone uses a more powerful computer chip."],"tip":"“Chip” has several common meanings, including a small piece, a snack and an electronic component.","course":"en","breakdown":"A small piece broken from a larger object; a thin slice of food; or a tiny electronic circuit.","related":"fragment;microchip","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A small piece broken from a larger object; a thin slice of food; or a tiny electronic circuit.","definitionZh":"碎片；薯片；芯片","examples":["A chip of paint came off the wall.","The new phone uses a more powerful computer chip."]},{"part":"verb","definition":"To break a small piece off something, or to become damaged in this way.","definitionZh":"削下；使缺损；崩掉一小块","examples":["Be careful not to chip the edge of the glass."]}]},{"word":"click","part":"verb / noun","phonetic":"/klɪk/","definition":"To press and release a button on a mouse or screen; or the short sound made by that action.","definitionZh":"点击；咔哒声","examples":["Click the link to open the article.","I heard a click when the door locked."],"tip":"“Click on” is common before a link or button; “click with someone” means get along well.","course":"en","breakdown":"To press and release a button on a mouse or screen; or the short sound made by that action.","related":"tap;press","categories":["Science & Technology"],"senses":[{"part":"verb","definition":"To press and release a button on a mouse or screen.","definitionZh":"点击；按下鼠标或屏幕按钮","examples":["Click the link to open the article."]},{"part":"noun","definition":"A short, sharp sound made by pressing or moving something.","definitionZh":"咔哒声；点击声","examples":["I heard a click when the door locked."]}]},{"word":"engine","part":"noun","phonetic":"/ˈendʒɪn/","definition":"A machine that uses energy to produce movement or power, especially in a vehicle.","definitionZh":"发动机；引擎","examples":["The car engine needs to be checked.","The search engine found several useful pages."],"tip":"An engine produces power or movement; a motor is a related term often used for smaller machines or electric devices.","course":"en","breakdown":"A machine that uses energy to produce movement or power, especially in a vehicle.","related":"motor;power unit","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A machine that uses energy to produce movement or power, especially in a vehicle.","definitionZh":"发动机；引擎","examples":["The car engine needs to be checked.","The search engine found several useful pages."]}]},{"word":"hardware","part":"noun","phonetic":"/ˈhɑːrdwer/","definition":"The physical parts of a computer or electronic system, rather than the programmes it uses.","definitionZh":"硬件","examples":["The new software requires better computer hardware.","The technician replaced the damaged hardware."],"tip":"“Hardware” is usually uncountable and refers to physical equipment; “software” refers to programmes and instructions.","course":"en","breakdown":"The physical parts of a computer or electronic system, rather than the programmes it uses.","related":"equipment;components","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"The physical parts of a computer or electronic system, rather than the programmes it uses.","definitionZh":"硬件","examples":["The new software requires better computer hardware.","The technician replaced the damaged hardware."]}]},{"word":"machine","part":"noun / verb","phonetic":"/məˈʃiːn/","definition":"A device with moving parts that uses power to perform work; or to make something using machinery.","definitionZh":"机器；机械；用机器加工","examples":["The machine prints labels automatically.","The factory machines metal parts for vehicles."],"tip":"A machine performs work; “machinery” is the uncountable term for machines considered as a group.","course":"en","breakdown":"A device with moving parts that uses power to perform work; or to make something using machinery.","related":"device;equipment","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A device with moving parts that uses power to perform work.","definitionZh":"机器；机械装置","examples":["The machine prints labels automatically."]},{"part":"verb","definition":"To make or shape something by using a machine.","definitionZh":"用机器加工；机械切削","examples":["The factory machines metal parts for vehicles."]}]},{"word":"online","part":"adjective / adverb","phonetic":"/ˌɑːnˈlaɪn/","definition":"Connected to or available through the internet.","definitionZh":"在线的；联网的","examples":["You can book the tickets online.","The online meeting starts at three."],"tip":"“Online” is commonly used for services, communication and activities accessed through the internet.","course":"en","breakdown":"Connected to or available through the internet.","related":"connected;internet-based","categories":["Science & Technology"],"senses":[{"part":"adjective","definition":"Connected to or available through the internet.","definitionZh":"在线的；联网的","examples":["The online meeting starts at three."]},{"part":"adverb","definition":"Using or through the internet.","definitionZh":"在线；通过网络","examples":["You can book the tickets online."]}]},{"word":"program","part":"noun / verb","phonetic":"/ˈproʊɡræm/","definition":"A set of instructions that a computer follows; or to give a device instructions to perform tasks.","definitionZh":"程序；计划；编程","examples":["The program helps students practise vocabulary.","She learned to program a small robot."],"tip":"“Program” is the American spelling; British English often uses “programme” for events or broadcasts, but “program” is common in computing.","course":"en","breakdown":"A set of instructions that a computer follows; or to give a device instructions to perform tasks.","related":"software;application","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A set of instructions that a computer follows","definitionZh":"程序；计划","examples":["The program helps students practise vocabulary."]},{"part":"verb","definition":"to give a device instructions to perform tasks.","definitionZh":"编程","examples":["She learned to program a small robot."]}]},{"word":"smartphone","part":"noun","phonetic":"/ˈsmɑːrtfoʊn/","definition":"A mobile phone that can run applications and connect to the internet like a small computer.","definitionZh":"智能手机","examples":["He uses his smartphone to take photographs.","The app works on most modern smartphones."],"tip":"A smartphone combines phone functions with computer features such as apps, web access and a touchscreen.","course":"en","breakdown":"A mobile phone that can run applications and connect to the internet like a small computer.","related":"mobile phone;handset","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A mobile phone that can run applications and connect to the internet like a small computer.","definitionZh":"智能手机","examples":["He uses his smartphone to take photographs.","The app works on most modern smartphones."]}]},{"word":"social media","part":"noun","phonetic":"/ˌsoʊʃəl ˈmiːdiə/","definition":"Websites and applications that let users create content, share information and communicate with others.","definitionZh":"社交媒体","examples":["Many artists share their work on social media.","The school published the announcement through its social-media accounts."],"tip":"“Social media” refers to online platforms and services where users create, share and discuss content.","course":"en","breakdown":"Websites and applications that let users create content, share information and communicate with others.","related":"social networks;platforms","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"Websites and applications that let users create content, share information and communicate with others.","definitionZh":"社交媒体","examples":["Many artists share their work on social media.","The school published the announcement through its social-media accounts."]}]},{"word":"speaker","part":"noun","phonetic":"/ˈspiːkər/","definition":"A person who speaks to an audience; or a device that produces sound from an audio signal.","definitionZh":"演讲者；扬声器；音箱","examples":["The speaker answered questions after the talk.","The laptop speakers are not very loud."],"tip":"“Speaker” can mean a person giving a talk or an audio device; context makes the meaning clear.","course":"en","breakdown":"A person who speaks to an audience; or a device that produces sound from an audio signal.","related":"presenter;loudspeaker","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A person who speaks to an audience; or a device that produces sound from an audio signal.","definitionZh":"演讲者；扬声器；音箱","examples":["The speaker answered questions after the talk.","The laptop speakers are not very loud."]}]},{"word":"technology","part":"noun","phonetic":"/tekˈnɑːlədʒi/","definition":"The use of scientific knowledge and tools to create methods, machines and systems for practical purposes.","definitionZh":"技术；科技","examples":["Technology has changed the way people communicate.","The school provides training in digital technology."],"tip":"“Technology” is usually uncountable when referring to the field or tools in general.","course":"en","breakdown":"The use of scientific knowledge and tools to create methods, machines and systems for practical purposes.","related":"tech;engineering","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"The use of scientific knowledge and tools to create methods, machines and systems for practical purposes.","definitionZh":"技术；科技","examples":["Technology has changed the way people communicate.","The school provides training in digital technology."]}]},{"word":"telephone","part":"noun / verb","phonetic":"/ˈtelɪfoʊn/","definition":"A device or system used to speak to someone over a distance; or to call someone.","definitionZh":"电话；打电话","examples":["The office telephone rang during the meeting.","I telephoned the clinic to change my appointment."],"tip":"“Telephone” is more formal than “phone”; it can refer to the device or the act of calling.","course":"en","breakdown":"A device or system used to speak to someone over a distance; or to call someone.","related":"phone;call","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A device or system used to speak to someone over a distance","definitionZh":"电话","examples":["The office telephone rang during the meeting."]},{"part":"verb","definition":"to call someone.","definitionZh":"打电话","examples":["I telephoned the clinic to change my appointment."]}]},{"word":"television","part":"noun","phonetic":"/ˈtelɪvɪʒən/","definition":"A device or system for receiving and showing programmes with sound and moving images.","definitionZh":"电视；电视机；电视节目","examples":["They watched the news on television.","The television in the living room is quite old."],"tip":"“Television” can refer to the device, the medium or the programmes; “TV” is the common abbreviation.","course":"en","breakdown":"A device or system for receiving and showing programmes with sound and moving images.","related":"TV;broadcast","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A device or system for receiving and showing programmes with sound and moving images.","definitionZh":"电视；电视机；电视节目","examples":["They watched the news on television.","The television in the living room is quite old."]}]},{"word":"text message","part":"noun / verb","phonetic":"/ˈtekst ˌmesɪdʒ/","definition":"A short written message sent from one mobile phone or digital device to another; or to send such a message.","definitionZh":"短信；发短信","examples":["I received a text message from the delivery company.","Please text-message me when you arrive."],"tip":"“Text message” is usually written as two words; “text” is a common verb meaning to send one.","course":"en","breakdown":"A short written message sent from one mobile phone or digital device to another; or to send such a message.","related":"SMS;text","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A short written message sent from one mobile phone or digital device to another","definitionZh":"短信","examples":["I received a text message from the delivery company."]},{"part":"verb","definition":"to send such a message.","definitionZh":"发短信","examples":["Please text-message me when you arrive."]}]},{"word":"upload","part":"verb / noun","phonetic":"/ˌʌpˈloʊd/","definition":"To send a file or data from a device to an online service or another computer; or the process or file sent.","definitionZh":"上传；上传内容","examples":["Upload your assignment before midnight.","The video upload failed because the connection was weak."],"tip":"“Upload” means send data to another system; “download” means receive it onto your device.","course":"en","breakdown":"To send a file or data from a device to an online service or another computer; or the process or file sent.","related":"send;transfer","categories":["Science & Technology"],"senses":[{"part":"verb","definition":"To send a file or data from a device to an online service or another computer.","definitionZh":"上传；将文件或数据传送到网络服务","examples":["Upload your assignment before midnight."]},{"part":"noun","definition":"A file or other content that has been uploaded.","definitionZh":"上传的文件；上传内容","examples":["The video upload failed because the connection was weak."]}]},{"word":"video","part":"noun / verb","phonetic":"/ˈvɪdioʊ/","definition":"A recording of moving images, usually with sound; or to record or send images electronically.","definitionZh":"视频；录像；录制视频","examples":["She watched a short video about the solar system.","We video-called our relatives last night."],"tip":"“Video” can refer to a recording or the act of recording; “video call” is a common way to communicate face to face online.","course":"en","breakdown":"A recording of moving images, usually with sound; or to record or send images electronically.","related":"clip;recording","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A recording of moving images, usually with sound","definitionZh":"视频；录像","examples":["She watched a short video about the solar system."]},{"part":"verb","definition":"to record or send images electronically.","definitionZh":"录制视频","examples":["We video-called our relatives last night."]}]},{"word":"website","part":"noun","phonetic":"/ˈwebsaɪt/","definition":"A collection of related pages and information available under one internet address.","definitionZh":"网站","examples":["The school website lists the term dates.","I found the instructions on the official website."],"tip":"A website contains web pages; a web page is one individual page within it.","course":"en","breakdown":"A collection of related pages and information available under one internet address.","related":"site;web page","categories":["Science & Technology"],"senses":[{"part":"noun","definition":"A collection of related pages and information available under one internet address.","definitionZh":"网站","examples":["The school website lists the term dates.","I found the instructions on the official website."]}]},{"word":"wireless","part":"adjective / noun","phonetic":"/ˈwaɪərləs/","definition":"Using radio signals rather than physical wires to send information or power; or a wireless connection or device.","definitionZh":"无线的；无线通信","examples":["The headphones connect to the phone wirelessly.","We use a wireless network at home."],"tip":"“Wireless” describes a connection without a physical cable; Wi-Fi is one common wireless networking technology.","course":"en","breakdown":"Using radio signals rather than physical wires to send information or power; or a wireless connection or device.","related":"Wi-Fi;radio","categories":["Science & Technology"],"senses":[{"part":"adjective","definition":"Using radio signals rather than physical wires to send information or power","definitionZh":"无线的","examples":["The headphones connect to the phone wirelessly."]},{"part":"noun","definition":"a wireless connection or device.","definitionZh":"无线通信","examples":["We use a wireless network at home."]}]},{"word":"crossing","part":"noun","phonetic":"/ˈkrɔːsɪŋ/","definition":"A place where people or vehicles can cross a road, railway or body of water; or the act of crossing.","definitionZh":"交叉口；人行横道；渡口","examples":["Use the pedestrian crossing near the traffic lights.","The ferry crossing takes about twenty minutes."],"tip":"A crossing is a designated place or route across an obstacle; a crosswalk is a common American term for a pedestrian crossing.","course":"en","breakdown":"A place where people or vehicles can cross a road, railway or body of water; or the act of crossing.","related":"crosswalk;intersection","categories":["Places"],"senses":[{"part":"noun","definition":"A place where people or vehicles can cross a road, railway or body of water; or the act of crossing.","definitionZh":"交叉口；人行横道；渡口","examples":["Use the pedestrian crossing near the traffic lights.","The ferry crossing takes about twenty minutes."]}]},{"word":"department store","part":"noun","phonetic":"/dɪˈpɑːrtmənt ˌstɔːr/","definition":"A large shop divided into sections that sell different kinds of products, such as clothes, furniture and cosmetics.","definitionZh":"百货商店","examples":["We bought a suitcase at the department store.","The department store has a café on the top floor."],"tip":"A department store is a large retail shop divided into sections for different types of products.","course":"en","breakdown":"A large shop divided into sections that sell different kinds of products, such as clothes, furniture and cosmetics.","related":"retail store;shop","categories":["Places"],"senses":[{"part":"noun","definition":"A large shop divided into sections that sell different kinds of products, such as clothes, furniture and cosmetics.","definitionZh":"百货商店","examples":["We bought a suitcase at the department store.","The department store has a café on the top floor."]}]},{"word":"dining room","part":"noun","phonetic":"/ˈdaɪnɪŋ ˌruːm/","definition":"A room in a house or building where people sit and eat meals.","definitionZh":"餐厅；饭厅","examples":["The family eats dinner together in the dining room.","We set the table in the dining room."],"tip":"A dining room is used for eating meals; a kitchen is where food is prepared.","course":"en","breakdown":"A room in a house or building where people sit and eat meals.","related":"dining area;meal room","categories":["Places"],"senses":[{"part":"noun","definition":"A room in a house or building where people sit and eat meals.","definitionZh":"餐厅；饭厅","examples":["The family eats dinner together in the dining room.","We set the table in the dining room."]}]},{"word":"driveway","part":"noun","phonetic":"/ˈdraɪvweɪ/","definition":"A private road or short path leading from a street to a house, garage or other building.","definitionZh":"私人车道；入户车道","examples":["Please do not park across the neighbour's driveway.","The children played basketball in the driveway."],"tip":"A driveway connects a property to a road; a pavement or sidewalk is for pedestrians.","course":"en","breakdown":"A private road or short path leading from a street to a house, garage or other building.","related":"access road;entrance","categories":["Places"],"senses":[{"part":"noun","definition":"A private road or short path leading from a street to a house, garage or other building.","definitionZh":"车道；私人 driveway","examples":["Please do not park across the neighbour's driveway.","The children played basketball in the driveway."]}]},{"word":"gate","part":"noun","phonetic":"/ɡeɪt/","definition":"A movable barrier that opens and closes an entrance in a fence or wall; or an airport boarding area.","definitionZh":"大门；栅门；登机口","examples":["Please close the garden gate behind you.","Our flight leaves from gate twelve."],"tip":"“Gate” can mean an entrance barrier or an airport departure point.","course":"en","breakdown":"A movable barrier that opens and closes an entrance in a fence or wall; or an airport boarding area.","related":"entrance;barrier","categories":["Places"],"senses":[{"part":"noun","definition":"A movable barrier that opens and closes an entrance in a fence or wall; or an airport boarding area.","definitionZh":"大门；栅门；登机口","examples":["Please close the garden gate behind you.","Our flight leaves from gate twelve."]}]},{"word":"house","part":"noun / verb","phonetic":"/haʊs/","definition":"A building where people live; or to provide a place for someone or something.","definitionZh":"房子；住宅；安置","examples":["They bought a small house near the park.","The building houses a collection of old maps."],"tip":"As a noun, “house” is a home building; as a verb, it means provide space or accommodation.","course":"en","breakdown":"A building where people live; or to provide a place for someone or something.","related":"home;residence","categories":["Places"],"senses":[{"part":"noun","definition":"A building where people live","definitionZh":"房子；住宅","examples":["They bought a small house near the park."]},{"part":"verb","definition":"to provide a place for someone or something.","definitionZh":"安置","examples":["The building houses a collection of old maps."]}]},{"word":"river","part":"noun","phonetic":"/ˈrɪvər/","definition":"A large natural flow of water that moves across land towards a sea, lake or another river.","definitionZh":"河流；江","examples":["The river flows through the centre of the town.","They crossed the river by boat."],"tip":"A river flows across land; a stream is usually smaller and narrower.","course":"en","breakdown":"A large natural flow of water that moves across land towards a sea, lake or another river.","related":"stream;waterway","categories":["Places"],"senses":[{"part":"noun","definition":"A large natural flow of water that moves across land towards a sea, lake or another river.","definitionZh":"河流；江","examples":["The river flows through the centre of the town.","They crossed the river by boat."]}]},{"word":"road","part":"noun","phonetic":"/roʊd/","definition":"A prepared surface or route for vehicles and people to travel between places.","definitionZh":"道路；公路","examples":["The road was closed because of flooding.","We drove along a narrow mountain road."],"tip":"A road is a route for travel; a street is usually a road within a town or city and may have buildings along it.","course":"en","breakdown":"A prepared surface or route for vehicles and people to travel between places.","related":"street;highway","categories":["Places"],"senses":[{"part":"noun","definition":"A prepared surface or route for vehicles and people to travel between places.","definitionZh":"道路；公路","examples":["The road was closed because of flooding.","We drove along a narrow mountain road."]}]},{"word":"store","part":"noun / verb","phonetic":"/stɔːr/","definition":"A shop where goods are sold; or to keep something for future use.","definitionZh":"商店；储存","examples":["I bought a notebook at the store.","Store the files in a safe location."],"tip":"“Store” is commonly used for a shop in American English; as a verb it means keep something for later use.","course":"en","breakdown":"A shop where goods are sold; or to keep something for future use.","related":"shop;retail outlet","categories":["Places"],"senses":[{"part":"noun","definition":"A shop where goods are sold","definitionZh":"商店","examples":["I bought a notebook at the store."]},{"part":"verb","definition":"to keep something for future use.","definitionZh":"储存","examples":["Store the files in a safe location."]}]},{"word":"street","part":"noun","phonetic":"/striːt/","definition":"A public road in a town or city, usually with buildings along one or both sides.","definitionZh":"街道；大街","examples":["The café is on the next street.","Children were playing in the street."],"tip":"A street is usually within a built-up area; a road is a more general route between places.","course":"en","breakdown":"A public road in a town or city, usually with buildings along one or both sides.","related":"road;avenue","categories":["Places"],"senses":[{"part":"noun","definition":"A public road in a town or city, usually with buildings along one or both sides.","definitionZh":"街道；大街","examples":["The café is on the next street.","Children were playing in the street."]}]},{"word":"studio","part":"noun","phonetic":"/ˈstuːdioʊ/","definition":"A room or building where an artist, photographer, musician or other professional works; or a place where broadcasts or films are made.","definitionZh":"工作室；摄影棚；录音室","examples":["The artist works in a small studio.","The news was recorded in a television studio."],"tip":"A studio is designed for creative work or recording; a workshop is usually used for making or repairing things.","course":"en","breakdown":"A room or building where an artist, photographer, musician or other professional works; or a place where broadcasts or films are made.","related":"workroom;recording space","categories":["Places"],"senses":[{"part":"noun","definition":"A room or building where an artist, photographer, musician or other professional works; or a place where broadcasts or films are made.","definitionZh":"工作室；摄影棚；录音室","examples":["The artist works in a small studio.","The news was recorded in a television studio."]}]},{"word":"town","part":"noun","phonetic":"/taʊn/","definition":"A place where people live and work that is usually larger than a village but smaller than a city.","definitionZh":"城镇；市镇","examples":["The town has a busy market square.","We moved to a quiet town near the coast."],"tip":"The distinction between a town and a city varies by country and legal system.","course":"en","breakdown":"A place where people live and work that is usually larger than a village but smaller than a city.","related":"small city;municipality","categories":["Places"],"senses":[{"part":"noun","definition":"A place where people live and work that is usually larger than a village but smaller than a city.","definitionZh":"城镇；市镇","examples":["The town has a busy market square.","We moved to a quiet town near the coast."]}]},{"word":"academy","part":"noun","phonetic":"/əˈkædəmi/","definition":"A school or institution that provides specialised education or training; or an organisation for promoting an art or science.","definitionZh":"学院；专科学院；学会","examples":["She studied animation at an arts academy.","The academy offers evening language classes."],"tip":"An academy may be an educational institution or a professional society.","course":"en","breakdown":"A school or institution that provides specialised education or training; or an organisation for promoting an art or science.","related":"school;institute","categories":["Education"],"senses":[{"part":"noun","definition":"A school or institution that provides specialised education or training; or an organisation for promoting an art or science.","definitionZh":"学院；专科学院；学会","examples":["She studied animation at an arts academy.","The academy offers evening language classes."]}]},{"word":"alphabet","part":"noun","phonetic":"/ˈælfəbet/","definition":"A set of letters used in writing a language, arranged in a fixed order.","definitionZh":"字母表","examples":["Children learn the alphabet before they start reading.","The English alphabet has twenty-six letters."],"tip":"An alphabet is a writing system based on letters; some languages use other writing systems.","course":"en","breakdown":"A set of letters used in writing a language, arranged in a fixed order.","related":"letters;script","categories":["Education"],"senses":[{"part":"noun","definition":"A set of letters used in writing a language, arranged in a fixed order.","definitionZh":"字母表","examples":["Children learn the alphabet before they start reading.","The English alphabet has twenty-six letters."]}]},{"word":"curriculum","part":"noun","phonetic":"/kəˈrɪkjələm/","definition":"The subjects and learning content included in a course or educational programme.","definitionZh":"课程；课程设置","examples":["The school updated its science curriculum.","The curriculum includes both theory and practical work."],"tip":"“Curriculum” is the singular form; the plural is “curricula” or “curriculums.”","course":"en","breakdown":"The subjects and learning content included in a course or educational programme.","related":"syllabus;programme","categories":["Education"],"senses":[{"part":"noun","definition":"The subjects and learning content included in a course or educational programme.","definitionZh":"课程；课程设置","examples":["The school updated its science curriculum.","The curriculum includes both theory and practical work."]}]},{"word":"education","part":"noun","phonetic":"/ˌedʒuˈkeɪʃən/","definition":"The process of teaching and learning, especially in schools, colleges and other institutions.","definitionZh":"教育","examples":["Education can create opportunities for people.","The country invests in public education."],"tip":"“Education” is usually uncountable when referring to the general process or system.","course":"en","breakdown":"The process of teaching and learning, especially in schools, colleges and other institutions.","related":"learning;instruction","categories":["Education"],"senses":[{"part":"noun","definition":"The process of teaching and learning, especially in schools, colleges and other institutions.","definitionZh":"教育","examples":["Education can create opportunities for people.","The country invests in public education."]}]},{"word":"experiment","part":"noun / verb","phonetic":"/ɪkˈsperɪmənt/","definition":"A scientific test carried out to discover or demonstrate something; or to try a new method or idea.","definitionZh":"实验；试验；尝试","examples":["The students carried out an experiment in the laboratory.","The team experimented with different materials."],"tip":"As a noun, an experiment is a test; as a verb, “experiment with” means try something to see what happens.","course":"en","breakdown":"A scientific test carried out to discover or demonstrate something; or to try a new method or idea.","related":"test;trial","categories":["Education"],"senses":[{"part":"noun","definition":"A scientific test carried out to discover or demonstrate something","definitionZh":"实验；试验","examples":["The students carried out an experiment in the laboratory."]},{"part":"verb","definition":"to try a new method or idea.","definitionZh":"尝试","examples":["The team experimented with different materials."]}]},{"word":"instructor","part":"noun","phonetic":"/ɪnˈstrʌktər/","definition":"A person who teaches a practical skill or subject, often in a specialised setting.","definitionZh":"教练；指导员；讲师","examples":["The driving instructor explained the rules clearly.","A swimming instructor helped the children learn safely."],"tip":"An instructor often teaches a practical skill; “teacher” is a broader term used in many settings.","course":"en","breakdown":"A person who teaches a practical skill or subject, often in a specialised setting.","related":"teacher;trainer","categories":["Education"],"senses":[{"part":"noun","definition":"A person who teaches a practical skill or subject, often in a specialised setting.","definitionZh":"教练；指导员；讲师","examples":["The driving instructor explained the rules clearly.","A swimming instructor helped the children learn safely."]}]},{"word":"knowledge","part":"noun","phonetic":"/ˈnɑːlɪdʒ/","definition":"Information, understanding and skills gained through learning or experience.","definitionZh":"知识；学识","examples":["Reading gives us knowledge about the world.","She has a good knowledge of computer graphics."],"tip":"“Knowledge” is uncountable; say “some knowledge” or “a piece of knowledge” only when a specific fact is meant.","course":"en","breakdown":"Information, understanding and skills gained through learning or experience.","related":"understanding;expertise","categories":["Education"],"senses":[{"part":"noun","definition":"Information, understanding and skills gained through learning or experience.","definitionZh":"知识；学识","examples":["Reading gives us knowledge about the world.","She has a good knowledge of computer graphics."]}]},{"word":"mathematics","part":"noun","phonetic":"/ˌmæθəˈmætɪks/","definition":"The study of numbers, quantities, shapes and patterns, including how they relate to one another.","definitionZh":"数学","examples":["Mathematics helps students develop problem-solving skills.","He enjoys mathematics more than history."],"tip":"“Mathematics” is often shortened to “math” in American English and “maths” in British English.","course":"en","breakdown":"The study of numbers, quantities, shapes and patterns, including how they relate to one another.","related":"math;maths","categories":["Education"],"senses":[{"part":"noun","definition":"The study of numbers, quantities, shapes and patterns, including how they relate to one another.","definitionZh":"数学","examples":["Mathematics helps students develop problem-solving skills.","He enjoys mathematics more than history."]}]},{"word":"pupil","part":"noun","phonetic":"/ˈpjuːpəl/","definition":"A person, especially a child, who is taught at a school.","definitionZh":"小学生；学生","examples":["The pupils lined up outside the classroom.","Each pupil received a new workbook."],"tip":"“Pupil” is especially common in British English for schoolchildren; “student” is used more broadly.","course":"en","breakdown":"A person, especially a child, who is taught at a school.","related":"student;learner","categories":["Education"],"senses":[{"part":"noun","definition":"A person, especially a child, who is taught at a school.","definitionZh":"小学生；学生","examples":["The pupils lined up outside the classroom.","Each pupil received a new workbook."]}]},{"word":"semester","part":"noun","phonetic":"/səˈmestər/","definition":"One of the two main periods into which an academic year is often divided.","definitionZh":"学期","examples":["The new semester begins in September.","She plans to study abroad next semester."],"tip":"A semester usually lasts around half an academic year; some institutions use terms or trimesters instead.","course":"en","breakdown":"One of the two main periods into which an academic year is often divided.","related":"term;academic period","categories":["Education"],"senses":[{"part":"noun","definition":"One of the two main periods into which an academic year is often divided.","definitionZh":"学期","examples":["The new semester begins in September.","She plans to study abroad next semester."]}]},{"word":"spelling","part":"noun","phonetic":"/ˈspelɪŋ/","definition":"The way a word is written using the correct letters in the correct order.","definitionZh":"拼写；拼法","examples":["The spelling of this word is difficult to remember.","The teacher checked the students' spelling."],"tip":"Spelling concerns written letters; pronunciation concerns how a word is spoken.","course":"en","breakdown":"The way a word is written using the correct letters in the correct order.","related":"orthography;written form","categories":["Education"],"senses":[{"part":"noun","definition":"The way a word is written using the correct letters in the correct order.","definitionZh":"拼写；拼法","examples":["The spelling of this word is difficult to remember.","The teacher checked the students' spelling."]}]}];
